/* Liberation Serif — the same open serif the physical Homm3 board game (Heegu's
   Homm3BG kit) sets its cards in. Bundled locally (public/fonts) under the SIL
   Open Font License; see fonts/Liberation-license.txt. Used as the display face
   for the fan-made menus so the UI reads like an olden-era Heroes screen. */
@font-face {
  font-family: "Liberation Serif";
  src: url("/fonts/LiberationSerif-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* -------------------------------------------------------------------------
   2026 cinematic main menu: full-quality ping-pong video, logo on the left,
   one compact stateful button stack on the right. Scoped so every other
   MenuShell screen keeps its established layout and chrome.
--------------------------------------------------------------------------- */

.mainMenuShell .menuShellBackdropVideo {
  filter: none;
  animation: none;
  transform: none;
  object-position: center center;
}

.mainMenuShell .menuShellVignette {
  background:
    linear-gradient(
      90deg,
      rgb(0 0 0 / 8%) 0%,
      transparent 38%,
      transparent 64%,
      rgb(0 0 0 / 14%) 100%
    ),
    linear-gradient(
      180deg,
      rgb(0 0 0 / 8%),
      transparent 18%,
      transparent 82%,
      rgb(0 0 0 / 15%)
    );
}

.mainMenuShell .menuShellContent {
  width: 100%;
  min-height: 0;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: clamp(22px, 5vw, 80px);
  padding: clamp(22px, 4vw, 58px);
  overflow: hidden;
}

.mainMenuShell .menuGameLogo {
  flex: 0 1 52%;
  width: min(690px, 48vw);
  margin: 0;
  filter: drop-shadow(0 7px 2px rgb(0 0 0 / 76%))
    drop-shadow(0 0 22px rgb(255 211 105 / 36%));
}

.mainMenuShell .menuShellPanel.bare {
  flex: 0 0 min(570px, 43vw);
  width: min(570px, 43vw);
  min-width: 390px;
}

.mainMenuShell .menuGameLogo {
  position: absolute;
  top: clamp(34px, 6vh, 54px);
  left: clamp(52px, 6vw, 86px);
  flex: 0 1 44%;
  width: min(460px, 32vw);
  max-width: 460px;
  transform: none;
}

.mainMenuShell .menuNav {
  width: 100%;
  gap: clamp(6px, 0.85vh, 10px);
}

.mainMenuShell .menuNavButton,
.mainMenuShell .menuNavButton:hover:not(:disabled),
.mainMenuShell .menuNavButton:disabled {
  isolation: isolate;
  min-height: clamp(76px, 11.2vh, 102px);
  overflow: hidden;
  border: 0;
  border-radius: 18px;
  background: transparent;
  box-shadow: 0 8px 15px rgb(0 0 0 / 48%);
  transform: none;
  transition:
    filter 150ms ease,
    transform 150ms ease;
}

.mainMenuShell .menuNavButton::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    90deg,
    transparent 5%,
    rgb(1 10 31 / 12%) 26%,
    rgb(1 8 26 / 42%) 50%,
    rgb(1 10 31 / 12%) 74%,
    transparent 95%
  );
  pointer-events: none;
}

.mainMenuShell .menuNavButton:hover:not(:disabled),
.mainMenuShell .menuNavButton:focus-visible {
  filter: brightness(1.13) saturate(1.08);
  transform: translateX(-5px) scale(1.012);
}

.mainMenuShell .menuNavIcon {
  top: 50%;
  left: 50%;
  z-index: 0;
  width: auto;
  height: 132%;
  opacity: 0.9;
  object-fit: contain;
  filter: drop-shadow(0 4px 5px rgb(0 0 0 / 78%)) saturate(1.08);
}

.mainMenuShell .menuNavHeroArt {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}

.mainMenuShell .menuNavButtonHeroes::before {
  background: linear-gradient(
    90deg,
    rgb(0 5 18 / 5%),
    rgb(0 5 18 / 50%) 50%,
    rgb(0 5 18 / 5%)
  );
}

.mainMenuShell .menuNavText {
  z-index: 3;
}

.mainMenuShell .menuNavLabel {
  color: #ffe9a2;
  background: linear-gradient(
    180deg,
    #fffbdc 0%,
    #ffe49a 26%,
    #e5ac42 62%,
    #9b5e19 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  font-family: var(--font-heroic), Georgia, "Times New Roman", serif;
  font-size: clamp(22px, 2.2vw, 34px);
  font-weight: 900;
  letter-spacing: 0.075em;
  line-height: 0.95;
  -webkit-text-stroke: 0.45px #4b2707;
  filter: drop-shadow(0 2px 0 #311600) drop-shadow(0 4px 5px #000)
    drop-shadow(0 0 7px #000);
  white-space: nowrap;
}

.mainMenuShell .menuNavLogout {
  min-height: clamp(64px, 8.8vh, 78px);
}

.mainMenuShell .menuShellFooter {
  position: absolute;
  right: 20px;
  bottom: max(10px, env(safe-area-inset-bottom));
  left: 20px;
  color: #f3deb1;
  text-shadow:
    0 2px 4px #000,
    0 0 8px #000;
}

@media (max-width: 820px) {
  .mainMenuShell .menuShellContent {
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    padding: 12px 14px 34px;
  }

  .mainMenuShell .menuGameLogo {
    flex: 0 0 auto;
    width: min(390px, 78vw);
    max-height: 23vh;
    object-fit: contain;
  }

  .mainMenuShell .menuShellPanel.bare {
    flex: 0 1 auto;
    width: min(500px, 94vw);
    min-width: 0;
  }

  .mainMenuShell .menuNavButton,
  .mainMenuShell .menuNavButton:hover:not(:disabled),
  .mainMenuShell .menuNavButton:disabled {
    min-height: clamp(58px, 9.5vh, 76px);
  }

  .mainMenuShell .menuNavLabel {
    font-size: clamp(19px, 5.8vw, 28px);
  }
}

@media (max-height: 650px) and (min-width: 821px) {
  .mainMenuShell .menuNavButton,
  .mainMenuShell .menuNavButton:hover:not(:disabled),
  .mainMenuShell .menuNavButton:disabled {
    min-height: 72px;
  }

  .mainMenuShell .menuNavLabel {
    font-size: 25px;
  }
}

/* NOTE: the reduced-motion rule for the video backdrop lives at the END of the
   menu CSS (beside the second .mainMenuShell block), NOT here — a media query
   adds no specificity, so an equally-specific declaration later in the file
   would silently defeat it. See "reduced motion → the still poster art". */
@font-face {
  font-family: "Liberation Serif";
  src: url("/fonts/LiberationSerif-Bold.ttf") format("truetype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Liberation Serif";
  src: url("/fonts/LiberationSerif-Italic.ttf") format("truetype");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: "Liberation Serif";
  src: url("/fonts/LiberationSerif-BoldItalic.ttf") format("truetype");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}

:root {
  color-scheme: dark;
  /* Olden-era Heroes display serif for menus/greeting/headings. */
  --font-heroic: "Liberation Serif", Georgia, "Times New Roman", serif;
  --bg: #0d0f10;
  --surface: #17191b;
  --surface-2: #202326;
  --line: #393c3f;
  --line-strong: #686052;
  --text: #f3efe4;
  --muted: #b9b2a4;
  --gold: #d5a84f;
  --gold-dark: #5e4620;
  --red: #a65348;
  --red-dark: #4d2523;
  --green: #5d8764;
  --blue: #557f99;
  --violet: #786fa6;
  --ink: #11110f;
  --focus: #f7cf6e;
  --felt: #1d3024;
  --wood-1: #4d3119;
  --wood-2: #2a1a0e;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background:
    radial-gradient(circle at 18% 8%, rgb(93 135 100 / 14%), transparent 26rem),
    radial-gradient(
      circle at 84% 14%,
      rgb(120 111 166 / 12%),
      transparent 24rem
    ),
    linear-gradient(160deg, #171310 0%, #221a12 46%, #14171a 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

a {
  color: inherit;
}

button {
  font: inherit;
}

.appShell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.topBar {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 18px;
  border-bottom: 1px solid var(--line);
  background: rgb(13 15 16 / 94%);
  backdrop-filter: blur(10px);
}

.brand {
  color: var(--gold);
  font-weight: 800;
  text-decoration: none;
}

.navLinks {
  display: flex;
  gap: 14px;
  color: var(--muted);
  font-size: 13px;
}

.navLinks a {
  text-decoration: none;
}

.navLinks a:hover {
  color: var(--text);
}

.footerNotice {
  margin-top: auto;
  padding: 9px 18px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  background: rgb(13 15 16 / 94%);
}

/* ---------- table layout ---------- */

.tableRoot {
  width: min(1680px, 100%);
  margin: 0 auto;
  padding: 10px 14px 16px;
  display: grid;
  gap: 10px;
}

.tableTopRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 250px;
  gap: 10px;
  align-items: start;
}

/* The combat board fills the row now that the shared-deck rail is gone: a wide
   board on the left and a roomier right rail for the unit card definition. */
.tableMidRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 10px;
  align-items: start;
}

/* During combat deployment the bigger board gets a dedicated deploy sidebar to
   its right; the right rail (inspect/commands) still trails it. */
.tableMidRow.withPlacement {
  grid-template-columns: minmax(0, 1fr) 248px 320px;
}

.tableSeatRow {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  min-height: 0;
}

/* ---------- shared chrome ---------- */

.errorBanner,
.targetBanner {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 40px;
  padding: 8px 12px;
  border-radius: 7px;
  border: 1px solid var(--line);
}

.errorBanner {
  border-color: var(--red);
  background: rgb(77 37 35 / 95%);
  flex-wrap: wrap;
}

/* Room-server version skew: louder than a rules error and self-explaining
   (see src/engine/version.ts). Amber so it reads as "fix your deploy", not a
   per-action rules rejection. */
.serverStaleWarning {
  flex: 1 1 100%;
  font-weight: 600;
  color: #ffd9a8;
}

.serverStaleWarning code {
  padding: 1px 5px;
  border-radius: 4px;
  background: rgb(0 0 0 / 35%);
  font-size: 0.92em;
}

.serverStaleWarning small {
  opacity: 0.7;
  font-weight: 400;
}

.targetBanner {
  border-color: var(--blue);
  background: rgb(38 68 83 / 95%);
}

.targetBanner button {
  margin-left: auto;
  padding: 4px 10px;
  border: 1px solid rgb(243 239 228 / 30%);
  border-radius: 5px;
  color: var(--text);
  background: rgb(13 15 16 / 40%);
  cursor: pointer;
}

.cardFaceFallback {
  display: grid;
  place-items: center;
  padding: 6px;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 6px;
  background: #101212;
  font-size: 11px;
  text-align: center;
  overflow-wrap: anywhere;
}

/* ---------- opponent seat ---------- */

.opponentBar {
  display: grid;
  gap: 8px;
}

.opponentSeat {
  display: grid;
  grid-template-columns: minmax(150px, 190px) minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: linear-gradient(180deg, rgb(34 28 20 / 92%), rgb(20 18 14 / 94%));
  box-shadow: 0 10px 26px rgb(0 0 0 / 30%);
}

.seatBadge {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.seatBadge strong {
  font-size: 13px;
}

/* Person-first seat nameplate (opponent bar + own dock): faction dot, person
   name, hero · town second line. Shared so every seat reads the same way. */
.seatWho {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.seatFactionDot {
  flex: 0 0 auto;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  box-shadow:
    0 0 0 1px rgb(0 0 0 / 45%),
    0 0 6px rgb(0 0 0 / 35%);
}

.seatWhoText {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.seatWhoText strong {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seatHostCrown {
  color: var(--gold);
  flex: 0 0 auto;
}

.seatPick {
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.01em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Co-op (step 6): who is at this seat — a computer, or a human on your side.
   Two tiny chips reusing the seat plate's own type scale; no new system. */
.seatControllerTag,
.seatAllyTag {
  border: 1px solid rgba(176, 141, 47, 0.5);
  border-radius: 999px;
  flex: 0 0 auto;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1px 6px;
  text-transform: uppercase;
  white-space: nowrap;
}

.seatControllerTag {
  background: rgba(255, 255, 255, 0.06);
  color: var(--muted);
}

.seatAllyTag {
  align-self: flex-start;
  background: rgba(96, 176, 112, 0.16);
  border-color: rgba(96, 176, 112, 0.55);
  color: #8fd6a2;
}

.seatMetrics {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
}

.seatMetrics > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.opponentHand {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 56px;
}

.cardBack {
  display: grid;
  place-items: center;
  aspect-ratio: 5 / 7;
  border-radius: 5px;
  border: 1px solid rgb(213 168 79 / 60%);
  color: rgb(213 168 79 / 85%);
  background:
    radial-gradient(circle at 50% 42%, rgb(213 168 79 / 26%), transparent 62%),
    repeating-linear-gradient(45deg, #232a3c 0 6px, #1b2130 6px 12px);
  box-shadow: 0 4px 8px rgb(0 0 0 / 38%);
  font-size: 10px;
  font-weight: 800;
}

.opponentCardBack {
  width: 38px;
  margin-right: -22px;
  transform: rotate(180deg);
}

.opponentHand .handCount {
  margin-left: 34px;
  color: var(--muted);
  font-size: 12px;
}

.seatPiles {
  display: flex;
  gap: 10px;
}

.opponentCardStats {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  font-size: 9px;
}

.opponentCardStats > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 20px;
  padding: 2px 6px;
  border: 1px solid rgb(213 168 79 / 22%);
  border-radius: 99px;
  color: var(--muted);
  background: rgb(10 9 7 / 38%);
  white-space: nowrap;
}

.opponentCardStats strong {
  color: var(--text);
  font-size: 10px;
}

/* ---------- piles ---------- */

.pileSpot {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 3px;
}

.pileSpot .pileCard {
  width: 44px;
  aspect-ratio: 5 / 7;
  border-radius: 5px;
}

.pileSpot.tall .pileCard {
  width: 64px;
}

.pileCard.faceUp {
  object-fit: cover;
  border: 1px solid rgb(243 239 228 / 25%);
  background: #0a0b0b;
  box-shadow: 0 4px 8px rgb(0 0 0 / 38%);
}

.pileCard.emptyPile {
  border: 1px dashed rgb(243 239 228 / 22%);
  background: rgb(13 15 16 / 30%);
}

.pileSpot > span {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 20px;
  padding: 1px 5px;
  border-radius: 99px;
  border: 1px solid rgb(213 168 79 / 60%);
  color: var(--ink);
  background: var(--gold);
  font-size: 11px;
  font-weight: 800;
  text-align: center;
}

.pileSpot small {
  color: var(--muted);
  font-size: 10px;
  text-transform: uppercase;
}

/* ---------- table menu ---------- */

.tableMenu {
  display: grid;
  gap: 6px;
  align-content: start;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgb(23 25 27 / 92%);
}

.menuRow {
  display: flex;
  gap: 6px;
}

.seatSwitch button {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
}

.seatSwitch button.selected {
  border-color: var(--gold);
  color: var(--ink);
  background: var(--gold);
}

.roomRow input {
  flex: 1;
  min-width: 0;
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  background: rgb(13 15 16 / 44%);
  font-size: 12px;
}

.roomRow button {
  display: grid;
  place-items: center;
  width: 36px;
  border: 1px solid rgb(213 168 79 / 54%);
  border-radius: 6px;
  color: var(--ink);
  background: var(--gold);
  cursor: pointer;
}

.statusRow {
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 11px;
}

.statusRow span {
  font-weight: 700;
  color: var(--text);
}

/* Connection-quality chip (RTT to the room server), beside the sync status. */
.connectionQualityChip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 7px;
  border: 1px solid rgb(243 239 228 / 14%);
  border-radius: 99px;
  background: rgb(13 15 16 / 40%);
  font-size: 10px;
  font-weight: 400;
  color: var(--muted);
  cursor: help;
}

.connectionQualityChip .qualityDot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.connectionQualityChip.quality-good .qualityDot {
  background: #4f9a5c;
}

.connectionQualityChip.quality-fair .qualityDot {
  background: #c9a23a;
}

.connectionQualityChip.quality-poor .qualityDot {
  background: #b0503f;
}

/* ------------------------------------------------------------------ */
/* Room membership panel (host / seats / observers)                    */
/* ------------------------------------------------------------------ */

.seatLocked {
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  flex-wrap: wrap;
}

/* Self-serve seat claim in a hosted/closed room (top menu) + the "Play as X"
   jump on the waiting strip: both let whoever must act reach their own seat. */
.seatClaimButton,
.promptSwitchSeat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  font: inherit;
  font-size: 11.5px;
  font-weight: 700;
  border-radius: 6px;
  border: 1px solid #ffe9b0;
  background: linear-gradient(180deg, #f6d27a, #d3a247);
  color: #1a1105;
  cursor: pointer;
}

.seatClaimButton.ghost {
  border-color: rgba(140, 110, 65, 0.6);
  background: rgba(20, 14, 9, 0.8);
  color: #e8d3a8;
}

.seatClaimButton:hover,
.promptSwitchSeat:hover {
  filter: brightness(1.06);
}

.seatClaimHint {
  font-weight: 500;
  font-style: italic;
  opacity: 0.85;
}

.promptSwitchSeat {
  margin-left: 8px;
}

.roomPanel {
  display: grid;
  gap: 6px;
}

.roomToggle {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-2);
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.roomToggle.open {
  border-color: var(--gold);
}

.roomToggleMeta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  color: var(--muted);
  font-weight: 600;
  font-size: 11px;
}

.roomBody {
  display: grid;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgb(13 15 16 / 55%);
}

.roomInvite,
.roomNameRow,
.roomModeRow {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}

.roomInvite input,
.roomNameRow input {
  flex: 1;
  min-width: 0;
  min-height: 30px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgb(13 15 16 / 50%);
  color: var(--text);
  font-size: 12px;
}

.roomModeNote {
  flex: 1;
  min-width: 140px;
  color: var(--muted);
  font-size: 11px;
}

.roomRosterStatus {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.roomMembers {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 5px;
}

.roomMember {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-2);
  font-size: 12px;
}

.roomMember.guest {
  border-style: dashed;
}

.roomMember.away {
  opacity: 0.72;
}

.roomMemberLiveDot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--muted);
}

.roomMemberLiveDot.on {
  background: #57c47a;
  box-shadow: 0 0 5px rgb(87 196 122 / 70%);
}

.roomMemberLiveDot.afk {
  background: #d5a84f;
  box-shadow: 0 0 5px rgb(213 168 79 / 55%);
}

.roomMemberVerified {
  color: var(--gold);
  flex: none;
}

.roomMemberPresence {
  margin-left: 4px;
  padding: 0 5px;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: lowercase;
}

.roomMemberPresence.online {
  border-color: rgb(87 196 122 / 45%);
  color: #7ed69a;
}

.roomMemberPresence.afk {
  border-color: rgb(213 168 79 / 45%);
  color: var(--gold);
}

.roomMemberPresence.away {
  border-color: var(--line);
  color: var(--muted);
}

.roomMemberName {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 700;
  color: var(--text);
}

.roomMemberName em {
  color: var(--muted);
  font-weight: 600;
  font-style: normal;
}

/* Person + their hero·town pick, stacked, in a room roster row. */
.roomMemberWho {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.roomMemberPerson {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}

.roomMemberPick {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

/* Verified members' names (and Hall of Fame rows) open the public profile. */
.roomMemberProfileLink,
.hallOfFameName,
.profileNameLink {
  color: inherit;
  text-decoration: underline dotted rgba(214, 168, 96, 0.6);
  text-underline-offset: 2px;
  cursor: pointer;
}

.roomMemberProfileLink:hover,
.hallOfFameName:hover,
.profileNameLink:hover {
  color: var(--gold);
  text-decoration-style: solid;
}

.roomMemberDot {
  align-self: center;
}

.hostCrown {
  color: var(--gold);
}

.roomSeatSelect {
  margin-left: auto;
  min-height: 28px;
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  color: var(--text);
  font-size: 12px;
}

.roomSeatBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  padding: 2px 8px;
  border: 1px solid rgb(213 168 79 / 45%);
  border-radius: 999px;
  color: var(--gold);
  font-weight: 700;
  font-size: 11px;
}

.roomSeatBadge.observer {
  border-color: var(--line);
  color: var(--muted);
}

.roomMemberActions {
  display: inline-flex;
  gap: 4px;
}

.iconButton {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

.iconButton.danger {
  border-color: var(--red);
  color: var(--red);
}

.roomMemberEmpty {
  color: var(--muted);
  font-size: 12px;
}

.roomLeave {
  justify-self: start;
}

.roomTitleRow {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}

.roomTitleLabel {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.roomTitleRow input {
  flex: 1;
  min-width: 0;
  min-height: 30px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgb(13 15 16 / 50%);
  color: var(--text);
  font-size: 12px;
}

.roomTitleRow input:disabled {
  opacity: 0.6;
}

.roomFooterButtons {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}

.commandButton.danger {
  border-color: var(--red);
  color: var(--red);
}

.roomClose {
  margin-left: auto;
}

.musicToggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.musicToggle[aria-pressed="true"] {
  border-color: var(--gold);
  color: var(--gold);
}

.musicToggle[aria-pressed="false"] {
  color: var(--muted);
}

/* Icon-only round form (the main menu's corner switch). */
.musicToggle.compact {
  gap: 0;
  justify-content: center;
  width: 34px;
  min-height: 34px;
  padding: 0;
  border-radius: 50%;
}

/* Pinned to the main menu's top-right corner, over the cinematic backdrop.
   `top` clears the Next DEV-TOOLS badge, which next.config.ts pins to the exact
   top-right corner (dev-only, but it swallows clicks landing under it). */
.mainMenuShell .menuMusicToggle {
  position: fixed;
  top: 54px;
  right: 14px;
  z-index: 30;
  border-color: rgb(214 178 94 / 55%);
  background: rgb(10 13 23 / 62%);
  box-shadow: 0 4px 12px rgb(0 0 0 / 45%);
}

.mainMenuShell .menuMusicToggle:hover {
  border-color: rgb(240 206 120 / 90%);
  filter: brightness(1.12);
}

/* ---------- combat card strip (top) ---------- */

/* Everything card-related stacks here: each opponent's hand/deck/discard
   (OpponentBar) above the viewer's own dock + permanents + playable hand
   (a reused .tableSeatRow). Card-flight animations land in this strip. */
.combatCardStrip {
  display: grid;
  gap: 10px;
  align-content: start;
  min-width: 0;
}

.combatOpponentRow {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: stretch;
  gap: 6px;
  min-width: 0;
}

.combatOpponentRow .opponentInfoDock.combat {
  align-content: center;
  justify-content: center;
  padding: 4px 6px;
}

.combatOpponentRow .opponentInfoDockLabel {
  font-size: 0;
}

.combatOpponentRow .opponentInfoDockLabel svg {
  width: 15px;
  height: 15px;
}

.combatOpponentRow .opponentInfoBtn {
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  overflow: hidden;
  font-size: 0;
}

.combatOpponentRow .opponentInfoBtn .seatFactionDot {
  width: 8px;
  height: 8px;
}

/* Undo is a small utility at the very top of the combat strip, not a full-width
   combat panel. Grid items stretch by default, so opt this one out explicitly. */
.combatUndoMove {
  justify-self: start;
  align-self: start;
  width: max-content;
  min-height: 26px;
  padding: 3px 8px;
  font-size: 10px;
  line-height: 1;
}

/* ---------- deck wells (left rail) ---------- */

.leftRail,
.rightRail {
  display: grid;
  gap: 10px;
  align-content: start;
}

.deckWells {
  display: grid;
  gap: 8px;
}

.deckWell {
  display: grid;
  gap: 7px;
  padding: 8px;
  border: 1px solid rgb(213 168 79 / 26%);
  border-radius: 9px;
  background: linear-gradient(180deg, rgb(32 35 38 / 94%), rgb(18 20 22 / 96%));
}

.deckWell header {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.wellPiles {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.wellSearch {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 28px;
  border: 1px solid rgb(213 168 79 / 54%);
  border-radius: 6px;
  color: var(--ink);
  background: var(--gold);
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.wellSearch:hover {
  filter: brightness(1.08);
}

/* ---------- board ---------- */

.boardColumn {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.initiativeRail {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 5px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgb(23 25 27 / 90%);
  color: var(--muted);
}

.initChip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px 3px 3px;
  border: 1px solid rgb(243 239 228 / 14%);
  border-radius: 99px;
  background: rgb(13 15 16 / 40%);
  font-size: 11px;
  color: var(--text);
}

.initChip strong {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  color: var(--ink);
  background: var(--gold);
  font-size: 10px;
}

.initChip.p1 {
  box-shadow: inset 0 0 0 1px rgb(85 127 153 / 55%);
}

.initChip.p2 {
  box-shadow: inset 0 0 0 1px rgb(166 83 72 / 55%);
}

.initChip.active {
  border-color: var(--gold);
  background: rgb(94 70 32 / 55%);
}

.initChip.done {
  opacity: 0.45;
}

.roundChip {
  margin-left: auto;
  font-size: 11px;
  text-transform: uppercase;
}

.boardFelt {
  position: relative;
  display: grid;
  place-items: center;
  min-width: 0;
  padding: 26px;
  border: 3px solid #8a6129;
  border-radius: 14px;
  background:
    radial-gradient(ellipse at 50% 40%, rgb(72 110 80 / 26%), transparent 70%),
    linear-gradient(
      90deg,
      rgb(61 37 16 / 72%),
      transparent 16%,
      transparent 84%,
      rgb(61 37 16 / 72%)
    ),
    linear-gradient(
      180deg,
      var(--wood-1),
      #b47a37 6%,
      #70481f 94%,
      var(--wood-2)
    );
  /* Layered wooden frame: dark groove, gold inlay, second groove — reads like
     the routed edge of a physical game board. */
  box-shadow:
    inset 0 0 0 3px #3a2412,
    inset 0 0 0 9px rgb(248 223 164 / 24%),
    inset 0 0 0 11px rgb(58 36 18 / 92%),
    inset 0 0 70px rgb(0 0 0 / 26%),
    0 32px 52px rgb(0 0 0 / 44%);
}

/* The combat board art is split into a slim scenery strip and the playable
   5x4 battlefield. The strip is outside the grid so card placement stays exact. */
.battlefieldFrame {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1240px;
  min-width: 0;
  display: grid;
  overflow: hidden;
  border: 2px solid #45301c;
  border-radius: 8px;
  background: #16110a;
  box-shadow:
    inset 0 0 0 2px rgb(238 202 122 / 16%),
    inset 0 0 34px rgb(0 0 0 / 24%),
    0 25px 22px rgb(0 0 0 / 32%);
}

.battlefieldFrame[data-board-art="pve-calamity-classic"],
.battlefieldFrame[data-board-art="pve-calamity-doom"] {
  isolation: isolate;
}

.battlefieldFrame[data-board-art="pve-calamity-classic"] {
  box-shadow:
    0 0 0 1px rgba(157, 130, 220, 0.5),
    0 18px 42px rgba(29, 14, 64, 0.45);
}

.battlefieldFrame[data-board-art="pve-calamity-doom"] {
  box-shadow:
    0 0 0 1px rgba(201, 82, 48, 0.48),
    0 18px 42px rgba(72, 14, 5, 0.5);
}

.pveBattlefieldTitle {
  position: absolute;
  top: 8px;
  left: 12px;
  z-index: 4;
  display: grid;
  gap: 1px;
  padding: 6px 10px 7px;
  border: 1px solid rgba(231, 201, 139, 0.5);
  border-radius: 6px;
  background: linear-gradient(
    135deg,
    rgba(12, 9, 17, 0.88),
    rgba(33, 20, 28, 0.68)
  );
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
  color: #f2e3be;
  pointer-events: none;
  text-shadow: 0 1px 2px #000;
}

.pveBattlefieldTitle > span {
  color: #c6a664;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.pveBattlefieldTitle > strong {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 12px;
  letter-spacing: 0.03em;
}

.battlefieldScenery {
  display: block;
  width: 100%;
  height: auto;
  object-fit: contain;
  border-bottom: 2px solid rgb(26 18 9 / 68%);
  pointer-events: none;
  user-select: none;
  transform-origin: center;
  transition: transform 400ms ease;
}

/* Horizontal battlefield: 5 columns wide (attacker back/front · crossing ·
   defender front/back, left to right) by 4 rows tall. Cells are placed onto
   this grid explicitly from their engine position (see battlefieldCellPlacement
   in board.tsx). */
.battlefield {
  position: relative;
  z-index: 1;
  width: 100%;
  aspect-ratio: 5 / 4;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  grid-template-rows: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  /* Fallback terrain if the art image fails to load: dirt (attacker) on the
     left, the crossing in the middle, grass (defender) on the right. */
  background: linear-gradient(
    90deg,
    #574127 0%,
    #6c5333 28%,
    #59683f 50%,
    #3f7140 72%,
    #2f5a30 100%
  );
  box-shadow: inset 0 0 34px rgb(0 0 0 / 24%);
}

.battlefieldTerrain {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
  user-select: none;
  transform-origin: center;
  z-index: 0;
  transition: transform 400ms ease;
}

/* Printed coordinate guide for rules and Creature Bank instructions that name
   cells as A1–D5. Numbers follow the horizontally mirrored 1–5 lanes; letters
   remain upright down both side edges. Labels sit just inside the board rim so
   they stay legible without covering the unit cards. */
.battlefieldCoordinates {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  grid-template-rows: repeat(4, minmax(0, 1fr));
  pointer-events: none;
}

.battlefieldCoordinate {
  display: grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border: 1px solid rgb(255 228 158 / 68%);
  border-radius: 4px;
  background: rgb(18 13 8 / 78%);
  color: #ffe6aa;
  font-size: clamp(9px, 1.1vw, 13px);
  font-weight: 900;
  line-height: 1;
  text-shadow: 0 1px 2px #000;
  box-shadow: 0 1px 5px rgb(0 0 0 / 55%);
}

.battlefieldCoordinate.top {
  align-self: start;
  justify-self: center;
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}

.battlefieldCoordinate.bottom {
  align-self: end;
  justify-self: center;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.battlefieldCoordinate.left {
  align-self: center;
  justify-self: start;
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}

.battlefieldCoordinate.right {
  align-self: center;
  justify-self: end;
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}

/* Seat-relative view: a horizontal mirror swaps the two armies left↔right
   (done per-cell in board.tsx, so cards stay upright). Mirror only the art
   layers so dirt/grass follow the swapped sides. */
.boardFelt.flipped .battlefieldScenery,
.boardFelt.flipped .battlefieldTerrain {
  transform: scaleX(-1);
}

.battleCell {
  min-width: 0;
  position: relative;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgb(26 18 9 / 60%);
  color: inherit;
  background: transparent;
  /* Engraved grid line: a dark rule with a faint lit edge, so the squares read
     as a printed board over the terrain art. */
  box-shadow:
    inset 0 0 0 1px rgb(255 232 172 / 13%),
    inset 0 0 18px rgb(0 0 0 / 16%);
  outline: 0 solid transparent;
}

button.battleCell {
  font: inherit;
  cursor: pointer;
}

.battleCell.active {
  border-color: #ffe39b;
  outline: 3px solid rgb(255 227 155 / 42%);
  outline-offset: -3px;
  box-shadow:
    inset 0 0 0 1px rgb(255 240 189 / 50%),
    0 0 20px rgb(248 207 110 / 42%);
  z-index: 2;
}

/* Active unit: gold ring + bouncing arrow so every seat sees whose activation it is. */
.boardCard .activeRing {
  position: absolute;
  inset: -4px;
  border-radius: 8px;
  border: 2px solid rgb(255 220 120 / 95%);
  box-shadow:
    0 0 0 2px rgb(120 80 10 / 55%),
    0 0 18px rgb(255 210 90 / 70%);
  pointer-events: none;
  animation: activeRingPulse 1.4s ease-in-out infinite;
}

.boardCard .activeTurnArrow {
  position: absolute;
  top: -26px;
  left: 50%;
  transform: translateX(-50%);
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  color: #ffe39b;
  filter: drop-shadow(0 2px 3px rgb(0 0 0 / 75%));
  pointer-events: none;
  animation: activeTurnArrowBob 0.85s ease-in-out infinite;
  z-index: 3;
}

@keyframes activeRingPulse {
  0%,
  100% {
    opacity: 1;
    box-shadow:
      0 0 0 2px rgb(120 80 10 / 55%),
      0 0 14px rgb(255 210 90 / 55%);
  }
  50% {
    opacity: 0.85;
    box-shadow:
      0 0 0 3px rgb(160 110 20 / 70%),
      0 0 22px rgb(255 220 110 / 85%);
  }
}

@keyframes activeTurnArrowBob {
  0%,
  100% {
    transform: translateX(-50%) translateY(0);
  }
  50% {
    transform: translateX(-50%) translateY(5px);
  }
}

.battleCell.moveTarget::after {
  content: "";
  position: absolute;
  inset: auto;
  width: 14px;
  height: 14px;
  border: 2px solid rgb(255 238 166 / 88%);
  border-radius: 50%;
  background: rgb(51 37 17 / 48%);
  box-shadow:
    0 0 0 3px rgb(74 186 94 / 20%),
    0 0 14px rgb(255 224 122 / 50%);
}

.battleCell.attackTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(166 83 72 / 88%);
  border-radius: 4px;
  box-shadow:
    inset 0 0 18px rgb(166 83 72 / 24%),
    0 0 18px rgb(166 83 72 / 32%);
  pointer-events: none;
}

.battleCell.cardTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(85 127 153 / 92%);
  border-radius: 4px;
  box-shadow:
    inset 0 0 18px rgb(85 127 153 / 30%),
    0 0 18px rgb(85 127 153 / 40%);
  pointer-events: none;
  animation: pulseTarget 1.2s ease-in-out infinite;
}

@keyframes pulseTarget {
  0%,
  100% {
    opacity: 0.65;
  }

  50% {
    opacity: 1;
  }
}

/* Printed-ability target choice (Death Cloud, splash, neutral target tie). */
.battleCell.abilityTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(186 124 220 / 92%);
  border-radius: 4px;
  box-shadow:
    inset 0 0 18px rgb(186 124 220 / 30%),
    0 0 18px rgb(186 124 220 / 42%);
  pointer-events: none;
  animation: pulseTarget 1.2s ease-in-out infinite;
}

/* Tied Initiative order: every stack that may begin this speed slot is a
   direct battlefield pick. Amber distinguishes ordering from attacks (red),
   cards (blue), and printed-ability targets (violet). */
.battleCell.activationOrderTarget::before {
  content: "";
  position: absolute;
  inset: 3px;
  z-index: 5;
  border: 3px solid rgb(255 215 112 / 96%);
  border-radius: 6px;
  box-shadow:
    inset 0 0 24px rgb(255 197 72 / 34%),
    0 0 22px rgb(255 210 92 / 62%);
  pointer-events: none;
  animation: pulseTarget 1.05s ease-in-out infinite;
}

.battleCell.activationOrderTarget:hover,
.battleCell.activationOrderTarget:focus-visible {
  background: rgb(255 215 112 / 16%);
  outline: 3px solid rgb(255 236 174 / 78%);
  outline-offset: -3px;
}

/* First Aid Tent heal: a wounded friendly unit you may mend (green cross glow). */
.battleCell.healTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(110 196 132 / 92%);
  border-radius: 4px;
  box-shadow:
    inset 0 0 18px rgb(110 196 132 / 30%),
    0 0 18px rgb(110 196 132 / 42%);
  pointer-events: none;
  animation: pulseTarget 1.2s ease-in-out infinite;
}

.battleCell.healTarget:hover,
.battleCell.healTarget:focus-visible {
  background: rgb(110 196 132 / 14%);
  outline: 3px solid rgb(154 226 174 / 60%);
  outline-offset: -3px;
}

/* Polish Set Artifacts: the legal units of an ARMED set power (aimed from the
   set-powers window instead of one dock button per unit). Gold, so it reads as
   an artifact effect rather than a spell (purple) or a mend (green). */
.battleCell.artifactSetTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(233 190 104 / 94%);
  border-radius: 4px;
  box-shadow:
    inset 0 0 18px rgb(233 190 104 / 32%),
    0 0 18px rgb(233 190 104 / 46%);
  pointer-events: none;
  animation: pulseTarget 1.2s ease-in-out infinite;
}

.battleCell.artifactSetTarget:hover,
.battleCell.artifactSetTarget:focus-visible {
  background: rgb(233 190 104 / 14%);
  outline: 3px solid rgb(247 216 150 / 62%);
  outline-offset: -3px;
}

/* Deployment drop zones while dragging units from the placement panel. */
.battleCell.dropTarget {
  background: rgb(124 186 110 / 9%);
  box-shadow:
    inset 0 0 0 2px rgb(154 206 134 / 36%),
    inset 0 0 16px rgb(0 0 0 / 10%);
}

.battleCell.dropTarget:hover,
/* The cell directly under the pointer while a unit is being dragged onto the
   board (pointer drag has no :hover, so the drag controller toggles this). */
.battleCell.dropTarget.dropHover {
  background: rgb(154 206 134 / 18%);
}

.battleCell.moveTarget:hover,
.battleCell.moveTarget:focus-visible,
.battleCell.attackTarget:hover,
.battleCell.attackTarget:focus-visible,
.battleCell.cardTarget:hover,
.battleCell.cardTarget:focus-visible,
.battleCell.abilityTarget:hover,
.battleCell.abilityTarget:focus-visible {
  background: rgb(255 237 166 / 11%);
  outline: 3px solid rgb(255 227 155 / 58%);
  outline-offset: -3px;
}

/* --- Repositioning: Tactics swap & Necklace of Swiftness one-space move ----- */

/* First pick: your swappable units glow, inviting a click to select. */
.battleCell.swapSource::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px dashed rgb(120 200 235 / 82%);
  border-radius: 6px;
  box-shadow: inset 0 0 16px rgb(120 200 235 / 22%);
  pointer-events: none;
}

/* The unit you picked to move/swap — a steady bright ring around its origin. */
.battleCell.swapSelected::before,
.battleCell.repositionSource::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: 3px solid rgb(255 227 155 / 95%);
  border-radius: 6px;
  box-shadow:
    inset 0 0 18px rgb(255 224 122 / 32%),
    0 0 18px rgb(255 224 122 / 55%);
  pointer-events: none;
}

/* Where it can go — pulsing destination / swap-partner cells. */
.battleCell.swapTarget::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 2px solid rgb(120 200 235 / 95%);
  border-radius: 6px;
  box-shadow:
    inset 0 0 18px rgb(120 200 235 / 32%),
    0 0 18px rgb(120 200 235 / 48%);
  pointer-events: none;
  animation: pulseTarget 1.2s ease-in-out infinite;
}

.battleCell.swapSource:hover,
.battleCell.swapTarget:hover,
.battleCell.swapSelected:hover {
  outline: 3px solid rgb(255 227 155 / 58%);
  outline-offset: -3px;
}

/* Confirm flash: a quick bright pop on the cell a unit lands in. */
.battleCell.fxRepositionFlash::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 6px;
  background: radial-gradient(
    circle,
    rgb(255 244 200 / 72%),
    rgb(255 224 122 / 0%) 70%
  );
  pointer-events: none;
  z-index: 4;
  animation: repositionFlash 0.72s ease-out forwards;
}

@keyframes repositionFlash {
  0% {
    opacity: 0;
    transform: scale(0.6);
  }

  35% {
    opacity: 1;
    transform: scale(1.06);
  }

  100% {
    opacity: 0;
    transform: scale(1.22);
  }
}

/* Ghost + arrow preview overlay (a child of .battlefield, so it rotates with
   the board and its cell coordinates line up with the cards). */
.repositionOverlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.repositionArrowSvg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  color: rgb(255 224 122 / 95%);
  overflow: visible;
}

.repositionArrowSvg line {
  stroke: rgb(255 224 122 / 92%);
  stroke-width: 0.11;
  stroke-linecap: round;
  filter: drop-shadow(0 0 2px rgb(0 0 0 / 65%));
}

.repositionGhost {
  position: absolute;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.repositionGhost img {
  width: 72%;
  aspect-ratio: 5 / 7;
  object-fit: cover;
  border-radius: 6px;
  opacity: 0.55;
  border: 2px solid rgb(255 244 200 / 80%);
  box-shadow: 0 0 14px rgb(255 224 122 / 55%);
  animation: pulseTarget 1.2s ease-in-out infinite;
}

.emptyBoardMark {
  width: 1px;
  height: 1px;
}

.boardCard {
  width: min(150px, 66%);
  aspect-ratio: 5 / 7;
  position: relative;
  display: block;
  border-radius: 6px;
  /* Game-piece frame: a dark edge ringed by a thin warm-gold inlay, lifted off
     the board with a soft drop shadow. */
  box-shadow:
    0 9px 15px rgb(0 0 0 / 46%),
    0 0 0 1px rgb(10 8 6 / 92%),
    0 0 0 2.5px rgb(214 178 104 / 60%);
}

.boardCardImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 5px;
  background: #090a0a;
}

/* Compact live HP at the card's top-right, above the printed skill copy. The
   name and duplicated numeric stat line stay on the scanned card/inspector;
   only coloured direction arrows call out live changes. */
.boardCardHud {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 8;
  display: flex;
  align-items: center;
  gap: 3px;
  /* The pill's content is bounded (HP + up to four chevrons — the unbounded
     card NAME left this plate), but keep the hard cap so it can never reach
     the printed stat rail on the card's left edge. */
  max-width: 76%;
  overflow: hidden;
  padding: 2px 3px;
  border: 1px solid rgb(255 234 169 / 55%);
  border-radius: 999px;
  background: rgb(14 13 11 / 92%);
  box-shadow: 0 3px 7px rgb(0 0 0 / 42%);
}

.boardCardHud span {
  font-size: 9px;
  line-height: 1;
}

.boardCardHp {
  color: #f5ead2;
  font-weight: 900;
  white-space: nowrap;
}

.boardCardStatChanges {
  display: inline-flex;
  align-items: center;
  gap: 1px;
}

.boardStatChange {
  display: inline-grid;
  place-items: center;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgb(0 0 0 / 45%);
}

.boardStatChange svg {
  width: 9px;
  height: 9px;
  stroke-width: 3.2;
}

.boardStatChange.attack {
  color: #ff695c;
}
.boardStatChange.defense {
  color: #6ba7ff;
}
.boardStatChange.health {
  color: #ffd65c;
}
.boardStatChange.speed {
  color: #65d487;
}

/* "What changed" tokens on the card's OUTER edge — the initiative rail's
   treatment, so a live stat swing reads at a glance without opening the
   inspector. Deliberately OUTSIDE the card art (right of the card, inside the
   cell's own slack): it can never cover the printed stat rail on the card's
   left edge, the name plate, or the HUD pill (whose 76% cap is a contract). */
.boardCardStatTokens {
  position: absolute;
  left: 100%;
  top: 4%;
  z-index: 9;
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-left: 2px;
  pointer-events: none;
}

.boardStatToken {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  padding: 1px 2px;
  border: 1px solid rgb(0 0 0 / 65%);
  border-radius: 4px;
  background: rgb(12 11 9 / 92%);
  box-shadow: 0 1px 3px rgb(0 0 0 / 55%);
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}

.boardStatToken svg {
  width: 8px;
  height: 8px;
}
.boardStatToken.attack {
  color: #ff695c;
  border-color: rgb(255 105 92 / 55%);
}
.boardStatToken.defense {
  color: #6ba7ff;
  border-color: rgb(107 167 255 / 55%);
}
.boardStatToken.health {
  color: #ffd65c;
  border-color: rgb(255 214 92 / 55%);
}
.boardStatToken.speed {
  color: #65d487;
  border-color: rgb(101 212 135 / 55%);
}
.boardStatToken.down {
  filter: saturate(0.75);
}

/* LIVE-EFFECT icons on the card's OUTER LEFT edge — the mirror of the stat-token
   rail above (which hangs off the outer RIGHT edge). `.boardCard` is
   `width: min(150px, 66%)` inside a centred cell, so both rails sit in the
   cell's own slack and neither can reach the printed stat rail, the name plate
   or the HUD pill. `pointer-events: none` matches the sibling rail so the icons
   can never swallow a click meant for the battlefield cell — which also means
   the native `title` tooltip does not fire on hover (see the component's doc
   comment: the icon is the signal, the inspector is the text surface). */
.boardCardEffectIcons {
  position: absolute;
  right: 100%;
  top: 4%;
  z-index: 9;
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-right: 2px;
  pointer-events: none;
}

.boardEffectIcon {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 1px solid rgb(0 0 0 / 65%);
  border-radius: 50%;
  background: rgb(12 11 9 / 92%);
  box-shadow: 0 1px 3px rgb(0 0 0 / 55%);
  line-height: 0;
}

.boardEffectIcon img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  border-radius: 50%;
}

.boardEffectIcon svg {
  width: 10px;
  height: 10px;
}

.boardEffectIcon.defense-token {
  border-color: rgb(107 167 255 / 62%);
}
.boardEffectIcon.artifact-set {
  border-color: rgb(255 214 92 / 62%);
}
.boardEffectIcon.ongoing-card {
  position: relative;
  border-color: rgb(129 190 255 / 80%);
  box-shadow:
    0 0 4px rgb(72 151 255 / 55%),
    0 1px 3px rgb(0 0 0 / 55%);
}
.boardEffectIcon.ongoing-card img {
  object-fit: cover;
}
.boardEffectCounter {
  position: absolute;
  right: -4px;
  bottom: -4px;
  display: grid;
  place-items: center;
  min-width: 9px;
  height: 9px;
  padding: 0 1px;
  border: 1px solid rgb(10 15 24 / 85%);
  border-radius: 999px;
  background: #e8f3ff;
  color: #10243d;
  font-size: 6px;
  font-weight: 900;
  line-height: 1;
}
.boardEffectIcon.roll-advantage {
  color: #65d487;
  border-color: rgb(101 212 135 / 62%);
}
.boardEffectIcon.roll-disadvantage {
  color: #ff695c;
  border-color: rgb(255 105 92 / 62%);
}

.unitActivationBadge {
  position: absolute;
  left: 4px;
  bottom: 4px;
  z-index: 8;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px 3px;
  border: 1px solid rgb(205 217 224 / 48%);
  border-radius: 999px;
  background: rgb(18 22 24 / 88%);
  color: #dce5e9;
  font-size: 6px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0;
  text-transform: uppercase;
  box-shadow: 0 2px 6px rgb(0 0 0 / 45%);
}

.unitActivationBadge i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 5px currentColor;
}

.unitActivationBadge.ready {
  border-color: rgb(100 212 135 / 64%);
  color: #77df99;
}

.unitActivationBadge.active {
  border-color: rgb(255 216 92 / 76%);
  color: #ffe077;
  animation: activeRingPulse 1.4s ease-in-out infinite;
}

.unitActivationBadge.waited {
  border-color: rgb(233 196 96 / 72%);
  color: #f1cf77;
}

.unitActivationBadge.acted {
  opacity: 0.72;
  color: #a9b2b8;
}

/* ---------- right rail ---------- */

/* The unit card definition: the card scan reads large at the top, its stats and
   abilities beneath. Widened with the right rail so the artwork is actually
   legible during a fight. */
.inspectPanel {
  display: grid;
  gap: 10px;
  min-height: 150px;
  padding: 11px;
  border: 1px solid rgb(243 239 228 / 11%);
  border-radius: 9px;
  background: linear-gradient(180deg, rgb(32 35 38 / 96%), rgb(18 20 22 / 98%));
}

.inspectPanel.empty {
  place-items: center;
  color: var(--muted);
  font-size: 12px;
}

.inspectImage {
  width: 100%;
  max-width: 240px;
  margin: 0 auto;
  aspect-ratio: 5 / 7;
  object-fit: contain;
  border-radius: 7px;
  background: #090a0a;
}

.inspectBody {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 7px;
}

.inspectBody strong {
  overflow-wrap: anywhere;
  font-size: 15px;
}

.inspectKind {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
}

.inspectTotalLegend {
  color: #f4d774;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

/* Initiative shifted by Haste/Slow etc. reads green (up) or red (down). */
.inspectKind .initUp {
  color: var(--green-text, #7fd58a);
  font-weight: 800;
}

.inspectKind .initDown {
  color: #e08a7f;
  font-weight: 800;
}

/* Attack/Defense raised (green) or lowered (red) by a lasting effect — e.g. the
   Bulwark Rune army-wide buffs — so the inspector matches the initiative cue. */
.inspectStats .statUp {
  color: var(--green-text, #7fd58a);
  font-weight: 800;
}

.inspectStats .statDown {
  color: #e08a7f;
  font-weight: 800;
}

.inspectStats {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.inspectStats span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 7px;
  border: 1px solid rgb(243 239 228 / 12%);
  border-radius: 5px;
  background: rgb(13 15 16 / 36%);
  font-size: 12px;
  font-weight: 700;
}

/* Retaliation status line: tells the player whether striking this unit now will
   draw its once-per-round counter-attack. Colour-coded by readiness. */
.inspectRetaliation {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  align-self: start;
  padding: 3px 8px;
  border: 1px solid rgb(243 239 228 / 14%);
  border-radius: 5px;
  background: rgb(13 15 16 / 36%);
  font-size: 11px;
  font-weight: 700;
  text-transform: capitalize;
}

.inspectRetaliation.ready {
  color: #9fd7a6;
  border-color: rgb(93 135 100 / 55%);
}

.inspectRetaliation.used {
  color: #d9b48a;
  border-color: rgb(150 110 70 / 55%);
}

.inspectRetaliation.unlimited {
  color: #f4d774;
  border-color: rgb(210 170 80 / 60%);
}

/* A Pack card's other side (what lethal damage flips it to). Deliberately quiet
   — a dashed, muted strip that reads as reference, not as a live stat. */
.inspectFlipSide {
  display: grid;
  gap: 1px;
  align-self: start;
  padding: 3px 8px;
  border: 1px dashed rgb(243 239 228 / 16%);
  border-radius: 5px;
  background: rgb(13 15 16 / 26%);
  font-size: 10px;
  line-height: 1.25;
}
.inspectFlipHead {
  color: rgb(243 239 228 / 62%);
  font-weight: 700;
  letter-spacing: 0.02em;
}
.inspectFlipStats {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--muted);
}

.inspectAbilities {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.inspectAbilities span {
  padding: 3px 6px;
  border: 1px solid rgb(243 239 228 / 12%);
  border-radius: 5px;
  color: var(--muted);
  background: rgb(13 15 16 / 34%);
  font-size: 10px;
}

.inspectAbilities span.implemented {
  color: var(--ink);
  border-color: rgb(93 135 100 / 70%);
  background: var(--green);
}

.inspectAbilities span.pending {
  border-color: rgb(213 168 79 / 44%);
  color: var(--gold);
}

.commandDock {
  display: grid;
  gap: 6px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgb(23 25 27 / 92%);
}

.dockStatus {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.commandButton {
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid rgb(213 168 79 / 54%);
  border-radius: 6px;
  color: var(--ink);
  background: var(--gold);
  cursor: pointer;
  text-align: left;
  font-size: 13px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.commandButton:hover {
  filter: brightness(1.08);
}

.commandButton.ghost {
  color: var(--muted);
  border-color: var(--line);
  background: var(--surface-2);
  font-weight: 600;
}

/* First Aid Tent heal button — green so it reads as mend, not attack. */
.commandButton.healCommandButton {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #07240f;
  border-color: rgb(110 196 132 / 70%);
  background: linear-gradient(180deg, rgb(150 222 170), rgb(110 196 132));
}

.effectsRail {
  display: grid;
  gap: 6px;
  padding: 8px;
  border: 1px solid rgb(120 111 166 / 36%);
  border-radius: 9px;
  background: rgb(30 28 40 / 80%);
}

.effectsRail header {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
}

.effectChip {
  display: grid;
  gap: 2px;
  padding: 6px 8px;
  border: 1px solid rgb(243 239 228 / 10%);
  border-radius: 6px;
  background: rgb(13 15 16 / 36%);
}

.effectChip span {
  font-size: 12px;
  font-weight: 700;
}

.effectChip small {
  color: var(--muted);
  font-size: 10px;
}

.effectUse {
  min-height: 30px;
  border: 1px solid rgb(120 111 166 / 60%);
  border-radius: 6px;
  color: var(--text);
  background: rgb(120 111 166 / 26%);
  cursor: pointer;
  font-size: 12px;
}

/* ---------- your seat ---------- */

.playerDock {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 52px;
  padding: 5px 6px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: linear-gradient(180deg, rgb(34 28 20 / 92%), rgb(20 18 14 / 94%));
}

.playerDock .pileSpot .pileCard {
  width: 36px;
}

.playerDock .pileSpot > span {
  top: -5px;
  right: -5px;
  min-width: 17px;
  padding: 0 4px;
  font-size: 9px;
}

.playerPileTools {
  display: grid;
  justify-items: center;
  gap: 4px;
}

.playerPileRow {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}

.combatSpellShelfHost {
  display: flex;
  justify-content: center;
  min-height: 34px;
  width: 100%;
}

.combatSpellShelfHost .spellShelf {
  align-self: auto;
  justify-content: center;
  margin: 0;
  padding: 0;
  border: 0;
}

.combatSpellShelfHost .shelfIcon {
  padding: 3px;
}

.combatSpellShelfHost .shelfGlyph {
  width: 34px;
  height: 25px;
}

/* Clickable discard in the combat player dock (opens the full pile browser). */
button.combatDiscardSpot {
  appearance: none;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font: inherit;
}
button.combatDiscardSpot:disabled {
  cursor: default;
}
button.combatDiscardSpot:not(:disabled):hover .pileCard.faceUp {
  outline: 2px solid rgb(213 168 79 / 70%);
  outline-offset: 1px;
}

/* Bottom combat deck + discard rail (map-mode own-deck parity). */
.combatDecksBottom {
  display: flex;
  justify-content: flex-start;
  padding: 6px 10px 8px;
  border-top: 1px solid var(--line);
  background: linear-gradient(180deg, rgb(18 16 12 / 88%), rgb(12 11 9 / 96%));
}
.combatOwnPiles {
  display: flex;
  align-items: flex-end;
  gap: 14px;
}
.combatOwnPile {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 3px;
  min-width: 72px;
}
button.combatOwnPile {
  appearance: none;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font: inherit;
}
.combatOwnPileCard {
  width: 72px;
  aspect-ratio: 5 / 7;
  border-radius: 6px;
  object-fit: cover;
  box-shadow: 0 4px 12px rgb(0 0 0 / 45%);
}
.combatOwnPileCard.faceUp {
  border: 1px solid rgb(243 239 228 / 28%);
}
.combatOwnPileCount,
.combatOwnDiscardBadge {
  position: absolute;
  top: -6px;
  right: -4px;
  min-width: 22px;
  padding: 1px 6px;
  border-radius: 99px;
  border: 1px solid rgb(213 168 79 / 60%);
  color: var(--ink);
  background: var(--gold);
  font-size: 12px;
  font-weight: 800;
  text-align: center;
  line-height: 1.3;
}
.combatOwnPile small {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
button.combatOwnDiscard:hover .combatOwnPileCard {
  outline: 2px solid rgb(213 168 79 / 75%);
  outline-offset: 2px;
}
button.combatOwnDiscard.hasCard .combatOwnPileCard {
  box-shadow:
    0 4px 12px rgb(0 0 0 / 45%),
    0 0 0 1px rgb(213 168 79 / 25%);
}

.dockMetrics {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
}

.dockMetrics strong {
  color: var(--text);
  font-size: 14px;
}

.dockMetrics > span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-height: 20px;
  padding: 2px 5px;
  border: 1px solid rgb(213 168 79 / 18%);
  border-radius: 99px;
  background: rgb(10 9 7 / 30%);
  white-space: nowrap;
}

/* Bulwark "Runes" combat track (frosty palette to match the faction colour). */
.runeTrack {
  display: grid;
  gap: 4px;
  padding: 5px 7px;
  border: 1px solid rgb(127 178 217 / 35%);
  border-radius: 7px;
  background: linear-gradient(180deg, rgb(20 34 50 / 80%), rgb(12 22 34 / 90%));
}

.runeTrack.compact {
  gap: 3px;
  padding: 3px 5px;
}

.runeTrackHead {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.runeSkillIcon {
  width: 18px;
  height: 18px;
  object-fit: contain;
  filter: drop-shadow(0 1px 2px rgb(0 0 0 / 55%));
}

.runeTitle {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #bfe0ff;
}

.runeCount {
  font-weight: 800;
  color: #eaf6ff;
}

.runeCount small {
  color: var(--muted);
  font-weight: 600;
}

.runeLevelTag {
  margin-left: auto;
  padding: 1px 6px;
  border-radius: 999px;
  border: 1px solid rgb(127 178 217 / 45%);
  background: rgb(127 178 217 / 22%);
  color: #d7eeff;
  font-size: 10px;
  font-weight: 800;
}

.runeLevels {
  display: flex;
  gap: 4px;
}

.runeLevel {
  display: grid;
  justify-items: center;
  gap: 1px;
  min-width: 52px;
  padding: 3px 5px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgb(255 255 255 / 4%);
  font-size: 10px;
  line-height: 1.1;
}

.runeLevelThreshold {
  font-size: 11px;
  font-weight: 800;
}

.runeLevelBonus {
  color: var(--muted);
  white-space: nowrap;
}

.runeLevel.active {
  border-color: rgb(127 210 255 / 70%);
  background: linear-gradient(
    180deg,
    rgb(60 140 200 / 40%),
    rgb(30 90 150 / 30%)
  );
  color: #eaf6ff;
  box-shadow: 0 0 8px rgb(127 200 255 / 28%);
}

.runeLevel.active .runeLevelBonus {
  color: #cdeaff;
}

.runeLevel.pending {
  border-style: dashed;
  opacity: 0.85;
}

.runeLevel.locked {
  opacity: 0.45;
  filter: grayscale(0.7);
}

.runePips {
  display: flex;
  gap: 3px;
}

.runePip {
  width: 9px;
  height: 9px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgb(255 255 255 / 8%);
}

.runePip.active {
  border-color: rgb(127 210 255 / 80%);
  background: radial-gradient(circle at 40% 35%, #bfe6ff, #3f8fcf);
  box-shadow: 0 0 6px rgb(127 200 255 / 55%);
}

.runePip.pending {
  border-style: dashed;
  background: rgb(127 178 217 / 25%);
}

.runePip.locked {
  opacity: 0.4;
}

.handFan {
  display: flex;
  align-items: end;
  padding: 6px 20px 3px 6px;
  min-height: 110px;
  /* Must stay visible on BOTH axes: `overflow-x: auto` promotes overflow-y
     to auto too (CSS spec), which clipped the card popover and its
     play/cast buttons — making every hand card unplayable in combat. */
  overflow: visible;
}

.handFan.muted {
  opacity: 0.35;
  pointer-events: none;
}

.handEmpty {
  color: var(--muted);
  font-size: 13px;
}

/* Spell Scrolls: a parchment rail beside the hand (cards are not in hand). */
.scrollRail {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-self: stretch;
  justify-content: center;
  padding-right: 12px;
  margin-right: 6px;
  border-right: 1px dashed rgba(210, 180, 120, 0.4);
}

.scrollChip {
  display: flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(
    180deg,
    rgba(94, 70, 32, 0.55),
    rgba(60, 44, 20, 0.55)
  );
  border: 1px solid rgba(210, 180, 120, 0.5);
  border-radius: 8px;
  padding: 6px 8px;
}

.scrollGlyph {
  font-size: 22px;
  line-height: 1;
}

.scrollSpells {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.scrollSpell {
  display: flex;
  align-items: center;
  gap: 6px;
}

.scrollSpellName {
  background: none;
  border: none;
  color: #f4e6c8;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  padding: 0;
  text-decoration: underline dotted;
}

.scrollSpellCasts {
  display: flex;
  gap: 4px;
}

.scrollSpellCasts .commandButton {
  font-size: 11px;
  padding: 2px 6px;
}

/* ---------- Spell Book / Spell Scroll shelf (house rule) ---------- */
.spellShelf {
  display: flex;
  flex-direction: row;
  gap: 5px;
  align-self: flex-start;
  padding: 0 7px 3px 0;
  margin-right: 4px;
  border-right: 1px dashed rgba(210, 180, 120, 0.4);
}

.shelfItem {
  position: relative;
  display: flex;
  justify-content: center;
}

.shelfIcon {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border: 1.5px solid rgba(213, 168, 79, 0.7);
  border-radius: 10px;
  background: linear-gradient(
    180deg,
    rgba(94, 70, 32, 0.6),
    rgba(60, 44, 20, 0.6)
  );
  cursor: pointer;
  /* A persistent soft glow so the Book always reads as a live control, plus a
     gentle pulse while it holds castable Spells. */
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.5),
    0 0 10px rgba(213, 168, 79, 0.28);
  transition:
    transform 120ms ease,
    box-shadow 120ms ease,
    border-color 120ms ease;
}

.shelfIcon:not(.empty) {
  animation: shelfPulse 2.4s ease-in-out infinite;
}

@keyframes shelfPulse {
  0%,
  100% {
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.5),
      0 0 10px rgba(213, 168, 79, 0.28);
  }

  50% {
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.5),
      0 0 16px rgba(240, 196, 106, 0.6);
  }
}

.shelfIcon.open,
.shelfIcon:hover,
.shelfIcon:focus-visible {
  border-color: var(--gold);
  transform: translateY(-1px) scale(1.05);
  box-shadow:
    0 0 0 1px rgba(213, 168, 79, 0.6),
    0 6px 16px rgba(0, 0, 0, 0.5),
    0 0 18px rgba(240, 196, 106, 0.6);
  outline: none;
}

/* An empty Spell Book is shown from the start, but dimmed until it holds Spells. */
.shelfIcon.empty {
  opacity: 0.72;
}

.shelfIcon.empty .shelfCount {
  background: rgba(210, 180, 120, 0.4);
  color: #2a2014;
}

.shelfGlyph {
  width: 36px;
  height: 28px;
  object-fit: contain;
  image-rendering: pixelated;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.6));
}

.shelfGlyphEmoji {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 34px;
  line-height: 40px;
}

.shelfCount {
  position: absolute;
  right: -6px;
  top: -6px;
  min-width: 16px;
  height: 16px;
  padding: 0 3px;
  border-radius: 8px;
  background: var(--gold);
  color: var(--ink);
  font-size: 10px;
  font-weight: 800;
  line-height: 16px;
  text-align: center;
}

.shelfPopover {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: grid;
  gap: 6px;
  width: 232px;
  max-height: 320px;
  overflow-y: auto;
  padding: 10px;
  border: 1px solid var(--gold);
  border-radius: 9px;
  background: rgb(20 19 15 / 97%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 55%);
}

.shelfPopover strong {
  font-size: 13px;
}

.shelfPopover small {
  color: var(--muted);
  font-size: 11px;
}

.shelfEmpty {
  color: var(--muted);
  font-style: italic;
  font-size: 12px;
}

.shelfSpell {
  display: grid;
  gap: 3px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgb(243 239 228 / 10%);
}

.shelfSpell:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

/* The spell row header: its card icon + name, one click to zoom the card. */
.shelfSpellHead {
  display: flex;
  align-items: center;
  gap: 8px;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;
  width: 100%;
}

/* Card art thumbnail shown beside each stored Spell in the Book/Scroll popover. */
.shelfSpellIcon {
  width: 34px;
  height: 46px;
  flex: 0 0 auto;
  object-fit: cover;
  border-radius: 4px;
  border: 1px solid rgb(212 175 108 / 55%);
  background: rgb(0 0 0 / 25%);
}

/* Text fallback frames (art-less specialties) reuse the same footprint. */
.shelfSpellIcon.cardFaceFallback {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  font-size: 8px;
  line-height: 1.1;
  text-align: center;
  color: #f4e6c8;
  overflow: hidden;
}

.shelfSpellName {
  color: #f4e6c8;
  font-size: 12px;
  font-weight: 700;
  text-decoration: underline dotted;
}

.shelfSpellCasts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.shelfSpellCasts .commandButton {
  font-size: 11px;
  padding: 3px 7px;
}

.shelfSpellHint {
  color: var(--muted);
  font-size: 10px;
  font-style: italic;
}

.trayTile.scrollTile {
  border-color: rgba(210, 180, 120, 0.6);
}

/* Scroll badge on the always-visible hero board. */
.hbScrolls {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.hbScrollChip {
  font-size: 11px;
  background: rgba(94, 70, 32, 0.5);
  border: 1px solid rgba(210, 180, 120, 0.5);
  border-radius: 6px;
  padding: 2px 6px;
  color: #f4e6c8;
}

.fanSlot {
  position: relative;
}

.fanCard {
  position: relative;
  display: block;
  width: 88px;
  margin-right: -28px;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
  transition:
    transform 160ms ease,
    margin 160ms ease;
  transform-origin: bottom center;
}

.fanCard .fanCardImage {
  width: 100%;
  aspect-ratio: 5 / 7;
  object-fit: cover;
  border-radius: 7px;
  border: 1px solid rgb(12 10 7 / 90%);
  background: #0a0b0b;
  box-shadow: 0 8px 14px rgb(0 0 0 / 45%);
}

.fanCard:hover,
.fanCard:focus-visible,
.fanSlot.open .fanCard {
  z-index: 30;
  transform: translateY(-34px) scale(1.5);
}

/* Pending-action echo (plan N2): a hand card whose play is submitted but not
   yet acknowledged dims at once, and after PENDING_ECHO_SLOW_MS (400 ms — see
   src/lib/pending-action-echo.ts) a pulsing ring appears: the "slow network"
   styling, pure CSS so it needs no timer or re-render. Presentation only —
   the class is removed on ack/error/snapshot and everything snaps back. */
.fanCard.cardInFlight,
.adventureHandCard.cardInFlight {
  /* relative anchors the ::after ring; a visual no-op without offsets. */
  position: relative;
  opacity: 0.55;
  filter: saturate(0.6);
}

.fanCard.cardInFlight::after,
.adventureHandCard.cardInFlight::after {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 8px;
  border: 2px solid rgb(213 168 79 / 0%);
  pointer-events: none;
  animation: cardInFlightSlow 1.1s ease-in-out 400ms infinite;
}

@keyframes cardInFlightSlow {
  0%,
  100% {
    border-color: rgb(213 168 79 / 0%);
  }

  50% {
    border-color: rgb(213 168 79 / 75%);
  }
}

.fanCard.playable .playGlow {
  position: absolute;
  inset: -2px;
  border-radius: 8px;
  border: 2px solid rgb(213 168 79 / 85%);
  box-shadow: 0 0 16px rgb(213 168 79 / 55%);
  pointer-events: none;
}

.fanCard.selected .fanCardImage {
  outline: 3px solid var(--blue);
  outline-offset: -1px;
}

/* ---------------------------------------------------------------------------
   Empowered cards — Empowered Statistics (intrinsic to the card) and abilities
   the player has had Empowered (per-owner, from player.empoweredAbilities). A
   violet ring + glow plus an "Empowered" pill set them apart from a normal
   statistic/ability AND from the gold "playable" glow. The ring uses
   outline + filter (not box-shadow) so it layers ON TOP of each surface's own
   box-shadow instead of replacing it via the cascade.
--------------------------------------------------------------------------- */
.empoweredCard {
  outline: 2px solid #c79bff;
  outline-offset: -2px;
  border-radius: 7px;
  filter: drop-shadow(0 0 5px rgb(168 85 247 / 85%));
}

.empoweredBadge {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, #8b5cf6, #5b21b6);
  color: #f5ecff;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.4;
  text-transform: uppercase;
  white-space: nowrap;
  border: 1px solid rgb(245 236 255 / 60%);
  box-shadow: 0 1px 4px rgb(0 0 0 / 50%);
}

/* Inline pill beside a name (combat tray). */
.trayTileBody .empoweredBadge {
  margin-left: 6px;
  vertical-align: middle;
}

/* Inline pill in the zoom body (slightly larger to match the read view). */
.zoomEmpoweredBadge {
  align-self: start;
  margin: 2px 0;
  font-size: 10px;
}

/* Overlay pill pinned to the top of the card art (hand fan, pile thumbnails). */
.empoweredBadgeOverlay {
  position: absolute;
  top: 3px;
  left: 50%;
  z-index: 6;
  transform: translateX(-50%);
  pointer-events: none;
}

/* The pile thumbnail button anchors its overlay badge. */
.pileCardButton {
  position: relative;
}

.fanSlot.open {
  z-index: 40;
}

.cardPopover {
  /* Combat hands live at the top of the battle screen. Anchoring this menu
     above its card sends its actions past y=0 on short/narrow viewports.
     A viewport-centred menu stays wholly reachable at every battle size. */
  position: fixed;
  top: 50%;
  bottom: auto;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 120;
  display: grid;
  gap: 6px;
  width: 218px;
  max-height: calc(100dvh - 24px);
  overflow-y: auto;
  padding: 10px;
  border: 1px solid var(--gold);
  border-radius: 9px;
  background: rgb(20 19 15 / 97%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 55%);
}

.cardPopover strong {
  font-size: 13px;
}

.cardPopover small {
  color: var(--muted);
  font-size: 11px;
}

.popMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.popMeta span {
  padding: 2px 5px;
  border: 1px solid rgb(243 239 228 / 12%);
  border-radius: 4px;
  color: var(--muted);
  background: rgb(13 15 16 / 36%);
  font-size: 9px;
  text-transform: uppercase;
}

.cardPopover button {
  min-height: 30px;
  border: 1px solid rgb(213 168 79 / 58%);
  border-radius: 6px;
  color: var(--ink);
  background: var(--gold);
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.cardPopover button.ghost {
  color: var(--muted);
  border-color: var(--line);
  background: var(--surface-2);
  font-weight: 600;
}

.cardPopover .noTiming {
  color: var(--muted);
  font-style: italic;
}

/* Confirm step for an immediate (no-target) play: an accidental click never
   commits — the player must press Confirm, and Cancel always backs out. */
.cardPopover .cardPlayConfirm {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cardPopover .cardPlayConfirm small {
  color: var(--muted);
}

.cardPopover .cardPlayConfirm .confirmLabel {
  font-size: 13px;
}

/* The adventure-hand confirm bar reuses the cost-picker row styling. */
.handButtons.playConfirm span {
  font-weight: 700;
}

/* ---------- reaction tray ---------- */

.reactionStrip {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  z-index: 70;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: min(680px, 92vw);
  padding: 10px 16px;
  border: 1px solid var(--gold);
  border-radius: 10px;
  background: rgb(94 70 32 / 96%);
  box-shadow: 0 18px 44px rgb(0 0 0 / 55%);
  font-size: 13px;
}

.reactionStrip small {
  color: rgb(243 239 228 / 75%);
}

.reactionTray {
  position: fixed;
  left: 50%;
  bottom: 12px;
  transform: translate(calc(-50% + var(--reaction-tray-x, 0px)), var(--reaction-tray-y, 0px));
  z-index: 80;
  display: grid;
  gap: 10px;
  width: min(880px, 96vw);
  padding: 12px 14px;
  border: 2px solid var(--gold);
  border-radius: 12px;
  background: rgb(24 21 15 / 97%);
  box-shadow: 0 24px 60px rgb(0 0 0 / 60%);
}

.reactionTray header {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.movableReactionTray > header {
  cursor: move;
  touch-action: none;
  user-select: none;
}

.reactionTrayGrip {
  color: var(--muted);
  flex: 0 0 auto;
}

.reactionTrayMinimize {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 30px;
  height: 28px;
  margin-left: auto;
  padding: 0;
  border: 1px solid rgb(243 239 228 / 25%);
  border-radius: 6px;
  color: var(--text);
  background: rgb(255 255 255 / 7%);
  cursor: pointer;
}

.reactionTrayMinimize:hover,
.reactionTrayMinimize:focus-visible {
  border-color: var(--gold);
  color: var(--gold);
}

.movableReactionTray.minimized {
  width: min(520px, 94vw);
}

.movableReactionTray.minimized > :not(header) {
  display: none;
}

.reactionTray header strong {
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 12px;
}

.reactionTray header span {
  color: var(--text);
  font-size: 13px;
}

.trayTiles {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.trayEmpty {
  color: var(--muted);
  font-size: 13px;
  padding: 12px;
}

.trayTile {
  position: relative;
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  gap: 8px;
  min-width: 224px;
  padding: 8px;
  border: 1px solid rgb(243 239 228 / 14%);
  border-radius: 9px;
  background: rgb(13 15 16 / 50%);
}

.trayTile.selected {
  border-color: var(--gold);
  box-shadow: 0 0 14px rgb(213 168 79 / 30%);
}

.trayOrderBadge {
  position: absolute;
  left: 4px;
  top: 4px;
  z-index: 2;
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 1px solid #f6d27c;
  border-radius: 50%;
  background: rgb(22 17 9 / 94%);
  color: #ffe6a6;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  pointer-events: none;
}

.trayCardImage {
  width: 74px;
  aspect-ratio: 5 / 7;
  object-fit: cover;
  border-radius: 6px;
  background: #0a0b0b;
}

.trayTileBody {
  display: grid;
  align-content: start;
  gap: 6px;
}

.trayTileBody strong {
  font-size: 12px;
  overflow-wrap: anywhere;
}

.trayGroup {
  display: grid;
  gap: 4px;
}

.trayPick,
.trayExpert,
.trayInstant {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 4px 8px;
  border: 1px solid rgb(243 239 228 / 22%);
  border-radius: 6px;
  color: var(--text);
  background: rgb(13 15 16 / 45%);
  cursor: pointer;
  font-size: 12px;
}

.trayPick.picked {
  border-color: var(--gold);
  color: var(--ink);
  background: var(--gold);
  font-weight: 800;
}

.trayExpert.picked {
  border-color: var(--violet);
  color: var(--text);
  background: rgb(120 111 166 / 55%);
  font-weight: 800;
}

.trayExpert.locked {
  border-style: dashed;
  color: rgb(243 239 228 / 45%);
  background: rgb(13 15 16 / 30%);
  cursor: not-allowed;
  opacity: 0.7;
}

.trayInstant {
  border-color: var(--red);
  background: rgb(166 83 72 / 30%);
  font-weight: 800;
}

.trayInstant:hover {
  background: rgb(166 83 72 / 55%);
}

.reactionTray footer {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.trayPreview {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  flex-wrap: wrap;
  color: var(--muted);
  font-size: 12px;
}

.trayPreview span {
  padding: 4px 8px;
  border: 1px solid rgb(243 239 228 / 14%);
  border-radius: 99px;
  background: rgb(13 15 16 / 45%);
  font-weight: 700;
}

.crownMeter.over {
  border-color: var(--red);
  color: #ffb9ad;
}

.trayPowerMeter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--gold);
  border-radius: 99px;
  background: rgb(213 168 79 / 14%);
  color: var(--gold);
  font-size: 12px;
  white-space: nowrap;
}

.trayPowerMeter strong {
  font-size: 13px;
}

.trayPowerMeter small {
  color: rgb(243 239 228 / 82%);
  font-weight: 600;
}

.trayConfirm,
.trayPass {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 38px;
  padding: 6px 14px;
  border-radius: 7px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
}

.trayConfirm {
  border: 1px solid rgb(213 168 79 / 70%);
  color: var(--ink);
  background: var(--gold);
}

.trayConfirm:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.trayPass {
  border: 1px solid var(--line);
  color: var(--text);
  background: var(--surface-2);
}

/* ---------- modals ---------- */

.modalBackdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  background: rgb(8 8 7 / 62%);
  backdrop-filter: blur(2px);
}

.searchModal {
  display: grid;
  gap: 12px;
  width: min(720px, 94vw);
  /* Cap the height to the viewport and scroll the body so a tall picker (a
     Search(4)/(5) wraps 2–3 card rows) fits a short window instead of
     overflowing past both edges with no way to reach the last option. `dvh`
     only binds when the viewport is actually short, so a normal desktop window
     — where the modal is far smaller than 92dvh — is byte-for-byte unchanged.
     Shared with RerollModal + LearningOfferModal (`.searchModal …`). */
  max-height: 92dvh;
  overflow-y: auto;
  padding: 16px;
  border: 2px solid var(--gold);
  border-radius: 12px;
  background: rgb(24 21 15 / 98%);
  box-shadow: 0 24px 60px rgb(0 0 0 / 60%);
}

/* Confirm dialog: e.g. "you can still buy troops — move into battle anyway?" */
.confirmModal {
  display: grid;
  gap: 12px;
  width: min(440px, 92vw);
  padding: 18px;
  border: 2px solid var(--gold);
  border-radius: 12px;
  background: rgb(24 21 15 / 98%);
