.dieScene {
  position: relative;
  width: 68px;
  height: 68px;
  /* Deeper perspective so the throw reads with real 3D weight. */
  perspective: 540px;
  transition: opacity 300ms ease;
}

/* A burst of light that pops the instant the die settles on its face. */
.dieScene::before {
  content: "";
  position: absolute;
  inset: -14%;
  border-radius: 24%;
  background: radial-gradient(
    circle at 50% 46%,
    rgb(236 200 96 / 55%),
    transparent 62%
  );
  opacity: 0;
  pointer-events: none;
}

.dieScene:has(.dieCube.settled)::before {
  animation: dieFlash 640ms ease-out;
}

@keyframes dieFlash {
  0% {
    opacity: 0;
    transform: scale(0.7);
  }

  28% {
    opacity: 1;
    transform: scale(1.12);
  }

  100% {
    opacity: 0;
    transform: scale(1.42);
  }
}

/* A soft contact shadow that thumps in as the die comes to rest on the felt. */
.dieScene::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -8px;
  width: 64%;
  height: 13px;
  transform: translateX(-50%) scale(0.4);
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    rgb(0 0 0 / 52%),
    transparent 70%
  );
  opacity: 0;
  pointer-events: none;
}

.dieScene:has(.dieCube.settled)::after {
  animation: dieShadow 560ms cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
}

@keyframes dieShadow {
  0% {
    opacity: 0;
    transform: translateX(-50%) scale(0.4);
  }

  44% {
    opacity: 0.9;
    transform: translateX(-50%) scale(1.16);
  }

  100% {
    opacity: 1;
    transform: translateX(-50%) scale(1);
  }
}

.dieScene.dimmed {
  opacity: 0.35;
}

/* A force-rerolled die (Hourglass of the Evil Hour / Negative Morale): a warm
   ring + pulse marks the "+1" being thrown away and rolled again. */
.dieScene.rerolled {
  animation: dieRerollPulse 620ms ease-in-out 2;
}

.dieScene.rerolled::after {
  border-color: rgb(224 96 72 / 85%);
  box-shadow: 0 0 14px rgb(224 96 72 / 55%);
}

@keyframes dieRerollPulse {
  0%,
  100% {
    filter: none;
  }
  50% {
    filter: brightness(1.35) saturate(1.2);
  }
}

.dieCube {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  /* The die rolls to its face with a heavy, slightly overshooting wobble. */
  transition: transform 820ms cubic-bezier(0.16, 0.9, 0.22, 1.18);
}

/* Hurled across the felt: fast multi-axis spin with bounces that lose height as
   the die sheds energy, plus a touch of sideways drift and a catch-light pulse. */
.dieCube.tumbling {
  animation: cubeTumble 720ms cubic-bezier(0.45, 0.05, 0.4, 1) infinite;
}

@keyframes cubeTumble {
  0% {
    transform: translateY(-60%) translateX(-11%) scale(0.93) rotateX(0deg)
      rotateY(0deg) rotateZ(-13deg);
  }

  16% {
    transform: translateY(7%) translateX(-5%) scale(1.03) rotateX(134deg)
      rotateY(88deg) rotateZ(17deg);
  }

  34% {
    transform: translateY(-35%) translateX(2%) scale(0.97) rotateX(240deg)
      rotateY(172deg) rotateZ(-13deg);
  }

  54% {
    transform: translateY(6%) translateX(7%) scale(1.04) rotateX(340deg)
      rotateY(264deg) rotateZ(13deg);
  }

  74% {
    transform: translateY(-17%) translateX(3%) scale(0.99) rotateX(452deg)
      rotateY(346deg) rotateZ(-7deg);
  }

  90% {
    transform: translateY(3%) translateX(1%) scale(1.01) rotateX(522deg)
      rotateY(404deg) rotateZ(5deg);
  }

  100% {
    transform: translateY(0%) translateX(0%) scale(1) rotateX(560deg)
      rotateY(430deg) rotateZ(0deg);
  }
}

/* The whole die gives as it lands — a squash on impact, then a double bounce. */
.dieScene:has(.dieCube.settled) {
  animation: dieLand 720ms cubic-bezier(0.2, 0.9, 0.3, 1.12);
}

@keyframes dieLand {
  0% {
    transform: translateY(-11%) scale(1.06);
  }

  28% {
    transform: translateY(5%) scaleX(1.13) scaleY(0.85);
  }

  50% {
    transform: translateY(-5%) scaleX(0.94) scaleY(1.07);
  }

  72% {
    transform: translateY(2%) scaleX(1.04) scaleY(0.97);
  }

  100% {
    transform: translateY(0) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dieScene:has(.dieCube.settled),
  .dieScene:has(.dieCube.settled)::before {
    animation: none;
  }

  .dieScene:has(.dieCube.settled)::after {
    animation: none;
    opacity: 1;
    transform: translateX(-50%) scale(1);
  }

  .dieCube.tumbling {
    animation-duration: 1000ms;
  }

  /* Keep the Market tab visible (bright border, no pulsing) for users who
     opt out of motion. */
  .marketTab {
    animation: none;
    border-color: rgba(255, 227, 150, 1);
    box-shadow:
      0 8px 22px rgba(0, 0, 0, 0.5),
      0 0 14px 3px rgba(255, 210, 120, 0.6);
  }
}

