  color: #ffe39a;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 12px rgb(221 177 76 / 35%);
}

.coopMapNode {
  width: 11px;
  height: 11px;
  border: 2px solid #071115;
}

.coopMapNode.ally {
  background: #4fd6c1;
  box-shadow: 0 0 7px #45d8c2;
}
.coopMapNode.enemy {
  background: #df4d68;
  box-shadow: 0 0 7px #e34966;
}
.coopMapNode.ally.one {
  left: 15%;
  bottom: 18%;
}
.coopMapNode.ally.two {
  left: 24%;
  top: 18%;
}
.coopMapNode.enemy.one {
  right: 14%;
  top: 17%;
}
.coopMapNode.enemy.two {
  right: 20%;
  bottom: 16%;
}

.coopEnemyPicker {
  display: grid;
  align-content: center;
  gap: 9px;
  padding: 10px;
}

.coopEnemyPicker > div:first-child {
  display: grid;
  gap: 2px;
}

.coopEnemyButtons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
}

.coopEnemyButtons button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 34px;
  border: 1px solid rgb(216 80 104 / 34%);
  border-radius: 7px;
  background: rgb(47 13 24 / 52%);
  color: #df9aaa;
  cursor: pointer;
}

.coopEnemyButtons button:hover,
.coopEnemyButtons button.active {
  border-color: #ec5e79;
  background: linear-gradient(180deg, #8d263b, #451421);
  color: #fff1f4;
  box-shadow: 0 0 10px rgb(226 69 99 / 34%);
}

.coopUnrankedBanner {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  color: #9be9dd;
}

.coopUnrankedBanner > span {
  display: grid;
  gap: 1px;
  color: #91acaf;
  font-size: 11px;
}

.coopUnrankedBanner strong {
  color: #cafff5;
  font-size: 12px;
}

.coopLobbyShell .lobbyCreate .commandButton.primary {
  border: 1px solid rgb(112 238 219 / 46%);
  background: linear-gradient(180deg, #16766e, #0a3d42);
  color: #ecfffb;
  box-shadow: 0 0 16px rgb(60 215 194 / 22%);
}

.coopLobbyShell .lobbyModeOption.active {
  border-color: #56d9c6;
  background: rgb(25 116 108 / 20%);
  box-shadow:
    inset 0 0 0 1px rgb(134 255 235 / 12%),
    0 0 10px rgb(62 219 196 / 18%);
}

.lobbyRoomRanked.coop {
  border-color: rgb(81 211 191 / 52%);
  background: rgb(13 93 86 / 34%);
  color: #bafff3;
}

/* Co-op stays unmistakable after room creation: static generated war-room art,
   a persistent mode banner, and no setup-scene video download for this mode. */
.setupSceneIllustration.setupSceneIllustration--coop,
.setupPhase .setupSceneIllustration.setupSceneIllustration--coop {
  background: #050b12 url("/assets/ui/coop/coop-mounted-party-v2.webp") center /
    cover no-repeat !important;
}

.setupLobby--coop .setupSceneDragonBreath,
.setupLobby--coop .setupScenePaintedFruit {
  display: none;
}

.coopSetupBanner {
  position: absolute;
  z-index: 9;
  top: 20px;
  right: 2.2%;
  display: grid;
  gap: 2px;
  width: min(330px, 28vw);
  padding: 10px 14px;
  border: 1px solid rgb(91 226 205 / 42%);
  border-left: 4px solid #58d9c5;
  border-radius: 8px;
  background: linear-gradient(110deg, rgb(5 32 39 / 91%), rgb(25 9 19 / 86%));
  box-shadow:
    0 10px 28px rgb(0 0 0 / 50%),
    0 0 18px rgb(72 217 195 / 12%);
  color: #c9fff5;
  pointer-events: none;
}

.coopSetupBanner > span {
  color: #65dfce;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.coopSetupBanner strong {
  font-family: var(--font-heroic);
  font-size: 13px;
}

.coopSetupBanner em {
  color: #ed6c83;
  font-style: normal;
}
.coopSetupBanner small {
  color: #91b5b6;
  font-size: 9px;
}

@media (max-width: 760px) {
  .coopMissionIntro {
    align-items: flex-start;
    flex-direction: column;
  }
  .coopMissionTags {
    justify-content: flex-start;
  }
  .coopExpeditionBuilder {
    grid-template-columns: 1fr;
  }
  .coopBattlefieldCard {
    grid-template-columns: 88px 1fr;
  }
  .coopSetupBanner {
    top: 7px;
    right: 8px;
    width: min(280px, calc(100vw - 16px));
    padding: 7px 10px;
  }
  .coopSetupBanner small {
    display: none;
  }
}

.dieFace {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border: 1px solid rgb(58 6 10 / 90%);
  /* Rounded corners like a real moulded die. */
  border-radius: 19%;
  color: #fff3e6;
  background:
    radial-gradient(
      120% 120% at 26% 16%,
      rgb(255 255 255 / 55%),
      rgb(255 255 255 / 0) 44%
    ),
    radial-gradient(135% 135% at 80% 98%, rgb(0 0 0 / 52%), rgb(0 0 0 / 0) 56%),
    linear-gradient(152deg, #e8404d 0%, #c81e2c 46%, #8a1018 100%);
  box-shadow:
    inset 0 2px 3px rgb(255 255 255 / 50%),
    inset 0 -6px 11px rgb(0 0 0 / 55%),
    inset 0 0 0 2px rgb(255 226 196 / 16%);
  /* The symbol reads as engraved: dark trough above, warm catch-light below. */
  text-shadow:
    0 -1px 1px rgb(0 0 0 / 65%),
    0 1px 0 rgb(255 196 178 / 45%);
  backface-visibility: hidden;
  font-size: 25px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.diceBreakdown {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  justify-content: center;
  transition: opacity 240ms ease;
}

.diceBreakdown.hidden {
  opacity: 0;
}

.diceBreakdown .formula {
  padding: 6px 12px;
  border: 1px solid rgb(243 239 228 / 16%);
  border-radius: 8px;
  background: rgb(13 15 16 / 50%);
  font-size: 15px;
  font-weight: 700;
}

.diceBreakdown .versus {
  color: var(--muted);
  text-transform: uppercase;
  font-size: 11px;
}

.damageResult {
  padding: 7px 16px;
  border-radius: 8px;
  font-size: 16px;
}

.damageResult.hit {
  color: #ffd9d2;
  border: 1px solid var(--red);
  background: rgb(166 83 72 / 40%);
}

.damageResult.blocked {
  color: #d8efd9;
  border: 1px solid var(--green);
  background: rgb(93 135 100 / 30%);
}

/* Roll-modifier chips under the dice breakdown: the morale/artifact/spell
   adjustments that changed this roll, plus the defender's Defend die. */
.diceModifiers {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  animation: diceModifiersIn 240ms ease;
}

@keyframes diceModifiersIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.diceModChip {
  padding: 3px 10px;
  border: 1px solid rgb(214 168 96 / 55%);
  border-radius: 99px;
  background: rgb(13 15 16 / 60%);
  color: var(--gold);
  font-size: 12px;
}

.diceModChip strong {
  font-weight: 800;
}

.diceModChip.shield {
  border-color: rgb(120 111 166 / 60%);
  color: var(--violet);
}

.diceModChip.reroll {
  border-color: rgb(224 96 72 / 60%);
  color: rgb(240 176 152);
}

/* "Might" divider tag before a WOG commander's extra attack dice. */
.mightDiceTag {
  align-self: center;
  padding: 2px 8px;
  border: 1px solid rgb(214 168 96 / 55%);
  border-radius: 99px;
  color: var(--gold);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ---------- log drawer ---------- */

.logDrawer {
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgb(23 25 27 / 90%);
  overflow: hidden;
}

.logToggle {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 36px;
  padding: 7px 12px;
  border: 0;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  text-align: left;
  font-size: 12px;
}

.logToggle span {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text);
}

/* "EVENT LOG" is the fixed tag; the live one-line ticker beside it takes the
   leftover width and ellipsizes (it is hidden on the desktop HUD's narrow pill). */
.logToggle .logToggleLabel {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.logDrawer ol {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 8px 12px 12px;
  list-style: none;
  max-height: 260px;
  overflow-y: auto;
}

.logDrawer li {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 8px;
  padding: 6px 8px;
  border: 1px solid rgb(243 239 228 / 8%);
  border-radius: 5px;
  background: rgb(13 15 16 / 30%);
  font-size: 12px;
}

.logDrawer li span {
  color: var(--muted);
  font-size: 10px;
  text-transform: uppercase;
}

/* The battlefield has no map HUD to host the log button. Keep a compact,
   always-visible combat chronicle above the lower edge of the table instead of
   leaving it after the full board where it falls below the viewport. */
.battleLogDrawer {
  position: fixed;
  z-index: 88;
  left: 12px;
  bottom: 12px;
  width: min(440px, calc(100vw - 24px));
  overflow: visible;
  border-color: rgb(202 154 65 / 78%);
  box-shadow: 0 12px 34px rgb(0 0 0 / 62%);
}

.battleLogDrawer .logPopover {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 0;
  width: 100%;
  overflow: hidden;
  border: 1px solid rgb(202 154 65 / 62%);
  border-radius: 9px;
  background: rgb(16 12 8 / 98%);
}

.battleLogDrawer .logPopover ol {
  max-height: min(48vh, 430px);
}

.battleLogDrawer .battleLogEvent.you {
  border-left: 3px solid #65a9ef;
}

.battleLogDrawer .battleLogEvent.enemy {
  border-left: 3px solid #d65a4b;
  background: rgb(76 20 16 / 30%);
}

.battleLogDrawer .battleLogEvent.enemy .logEventMeta {
  color: #ff9a89;
}

@media (max-width: 720px) {
  .battleLogDrawer {
    left: 8px;
    bottom: 58px;
    width: calc(100vw - 16px);
  }

  .battleLogDrawer .logPopover ol {
    max-height: 38vh;
  }
}

/* The event log rides the top command band as ONE compact scroll button, and its
   open chronicle is a POPOVER — never an in-flow block that would inflate the
   command band and shove the map down. These base rules cover every non-phone
   width; the desktop-HUD block below re-anchors the popover `fixed` because the
   band clips its overflow there (an absolute child would be cut off). */
.advHudButtons > .logDrawer {
  position: relative;
  flex: 0 0 auto;
  /* The drawer clips by default (rounded corners); the popover must escape it. */
  overflow: visible;
}

.advHudButtons > .logDrawer .logToggle {
  width: auto;
  white-space: nowrap;
}

.advHudButtons > .logDrawer .logPopover {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 92;
  box-sizing: border-box;
  width: min(560px, calc(100vw - 32px));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgb(23 25 27 / 97%);
  box-shadow: 0 18px 48px rgb(0 0 0 / 60%);
}

/* ---------- credits ---------- */

.creditsPage {
  width: min(1440px, 100%);
  margin: 0 auto;
  padding: 18px;
  display: grid;
  gap: 12px;
}

.panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: rgb(23 25 27 / 92%);
}

.creditsPanel {
  max-width: 880px;
}

.creditsPanel h1,
.creditsPanel h2 {
  margin: 0;
  line-height: 1.1;
}

.creditsPanel p {
  color: var(--muted);
  line-height: 1.55;
}

.sourceList {
  display: grid;
  gap: 8px;
  margin: 0;
  padding-left: 18px;
}

.sourceList a {
  color: var(--gold);
}

/* ---------- responsive ---------- */

@media (max-width: 1240px) {
  .tableMidRow {
    grid-template-columns: minmax(0, 1fr) 280px;
  }

  .tableMidRow.withPlacement {
    grid-template-columns: minmax(0, 1fr) 220px 280px;
  }
}

@media (max-width: 1020px) {
  .tableTopRow,
  .tableMidRow,
  .tableMidRow.withPlacement {
    grid-template-columns: 1fr;
  }

  .rightRail {
    grid-template-columns: 1fr 1fr;
  }

  .opponentSeat {
    grid-template-columns: minmax(140px, 190px) minmax(0, 1fr) auto;
    gap: 6px;
  }

  .tableSeatRow {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .tableSeatRow > .handColumn {
    grid-column: 1 / -1;
  }
}

@media (max-width: 680px) {
  .topBar {
    align-items: flex-start;
    flex-direction: column;
    padding: 10px 14px;
  }

  .tableRoot {
    padding: 8px;
  }

  .battlefieldFrame {
    max-width: calc(100vw - 32px);
  }

  .battlefield {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    grid-template-rows: repeat(4, minmax(0, 1fr));
  }

  .boardFelt {
    justify-items: start;
    padding: 12px;
  }

  .boardCard {
    width: min(48px, 66%);
  }

  .rightRail {
    grid-template-columns: 1fr;
  }

  .fanCard {
    width: 84px;
    margin-right: -28px;
  }

  .reactionTray {
    width: 98vw;
  }
}

/* ------------------------------------------------------------------ */
/* Adventure map screen                                                */
/* ------------------------------------------------------------------ */

.adventureRoot {
  gap: 8px;
  /* Tray bottom frost hangs slightly past the card bar into the gap above town. */
  overflow: visible;
}

/* ------------------------------------------------------------------ */
/* Map UI redesign — a Warcraft-style command frame                    */
/*                                                                     */
/* The adventure root is a single-column grid; `order` lays its rows   */
/* out as: status ribbon (HUD) → your card bar (hand · deck · book) →  */
/* the map with its left command rail → the shared-deck shelf. This    */
/* keeps every panel's DOM (and its test contracts) exactly where it   */
/* was — only the visual row order changes. Overlays (market, prompts, */
/* feed, modals) are position:fixed, so they ignore `order`.           */
/* ------------------------------------------------------------------ */
.adventureRoot > .tableTopRow {
  order: 1;
}

.adventureRoot > .errorBanner,
.adventureRoot > .preBattlePanel {
  order: 2;
}

.adventureRoot > .playerCardBar {
  order: 3;
  overflow: visible;
}

.adventureRoot > .adventureMidRow {
  order: 4;
}

.adventureRoot > .advDecksBottom {
  order: 5;
}

.advHud {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 14px;
  padding: 8px 14px;
  background: linear-gradient(
    180deg,
    rgba(43, 31, 18, 0.92),
    rgba(28, 20, 12, 0.94)
  );
  border: 1px solid rgba(170, 130, 70, 0.35);
  border-radius: 10px;
  min-height: 56px;
  /* Wrap the status cells onto a second line rather than pushing the action
     buttons (End turn / Give up) off the right edge where they get clipped and
     become unclickable — the "the Give up button is blocked when zoomed out"
     bug. min-width:0 lets the flex row actually shrink inside its grid column. */
  flex-wrap: wrap;
  min-width: 0;
}

.advHudCell {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding-right: 14px;
  border-right: 1px solid rgba(170, 130, 70, 0.2);
}

.advHudCell strong {
  font-size: 13px;
  color: #f0dcb8;
}

.advHudCell small {
  font-size: 11px;
  color: #b89f78;
}

.advHudCell.resources {
  flex-direction: row;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: #ecd9b0;
}

.advHudCell.winner strong {
  color: #ffd76a;
}

.advHudButtons {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.menuRow.resetRow {
  display: flex;
  gap: 6px;
}

.menuRow.resetRow button {
  flex: 1;
  font-size: 11px;
}

/* Game-lifecycle group: a "GAME" label, the New adventure button, and (in
   single-player) the Save / Load slots stacked beneath it as one clear cluster. */
.menuRow.gameControlsRow {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: stretch;
}

.menuRow.gameControlsRow > .commandButton {
  font-size: 11px;
}

/* In the grouped Game cluster the save panel fills the column cleanly (its
   compact default right-aligns with a max-width, which looks stray here). */
.menuRow.gameControlsRow > .singlePlayerSavePanel.compact {
  margin: 2px 0 0;
  max-width: none;
}

.menuGroupLabel {
  font-size: 9.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  color: #d8b874;
  opacity: 0.85;
}

/* Two columns now: the right rail is gone (hero board docks in the top bar,
   the town lives in its popup window), so the map takes the freed width and
   the unit deck rides the widened left rail. */
.adventureMidRow {
  display: grid;
  grid-template-columns: 244px minmax(0, 1fr);
  gap: 12px;
  flex: 1;
  min-height: 0;
}

.mapColumn {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
}

/* The map plus its floating Far-tile tray. The tray anchors HERE (not on
   .mapColumn) so it overlays the map's top-left corner — never the town/hero
   dock sitting above the map in the same column. */
.mapStage {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
}

/* Single-player: a quiet badge while a computer opponent's hero is walked out
   step by step on the map. Purely informative — it never gates any input. */
.computerMovingBanner {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(20, 26, 38, 0.86);
  border: 1px solid rgba(159, 224, 138, 0.45);
  color: #e8f2df;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);
  pointer-events: none;
}

.computerMovingDot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #9fe08a;
  box-shadow: 0 0 8px rgba(159, 224, 138, 0.9);
  animation: computerMovingPulse 0.9s ease-in-out infinite;
}

@keyframes computerMovingPulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.opponentTurnBackdrop {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(6, 10, 18, 0.62);
  animation: overlayIn 0.18s ease-out;
}

.opponentTurnCard {
  min-width: 260px;
  max-width: 420px;
  padding: 18px 20px 16px;
  border-radius: 14px;
  background: linear-gradient(
    180deg,
    rgba(28, 34, 48, 0.98),
    rgba(18, 22, 32, 0.98)
  );
  border: 1px solid rgba(159, 224, 138, 0.4);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.55);
  color: #e8f2df;
}

.opponentTurnTitle {
  margin: 0 0 12px;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-align: center;
}

.opponentTurnBattles {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opponentTurnBattles li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.04);
  border-left: 3px solid transparent;
}

.opponentBattleWon {
  border-left-color: #9fe08a;
}

.opponentBattleLost {
  border-left-color: #e0776f;
}

.opponentBattleIcon {
  font-size: 1.05rem;
  line-height: 1.3;
}

.opponentBattleBody {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.opponentBattleLine {
  font-size: 0.9rem;
  font-weight: 600;
}

.opponentBattleReward {
  font-size: 0.78rem;
  color: #b9c6ad;
}

.opponentTurnNoBattles {
  margin: 0 0 14px;
  font-size: 0.9rem;
  color: #c7d2bd;
  text-align: center;
}

.opponentTurnActions {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.opponentTurnWatch,
.opponentTurnSkip {
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}

.opponentTurnWatch {
  background: #9fe08a;
  color: #12200c;
  border-color: rgba(159, 224, 138, 0.9);
}

.opponentTurnWatch:hover {
  background: #b0eb9c;
}

.opponentTurnSkip {
  background: rgba(255, 255, 255, 0.06);
  color: #d6dfcc;
  border-color: rgba(255, 255, 255, 0.16);
}

.opponentTurnSkip:hover {
  background: rgba(255, 255, 255, 0.12);
}

/* Positioning host for the map's floating control cards: the cards must sit
   OUTSIDE .hexMapWrap (whose `isolation: isolate` would trap their z-index
   below the Far-tile tray overlay, z-index 6) while anchoring to the exact
   same box. Takes over the wrap's flex role in the map column; the wrap keeps
   its own sizing inside. Creates NO stacking context (z-index: auto) so the
   float cards compete with the tray in the .mapStage context and win. */
.hexMapOuter {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
}

.hexMapWrap {
  flex: 1;
  min-height: min(68vh, 720px);
  background:
    radial-gradient(ellipse at 30% 20%, rgba(84, 64, 38, 0.5), transparent 60%),
    linear-gradient(180deg, #1d2433, #141a26);
  border: 1px solid rgba(170, 130, 70, 0.35);
  border-radius: 12px;
  overflow: hidden;
  /* Own stacking context so the decorative backdrop can sit at z-index:-1 —
     behind every tile, hero and overlay, but above the wrap's own fill. */
  isolation: isolate;
}

/* Decorative parchment behind the map: blurred and faint so it textures the
   empty sea/void around the tiles without touching the tile art itself
   (tiles paint above this at z-index >= 0). */
.hexMapWrap::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: url("/assets/ui/map-backdrop.jpg") center / cover no-repeat;
  filter: blur(3px) brightness(0.82) saturate(0.85);
  opacity: 0.24;
  pointer-events: none;
}

.hexMapSvg {
  width: 100%;
  height: 100%;
}

.hexCell {
  stroke: rgba(20, 14, 8, 0.85);
  stroke-width: 1.6;
  transition: filter 0.12s ease;
}

.hexCell.blocked {
  filter: brightness(0.45) saturate(0.4);
}

.hexCell.moveTarget {
  cursor: pointer;
  stroke: #ffd76a;
  stroke-width: 2.4;
  filter: brightness(1.18);
}

.hexCell.moveTarget:hover {
  filter: brightness(1.45);
}

/* Logistics (basic) / Nomads end-of-turn step: the adjacent empty fields the
   hero may step onto. A distinct pulsing teal — set apart from the golden
   click-to-move target — so the prompt's destinations read as clickable hexes
   on the board, not just buttons in the tray. */
.hexCell.endTurnMoveTarget {
  cursor: pointer;
  stroke: #57e0ff;
  stroke-width: 3;
  filter: brightness(1.3) drop-shadow(0 0 4px rgba(87, 224, 255, 0.85));
  animation: endTurnMovePulse 1.2s ease-in-out infinite;
}

.hexCell.endTurnMoveTarget:hover {
  filter: brightness(1.6) drop-shadow(0 0 7px rgba(87, 224, 255, 1));
}

/* Dimension Door / View Earth: locations named by a map choice are direct
   board controls. Violet distinguishes a spell destination from ordinary
   movement and stays visible over both the scanned tile art and icon mode. */
.hexCell.mapChoiceTarget {
  cursor: pointer;
  stroke: #d99cff;
  stroke-width: 3.4;
  fill-opacity: 0.46;
  filter: brightness(1.38) drop-shadow(0 0 6px rgb(217 156 255 / 95%));
  animation: mapChoicePulse 1.05s ease-in-out infinite;
}

.hexCell.mapChoiceTarget:hover {
  stroke: #fff0ff;
  filter: brightness(1.7) drop-shadow(0 0 10px rgb(217 156 255 / 100%));
}

@keyframes mapChoicePulse {
  0%,
  100% {
    stroke-opacity: 0.68;
  }
  50% {
    stroke-opacity: 1;
  }
}

/* Subterranean Gate exit picker: EVERY candidate hex the player may click to
   place the gate/path-up glows amber (the currently-highlighted one wears the
   brighter mapChoiceTarget purple above). Without this the alternate exits were
   invisible, so the only way to change the exit was a cycle float that could
   vanish — "the window disappears and won't work". Now the whole choice is on
   the map: click the hex you want. */
.hexCell.gateExitCandidate {
  cursor: pointer;
  stroke: #f4c95d;
  stroke-width: 3.2;
  fill-opacity: 0.4;
  filter: brightness(1.3) drop-shadow(0 0 6px rgb(244 201 93 / 90%));
  animation: mapChoicePulse 1.15s ease-in-out infinite;
}

.hexCell.gateExitCandidate:hover {
  stroke: #ffe6a3;
  filter: brightness(1.65) drop-shadow(0 0 10px rgb(244 201 93 / 100%));
}

/* Monolith / Whirlpool / colored-Gate travel picker: each destination is a
   glowing, clickable EXIT hex. A bright aqua-green — distinct from the teal
   end-of-turn move and the violet spell destination — reads as "teleport". The
   face-down overlay (a destination still riding a hidden tile) shares the glow
   but keeps a translucent fill so the token art shows through. */
.hexCell.teleportTarget,
.teleportTargetFaceDown {
  cursor: pointer;
  stroke: #5effc0;
  stroke-width: 3.4;
  filter: brightness(1.32) drop-shadow(0 0 6px rgba(94, 255, 192, 0.9));
  animation: teleportTargetPulse 1.1s ease-in-out infinite;
}

.hexCell.teleportTarget:hover,
.teleportTargetFaceDown:hover {
  stroke: #d6fff0;
  filter: brightness(1.62) drop-shadow(0 0 10px rgba(94, 255, 192, 1));
}

@keyframes teleportTargetPulse {
  0%,
  100% {
    stroke-opacity: 1;
  }
  50% {
    stroke-opacity: 0.45;
  }
}

/* "exit here" label on each teleport destination hex. */
.hexTeleportCue {
  fill: #b6ffe4;
  font-size: 9px;
  font-weight: 800;
  paint-order: stroke;
  stroke: rgba(8, 34, 26, 0.92);
  stroke-width: 2.6px;
  pointer-events: none;
}

/* Redwood Observatory's open-map Far-tile slots do not have fields yet, so a
   large dashed target is drawn at the future tile centre itself. */
.observatoryPlacementTarget {
  cursor: pointer;
  pointer-events: all;
}

.observatoryPlacementTarget circle {
  fill: rgb(29 15 43 / 68%);
  stroke: #d99cff;
  stroke-width: 3;
  stroke-dasharray: 7 5;
  filter: drop-shadow(0 0 8px rgb(217 156 255 / 90%));
}

.observatoryPlacementTarget text {
  fill: #fff0ff;
  font-size: 11px;
  font-weight: 800;
  paint-order: stroke;
  stroke: rgb(20 9 27 / 90%);
  stroke-width: 3px;
}

.observatoryPlacementTarget:hover circle {
  fill: rgb(116 53 145 / 58%);
  stroke: #fff0ff;
}

@keyframes endTurnMovePulse {
  0%,
  100% {
    stroke-opacity: 1;
  }
  50% {
    stroke-opacity: 0.4;
  }
}

/* Mandatory start-of-turn draw still pending: the fields the hero COULD step
   onto are shown LOCKED — a dimmed, dashed golden outline — and a tap reminds
   the player to draw first instead of moving. */
.hexCell.moveTargetLocked {
  cursor: not-allowed;
  stroke: #ffd76a;
  stroke-width: 2;
  stroke-dasharray: 4 3;
  stroke-opacity: 0.5;
  filter: brightness(1.04);
}

.hexCell.moveTargetLocked:hover {
  stroke-opacity: 0.85;
}

/* The brief "draw first" reminder note anchored at the tapped hex. */
.mapFloatCard.drawReminderFloat {
  border-color: rgba(255, 196, 90, 0.85);
  background: rgba(40, 22, 8, 0.97);
  color: #ffd9a0;
  animation: drawReminderFade 2.6s ease-in-out forwards;
}

/* The "you need a Subterranean Gate" hint anchored at a tapped hidden cavern. */
.mapFloatCard.gateHintFloat {
  border-color: rgba(176, 142, 214, 0.9);
  background: rgba(30, 18, 44, 0.98);
  color: #e2d2f6;
  animation: drawReminderFade 4.2s ease-in-out forwards;
  text-align: left;
  line-height: 1.35;
}

.mapFloatCard.gateHintFloat .mapFloatLabel {
  white-space: normal;
}

@keyframes drawReminderFade {
  0% {
    opacity: 0;
    transform: translateY(3px);
  }
  10%,
  80% {
    opacity: 1;
    transform: translateY(0);
  }
  100% {
    opacity: 0;
  }
}

.hexFaceDown {
  /* The printed starry back renders beneath; hexes stay as click targets. */
  fill: transparent;
  stroke: transparent;
  stroke-width: 1.6;
}

.hexFaceDown.discoverable {
  cursor: pointer;
  stroke: rgba(255, 215, 106, 0.65);
}

.hexFaceDown.discoverable:hover {
  fill: rgba(255, 215, 106, 0.16);
  stroke: #ffd76a;
}

/* A hidden Underground tile you can't discover from the Surface — tappable to
   explain the Subterranean Gate, tinted violet to read as "another layer". */
.hexFaceDown.needsGate {
  cursor: help;
  stroke: rgba(176, 142, 214, 0.5);
}

.hexFaceDown.needsGate:hover {
  fill: rgba(122, 90, 158, 0.18);
  stroke: rgba(176, 142, 214, 0.85);
}

/* Obelisk Grail clue: the face-down tiles that can still host the Ⅶ objective
   (Grail / Dragon Utopia) are the only clickable pick — a cool arcane glow so
   it never reads as an ordinary discovery (gold) or a locked cavern (violet). */
.hexFaceDown.grailClueTarget {
  cursor: pointer;
  fill: rgba(110, 200, 220, 0.16);
  stroke: rgba(140, 226, 244, 0.8);
  animation: grailCluePulse 1.8s ease-in-out infinite;
}

.hexFaceDown.grailClueTarget:hover {
  fill: rgba(140, 226, 244, 0.3);
  stroke: #b6f0ff;
}

@keyframes grailCluePulse {
  0%,
  100% {
    stroke-opacity: 0.55;
  }
  50% {
    stroke-opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hexFaceDown.grailClueTarget {
    animation: none;
  }
}

.tileBackArt {
  pointer-events: none;
}

.hexFaceDownLabel {
  fill: #c8a96d;
  font-size: 11px;
  pointer-events: none;
  font-weight: 600;
}

/* "via Subterranean Gate" label on a hidden cavern; "↧ descend / ↥ ascend" cue
   on a reachable gate hex. */
.hexCavernHint {
  fill: #d7c2f0;
  font-size: 8.5px;
  font-weight: 600;
  paint-order: stroke;
  stroke: rgba(28, 16, 40, 0.85);
  stroke-width: 2.4px;
  pointer-events: none;
}

.hexGateCue {
  fill: #ffe9bd;
  font-size: 9px;
  font-weight: 700;
  paint-order: stroke;
  stroke: rgba(28, 16, 40, 0.9);
  stroke-width: 2.6px;
  pointer-events: none;
}

/* "gate here / path up here" label on each candidate hex while the pick-on-reveal
   Subterranean Gate placement choice is open. Short words + thick halo so the
   cue stays legible over busy tile art without covering the cave-mouth graphic. */
.hexGateChoiceCue {
  fill: #9be7ff;
  font-size: 8px;
  font-weight: 800;
  paint-order: stroke;
  stroke: rgba(10, 24, 40, 0.95);
  stroke-width: 3px;
  pointer-events: none;
}

.hexGateChoiceCue.selected {
  fill: #e8fff8;
  font-size: 8.5px;
  stroke: rgba(6, 28, 22, 0.96);
  stroke-width: 3.2px;
  filter: drop-shadow(0 0 3px rgba(94, 255, 192, 0.85));
}

.hexGateChoiceCue.dim {
  fill: rgba(155, 231, 255, 0.55);
  font-size: 7px;
  stroke-width: 2.2px;
  stroke-opacity: 0.85;
}

.hexGlyph {
  font-size: 17px;
  pointer-events: none;
}

/* Atmosphere tiles (anime seats): modular field icons attached over art. */
.fieldSymbolModule {
  pointer-events: none;
  filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.85))
    drop-shadow(0 1px 2px rgba(0, 0, 0, 0.55));
}

.hexDifficulty {
  fill: #ffe9bd;
  font-size: 12px;
  font-weight: 700;
  paint-order: stroke;
  stroke: rgba(20, 12, 4, 0.9);
  stroke-width: 2.6;
  pointer-events: none;
}

/* Designer-ALTERED guard: a faint amber outline on the hex + a small gear so an
   altered neutral fight (custom army / level / forced settlement) reads at a
   glance. The tooltip and the pre-attack confirm carry the detail. */
.hexCell.alteredGuard {
  stroke: #e6b34a;
  stroke-width: 2.2;
}

.hexAlteredGuard {
  fill: #ffd98a;
  font-size: 9px;
  paint-order: stroke;
  stroke: rgba(20, 12, 4, 0.92);
  stroke-width: 2.2;
  pointer-events: none;
}
.hexDesignerReward {
  fill: #9dffb0;
  font-size: 9px;
  paint-order: stroke;
  stroke: rgba(8, 20, 10, 0.92);
  stroke-width: 2.2;
  pointer-events: none;
}

/* The Creature Bank a tile drew at reveal, named on its Blocked Field while the
   player rotates (so they know the bank before committing the rotation). */
.hexBankLabel {
  fill: #ffe1a6;
  font-size: 7.2px;
  font-weight: 800;
  paint-order: stroke;
  stroke: rgba(18, 10, 3, 0.92);
  stroke-width: 2.4;
  pointer-events: none;
}

.bankSizeCombatChip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex: 0 0 auto;
  padding: 4px 8px 4px 6px;
  border: 1px solid rgba(28, 15, 6, 0.9);
  border-radius: 999px;
  color: #1b1008;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.03em;
  box-shadow:
    0 2px 5px rgba(0, 0, 0, 0.48),
    inset 0 1px rgba(255, 255, 255, 0.32);
}

.bankSizeCombatChip > .bankSizeCoin {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 2px solid rgba(32, 17, 7, 0.88);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 950;
  line-height: 1;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.2),
    0 1px 2px rgba(0, 0, 0, 0.55);
}

/* Polish Creature Bank size = number of Stacked defenders. Coloured by size:
   1 black, 2 brown, 3 silver, 4 gold (the v1.2 sheet's coin colours). */
.bankSizeCombatChip.size-1 {
  background: linear-gradient(180deg, #4a4a4f, #23232a);
  color: #f2f2f5;
}

.bankSizeCombatChip.size-2 {
  background: linear-gradient(180deg, #c8793d, #874018);
  color: #fff1d7;
}

.bankSizeCombatChip.size-3 {
  background: linear-gradient(180deg, #f0f0f0, #aaa);
}

.bankSizeCombatChip.size-4 {
  background: linear-gradient(180deg, #f4db6a, #b9901f);
}

.bankSizeCombatChip.size-1 .bankSizeCoin {
  background: radial-gradient(circle at 35% 30%, #6a6a70, #2b2b31 68%, #121216);
  color: #f4f4f6;
}

.bankSizeCombatChip.size-2 .bankSizeCoin {
  background: radial-gradient(circle at 35% 30%, #e29a63, #9b4b22 68%, #5d260f);
  color: #fff3dc;
}

.bankSizeCombatChip.size-3 .bankSizeCoin {
  background: radial-gradient(circle at 35% 30%, #fff, #b9c1c8 68%, #737d86);
  color: #1a1d20;
}

.bankSizeCombatChip.size-4 .bankSizeCoin {
  background: radial-gradient(circle at 35% 30%, #fff0a0, #d4aa28 68%, #83600c);
  color: #241603;
}

.bankPreviewSecondRing {
  fill: rgba(10, 7, 4, 0.92);
  stroke: #ffe39a;
  stroke-width: 2.4px;
  pointer-events: none;
}

/* Polish house-rule bank-size markers from the v1.2 sheet. The coin shows the
   size = number of Stacked defenders (1-4), coloured 1 black / 2 brown /
   3 silver / 4 gold. */
.bankSizeSvgBadge {
  pointer-events: none;
  filter: drop-shadow(0 1.5px 1px rgba(0, 0, 0, 0.92));
}

.bankSizeSvgBadge circle {
  stroke: #1b1008;
  stroke-width: 1.3px;
  paint-order: stroke fill;
}

.bankSizeSvgBadge text {
  fill: #170d05;
  font-size: 6.5px;
  font-weight: 950;
  pointer-events: none;
}

.bankSizeSvgBadge.size-1 .coinOuter {
  fill: #22222a;
}

.bankSizeSvgBadge.size-1 .coinInner {
  fill: #52525a;
}

.bankSizeSvgBadge.size-1 text {
  fill: #f2f2f5;
}

.bankSizeSvgBadge.size-2 .coinOuter {
  fill: #91461f;
}

.bankSizeSvgBadge.size-2 .coinInner {
  fill: #cf7a40;
}

.bankSizeSvgBadge.size-3 .coinOuter {
  fill: #8d98a3;
}

.bankSizeSvgBadge.size-3 .coinInner {
  fill: #dde4e8;
}

.bankSizeSvgBadge.size-4 .coinOuter {
  fill: #aa7c10;
}

.bankSizeSvgBadge.size-4 .coinInner {
  fill: #e9c84f;
}

.bankSizeSvgBadge.placed {
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.96));
}

.dungeonFloorSvgBadge {
  pointer-events: none;
  filter: drop-shadow(0 1px 2px #000);
}

.dungeonFloorSvgBadge rect {
  fill: rgba(15, 8, 24, 0.9);
  stroke: #e4bc62;
  stroke-width: 1.5;
}

.dungeonFloorSvgBadge text {
  fill: #fff1bf;
  font-family: Georgia, serif;
  font-weight: 800;
}

/* Field Override (WOG / anime) hex: a small unobtrusive corner glyph badge so a
   zoomed-out player can spot the hex is special and hover/tap it. */
.fieldOverrideGlyphBadge {
  pointer-events: none;
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.9));
}

.fieldOverrideGlyphBadge circle {
  fill: rgba(20, 14, 8, 0.82);
  stroke: rgba(255, 224, 150, 0.7);
  stroke-width: 1px;
}

.fieldOverrideGlyphBadge text {
  font-size: 9px;
  pointer-events: none;
}

.hexProduction {
  fill: #ffe9bd;
  font-size: 10px;
  paint-order: stroke;
  stroke: rgba(20, 12, 4, 0.85);
  stroke-width: 2.2;
  pointer-events: none;
}

.blackCube {
  fill: #14100c;
  stroke: rgba(220, 190, 130, 0.6);
  stroke-width: 0.8;
  pointer-events: none;
}

.flagPole,
.heroFlagPole {
  stroke: #1d1206;
  stroke-width: 1.6;
}

.heroPawnBase {
  fill: #14100c;
}

.placementGhost {
  fill: rgba(255, 215, 106, 0.18);
  stroke: #ffd76a;
  stroke-dasharray: 5 4;
  stroke-width: 1.6;
  cursor: pointer;
}

.placementGhost:hover {
  fill: rgba(255, 215, 106, 0.35);
}

/* The Ⅱ–Ⅲ Far-tile supply sits as a compact pile in the map's TOP-LEFT corner
   (it used to be a strip below the map). It glows when at least one tile can be
   opened this turn so the player notices the option without a pop-up notice. */
.farTileTray {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 6;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  max-width: 232px;
  padding: 6px 10px;
  background: rgba(33, 25, 15, 0.92);
  border: 1px solid rgba(170, 130, 70, 0.3);
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5);
}

.farTileTray.usable {
  border-color: rgba(255, 215, 106, 0.85);
  box-shadow:
    0 0 14px rgba(255, 215, 106, 0.55),
    0 4px 14px rgba(0, 0, 0, 0.5);
}

.farTileTray small {
  color: #b89f78;
  flex-basis: 100%;
}

/* Optional positive-Morale spend ("Morale: draw 1 / redraw cards"). It carries
   the `handDirectives` class too, so it inherits the EXACT ornate hand-step
   look (leather panel + HoMM3 button plates) — the desktop fixed-banner rules
   are scoped to `.playerCardBar .handDirectives`, so they do NOT apply here.
   This class only RE-POSITIONS it: a compact vertical box to the RIGHT of the
   Far-tile tray (232px at left:10px), clamped so it never spills off a narrow
   (phone) map. */
.mapMoraleSpend.handDirectives {
  position: absolute;
  top: 10px;
  left: min(252px, calc(100% - 176px));
  z-index: 7;
  width: max-content;
  max-width: 176px;
  padding: 8px 10px 10px;
}

.commandButton.selected {
  outline: 2px solid #ffd76a;
}

.commandButton.primary {
  background: linear-gradient(180deg, #8c6a2c, #6e5122);
  color: #ffe9bd;
}

/* ---- Hero board (printed-board recreation, scales with its container) ---- */
.hbWrap {
  container-type: inline-size;
}

.hb {
  --hb-gold: #e8c96a;
  --hb-pale: #f3e6bf;
  --hb-bronze: #a87c41;
  --hb-leather: #6a4423;
  --hb-leather-2: #46290f;
  --hb-slate: #1b1d21;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 1.4cqw;
  padding: 3.4cqw 3.4cqw 2.4cqw;
  border-radius: 3.4cqw;
  border: 1px solid #000;
  background:
    radial-gradient(
      130% 80% at 18% 0%,
      rgba(255, 244, 214, 0.05),
      transparent 46%
    ),
    radial-gradient(120% 90% at 88% 110%, rgba(0, 0, 0, 0.5), transparent 50%),
    #16110b;
  box-shadow: 0 1.4cqw 3cqw rgba(0, 0, 0, 0.55);
  overflow: hidden;
}

/* Printed double frame: faction piping outside, bronze ornament inside. */
.hb::after {
  content: "";
  position: absolute;
  inset: 0.8cqw;
  border: 0.35cqw solid var(--hb-edge, #3f6fb5);
  border-radius: 2.8cqw;
  opacity: 0.65;
  pointer-events: none;
}

.hb::before {
  content: "";
  position: absolute;
  inset: 1.7cqw;
  border: 0.45cqw solid var(--hb-bronze);
  border-radius: 2.2cqw;
  box-shadow:
    inset 0 0 0 0.25cqw rgba(0, 0, 0, 0.75),
    0 0 0 0.25cqw rgba(0, 0, 0, 0.75),
    inset 0 0 2.4cqw rgba(0, 0, 0, 0.55);
  pointer-events: none;
  z-index: 1;
}

.hb > * {
  position: relative;
  z-index: 2;
}

.hb button {
  appearance: none;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  color: inherit;
  font: inherit;
  text-align: inherit;
}

.hbTop {
  display: grid;
  grid-template-columns: 41% 1fr;
  gap: 2.2cqw;
  align-items: stretch;
}

.hbPortrait {
  position: relative;
  display: flex;
  padding: 0.7cqw;
  border-radius: 1.6cqw;
  background: linear-gradient(
    150deg,
    #c89a52,
    #6e4d22 45%,
    #d8b06a 80%,
    #5d3e1a
  );
  box-shadow: 0 0.5cqw 1.4cqw rgba(0, 0, 0, 0.6);
}

.hbPortrait img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 0;
  aspect-ratio: 58 / 64;
  object-fit: cover;
  border-radius: 1cqw;
  background: #0d0a06;
}

/* Public Grail-carrier badge (map-designer dig → carry). */
.hbGrailMarker {
  position: absolute;
  right: 0.4cqw;
  bottom: 0.4cqw;
  z-index: 2;
