/* Card-art windows: a fixed crop over the scanned card recovers the art. */
.hbArt {
  position: relative;
  overflow: hidden;
  border-radius: 0.8cqw;
  background: #20150a;
  filter: drop-shadow(0 0.4cqw 0.7cqw rgba(0, 0, 0, 0.55));
}

.hbArt img {
  position: absolute;
  left: 0;
  top: 0;
  display: block;
  max-width: none;
}

.hbArt-ability {
  width: 78%;
  max-width: 21cqw;
  aspect-ratio: 1.12;
}

.hbArt-ability img {
  width: 200%;
  transform: translate(-25%, -7%);
}

.hbArt-specialty {
  width: 11.6cqw;
  aspect-ratio: 1.05;
  border: 0.35cqw solid rgba(190, 146, 82, 0.75);
  box-shadow: inset 0 0 0 0.25cqw rgba(0, 0, 0, 0.8);
}

.hbArt-specialty img {
  width: 262%;
  transform: translate(-31%, -9.5%);
}

/* Art-less specialty thumbnail: the specialty symbol, contained in the slot
   (full native card opens on zoom). Overrides the .hbArt img crop above. */
.hbArt .hbSpecIcon {
  position: absolute;
  inset: 8%;
  width: 84%;
  height: 84%;
  object-fit: contain;
  transform: none;
}

.hbArtEmpty {
  background:
    radial-gradient(
      80% 80% at 50% 40%,
      rgba(255, 222, 160, 0.12),
      transparent 70%
    ),
    #2a1b0c;
}

/* ---- Experience track: the AUTHENTIC printed mat art ----
   The green marble strip — with the laurelled Ⅰ–Ⅶ numerals, the blue connector
   arrows and the hand-limit / crown icons — is the real printed scan
   (xp-track.webp; identical on every hero mat, so one shared crop). The 13
   die-cut boxes are TRANSPARENT holes in that art; each .hbXpBox is positioned
   exactly over its hole (inline % from HOLE_RECTS) so the specialty / ability
   card shows THROUGH it, like a card slid behind the printed board. The current
   XP box wears a glowing gold frame + a subtle cube in its corner — the only
   markers, and neither covers the card art. */
.hbTrack {
  position: relative;
  border-radius: 1.4cqw;
}

.hbTrackArt {
  position: relative;
  width: 100%;
  border-radius: 1.2cqw;
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  /* aspect-ratio is set inline (XP_TRACK_ASPECT) so the % hole coords hold. */
}

/* One die-cut hole: a transparent window laid exactly over the art's punched
   box (left/top/width/height come inline from HOLE_RECTS). It has no fill of
   its own — the card in it (top row) or the dark table beneath (empty holes)
   shows through the transparent art. */
.hbXpBox {
  position: absolute;
  border-radius: 0.9cqw;
}

.hbSlot {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 0.7cqw;
  overflow: hidden;
}

button.hbSlot {
  cursor: zoom-in;
}
button.hbSlot:disabled {
  cursor: default;
}

/* Specialty / kept-ability card art fills its hole exactly (the card shows
   through the die-cut window — no frame of its own; the art's hole is the
   frame). */
.hbSlotSpecialty .hbArt,
.hbSlotAbilityPick .hbArt {
  width: 100%;
  height: 100%;
  max-width: none;
  aspect-ratio: auto;
  border: none;
  border-radius: 0;
  filter: none;
  background: none;
}

.hbSlotSpecialty .hbArt img {
  width: 286%;
  transform: translate(-32.5%, -10.5%);
}

.hbSlotAbilityPick .hbArt-ability img {
  width: 200%;
  transform: translate(-25%, -8%);
}

/* Not yet earned: the specialty card still shows through its hole, dimmed as a
   preview. */
.hbSlotSpecialty.preview .hbArt {
  filter: grayscale(0.6) brightness(0.62);
}

/* CURRENT box: the level marker — a glowing gold frame hugging the hole. It
   sits OUTSIDE the hole (box-shadow spread), so the card art is never covered. */
.hbXpBox.current {
  box-shadow:
    0 0 0 0.35cqw rgba(255, 238, 182, 0.95),
    0 0 2.4cqw rgba(232, 201, 106, 0.95),
    inset 0 0 1.2cqw rgba(232, 201, 106, 0.5);
  animation: hbCurrentGlow 2.4s ease-in-out infinite;
}

/* The subtle progress cube — a small faction-coloured gem tucked into the
   current box's top-right corner. Marks exactly which box (half-step included)
   you are on, without blocking the specialty / ability art. */
.hbCube {
  position: absolute;
  top: -0.9cqw;
  right: -0.9cqw;
  width: 2.7cqw;
  height: 2.7cqw;
  transform: rotate(45deg);
  border-radius: 0.5cqw;
  background: radial-gradient(
    125% 125% at 32% 26%,
    #fff 0%,
    var(--hb-cube, #2f6fd0) 46%,
    color-mix(in srgb, var(--hb-cube, #2f6fd0) 52%, #000) 100%
  );
  border: 0.25cqw solid rgba(255, 244, 214, 0.95);
  box-shadow:
    0 0.3cqw 0.7cqw rgba(0, 0, 0, 0.7),
    0 0 1.2cqw color-mix(in srgb, var(--hb-cube, #2f6fd0) 80%, transparent);
  z-index: 3;
  pointer-events: none;
}

@keyframes hbCurrentGlow {
  0%,
  100% {
    box-shadow:
      0 0 0 0.3cqw rgba(255, 238, 182, 0.85),
      0 0 1.6cqw rgba(232, 201, 106, 0.7),
      inset 0 0 1cqw rgba(232, 201, 106, 0.42);
  }
  50% {
    box-shadow:
      0 0 0 0.42cqw rgba(255, 246, 206, 1),
      0 0 3.4cqw rgba(232, 201, 106, 1),
      inset 0 0 1.4cqw rgba(232, 201, 106, 0.68);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hbXpBox.current {
    animation: none;
  }
}

