@media (prefers-reduced-motion: reduce) {
  .setupWisp,
  .setupWispImg,
  .setupMote {
    animation: none !important;
    transform: none;
  }
  .setupWisp {
    opacity: 0;
  }
  .setupWisp1,
  .setupWisp3 {
    opacity: 0.55;
  }
  .setupWispImg {
    opacity: 1;
