/* Frost only the top HUD + Game options tab — Heroes & draft stays clear so
   the Gold Dragon backdrop reads through that tab. */
.setupPhase .advHud,
.setupLobby .gameOptions {
  backdrop-filter: blur(3px);
}

/* Keep interactive setup chrome above the fixed ambient wisp layer (z-index 0). */
.setupPhase > .tableTopRow,
.setupPhase > .setupLobby,
.setupPhase > .logDrawer,
.setupPhase > .errorBanner {
  position: relative;
  z-index: 1;
}

/* Map-setup lobby */
.setupLobby {
  /* Sit above the fixed backdrop scene so the panels always read on top. */
  position: relative;
  z-index: 1;
  /* The grid parent (.tableRoot) orders the top bar at `order:1`; without an
     order the lobby would default to 0 and jump ABOVE the "Map setup" top bar,
     leaving that bar floating in the middle of the screen. Order it (and the
     game-log drawer below) AFTER the top bar + error banner. */
  order: 3;
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 22px 14px;
  max-width: 1080px;
  margin: 0 auto;
  width: 100%;
}

/* Keep the game-log drawer at the bottom of the setup screen, below the lobby
   (same reason as above — it also defaults to order 0). */
.setupPhase > .logDrawer {
  order: 4;
}

.setupLobby header h2 {
  margin: 0 0 6px;
  color: #ffe9bd;
  text-shadow:
    0 2px 10px rgb(0 0 0 / 82%),
    0 0 4px rgb(0 0 0 / 70%);
}

.setupLobby header p {
  margin: 0;
  color: #dcc79c;
  max-width: 70ch;
  text-shadow:
    0 1px 6px rgb(0 0 0 / 88%),
    0 0 3px rgb(0 0 0 / 70%);
}

/* Red take-back warning broadcast to every player when a seat resets a roll,
   town or pick during setup. Loud on purpose so the table notices the do-over. */
.setupCheatWarning {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  align-items: flex-start;
  gap: 10px;
