  text-shadow: 0 1px 3px rgb(0 0 0 / 85%);
}

.setupLobby .optionButtons button:hover {
  border-color: rgba(214, 178, 94, 0.8);
}

.setupLobby .optionButtons button.selected {
  background: linear-gradient(180deg, #e8c576, #c2933f);
  color: #2a1c08;
  border-color: #ffd76a;
