}

/* ------------------------------------------------------------------------ */
/* Setup Hub — the four big icon boxes (Game mode · Heroes & Draft · Map ·
   Advanced settings), centered mid-screen in a 2×2 grid, each opening a
   popup window and summarizing the current choice underneath. */
.setupHubGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(220px, 300px));
  justify-content: center;
  gap: 14px;
  /* Center the boxes in the leftover space between the seats row and the
     Start button (the button below takes the matching auto margin). With a
     short viewport the autos collapse to 0 and the page simply scrolls. */
  margin-top: auto;
  padding: 4px 0 2px;
}

/* The lobby's Start button is the same art button the menu uses; cap its height
   here so the four boxes stay the screen's centre of gravity. */
.setupLobby > .newGameMenuButton {
  width: min(200px, 60vw);
  margin-bottom: auto;
}

.setupLobby > .newGameMenuButton .newGameMenuLabel {
  font-size: 19px;
}

/* The table chat docks bottom-LEFT at up to 380px wide (z-index 200). On a wide
   screen the centered Start button clears it horizontally; on a narrow one the
   dock spans the column, so reserve room to scroll the button out from under it. */
@media (max-width: 820px) {
  .setupLobby {
    padding-bottom: calc(56vh + 32px);
  }

  /* Flow from the top instead of centering: on a narrow screen the auto margins
     would park the Start button near the dock AND move it every time the dock
     grows a line. */
  .setupHubGrid,
  .setupLobby > .newGameMenuButton {
    margin-top: 0;
    margin-bottom: 0;
  }

  .setupLobby > .newGameMenuButton {
    margin-inline: auto;
  }
}

/* The setup screen reads as a title screen: the whole column is centered on the
   four boxes (the in-game table keeps its left-aligned panels). */
.setupLobby > header,
.setupLobby > header p,
.setupLobby > .helperCoachLobbyNote {
  text-align: center;
  margin-inline: auto;
}

.setupLobby > .lobbySeats {
  justify-content: center;
}

/* Each box is a full-bleed PAINTED PANEL (SETUP_HUB_ART, frame baked into the
   art) with the title/summary on a dark bottom plate — the AAA-menu-tile idiom
   (Diablo/StarCraft campaign buttons), replacing the old icon-in-a-circle. */
.setupHubBox {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  /* The panel art is 3:2 with its ornate frame BAKED IN — matching the box's
     aspect means the frame is never cropped away (the box still grows if a
     long summary needs more room; `cover` absorbs that case). */
  aspect-ratio: 3 / 2;
  padding: 0;
  border: 1px solid rgba(163, 126, 64, 0.7);
  border-radius: 12px;
  overflow: hidden;
  isolation: isolate;
  /* Fallback ground while the panel art streams in. */
  background: linear-gradient(
    165deg,
    rgba(46, 33, 17, 0.95),
    rgba(18, 13, 7, 0.97) 70%
  );
  color: #e7d3a8;
  cursor: pointer;
  box-shadow:
    inset 0 0 0 1px rgba(255, 227, 172, 0.08),
    0 12px 28px rgba(0, 0, 0, 0.55);
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
  animation: setupHubBoxIn 0.5s cubic-bezier(0.22, 0.9, 0.28, 1) both;
}

/* Staggered entrance, reading order. */
.setupHubBox--mode {
  animation-delay: 0.04s;
}
.setupHubBox--heroes {
  animation-delay: 0.12s;
}
.setupHubBox--map {
  animation-delay: 0.2s;
}
.setupHubBox--advanced {
  animation-delay: 0.28s;
}

@keyframes setupHubBoxIn {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

/* A slow ember "breath" on the inner rim so the panels feel alive at rest. */
.setupHubBox::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 26px rgba(255, 186, 92, 0.16);
  animation: setupHubBreath 5.4s ease-in-out infinite;
}

.setupHubBox--heroes::after {
  animation-delay: 1.3s;
}
.setupHubBox--map::after {
  animation-delay: 2.6s;
}
.setupHubBox--advanced::after {
  animation-delay: 3.9s;
}

@keyframes setupHubBreath {
  0%,
  100% {
    opacity: 0.25;
  }

  50% {
    opacity: 0.75;
  }
}

.setupHubBox:hover,
.setupHubBox:focus-visible {
  transform: translateY(-4px);
  border-color: #ffd76a;
  box-shadow:
    inset 0 0 0 1px rgba(255, 227, 172, 0.16),
    0 0 24px rgba(224, 170, 76, 0.34),
    0 18px 36px rgba(0, 0, 0, 0.62);
}

/* The painted panel: art (cover-cropped), a bottom shade for the text plate,
   and the hover light-sweep. All aria-hidden presentation. */
.setupHubBoxArt {
  position: absolute;
  inset: 0;
  display: block;
  overflow: hidden;
  z-index: -1;
}

.setupHubBoxArtImg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.97) brightness(0.95);
  transition:
    transform 0.6s cubic-bezier(0.2, 0.7, 0.2, 1),
    filter 0.3s ease;
}

.setupHubBox:hover .setupHubBoxArtImg,
.setupHubBox:focus-visible .setupHubBoxArtImg {
  transform: scale(1.07);
  filter: saturate(1.08) brightness(1.06);
}

.setupHubBoxArtShade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(10, 7, 3, 0) 36%,
    rgba(10, 7, 3, 0.4) 58%,
    rgba(8, 5, 2, 0.86) 84%,
    rgba(6, 4, 2, 0.94) 100%
  );
}

/* Travelling light sweep across the art on hover/focus (torchlight pass). */
.setupHubBoxSheen {
  position: absolute;
  top: -20%;
  bottom: -20%;
  left: -60%;
  width: 45%;
  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(255, 232, 180, 0.26) 45%,
    rgba(255, 246, 220, 0.4) 50%,
    rgba(255, 232, 180, 0.26) 55%,
    transparent 100%
  );
  transform: skewX(-18deg);
  opacity: 0;
  pointer-events: none;
}

.setupHubBox:hover .setupHubBoxSheen,
.setupHubBox:focus-visible .setupHubBoxSheen {
  animation: setupHubSheen 0.9s ease 0.05s 1;
}

@keyframes setupHubSheen {
  0% {
    opacity: 0;
    transform: skewX(-18deg) translateX(0);
  }

  12% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform: skewX(-18deg) translateX(430%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .setupHubBox,
  .setupHubBox::after,
  .setupHubBoxSheen,
  .setupHubBoxArtImg {
    animation: none !important;
    transition: none !important;
  }
}

/* The text plate the shade keeps readable, pinned to the panel bottom. */
.setupHubBoxPlate {
  position: relative;
  display: grid;
  gap: 4px;
  justify-items: center;
  width: 100%;
  padding: 10px 12px 12px;
}

.setupHubBoxTitle {
