  gap: 3px;
  justify-items: center;
  font-size: 12px;
  line-height: 1.35;
  color: #cdb68a;
  text-align: center;
}

.setupHubBoxLine {
  display: block;
  max-width: 26ch;
}

.setupHubBoxDim {
  opacity: 0.78;
  font-size: 11px;
}

.setupHubChips {
  display: inline-flex;
  gap: 4px;
}

.setupHubChip {
  padding: 1px 8px;
  border: 1px solid rgba(193, 130, 225, 0.6);
