.setupHubBoxTitle {
  font-size: clamp(12px, 1.45vw, 17px);
}
.setupHubBoxSummary {
  font-size: 10px;
}
.setupHubBoxDim {
  font-size: 9px;
}

.setupHubBox::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -38px;
  width: 18px;
  height: 29px;
  border-radius: 50% 50% 54% 54%;
  background: radial-gradient(
    circle at 34% 24%,
    #fff4a8,
    #e2a339 34%,
    #783417 86%
  );
  box-shadow: 0 0 12px 4px rgba(255, 197, 73, 0.36);
  transform: translateX(-50%);
  animation: setupHubFruitGlow 3.2s ease-in-out infinite;
