.setupHubBox--heroes::before {
  animation-delay: -0.8s;
}
.setupHubBox--map::before {
  animation-delay: -1.7s;
}
.setupHubBox--advanced::before {
  animation-delay: -2.5s;
}

@keyframes setupHubFruitGlow {
  0%,
  100% {
    filter: brightness(0.9);
    box-shadow: 0 0 8px 2px rgba(255, 197, 73, 0.22);
  }
  50% {
    filter: brightness(1.25);
    box-shadow: 0 0 18px 7px rgba(255, 197, 73, 0.52);
  }
}

.setupHubBox:hover::before,
.setupHubBox:focus-visible::before,
