.setupSceneFruit--heroes {
  left: 47.8%;
  top: 1.8%;
  animation-delay: -2.4s;
}
.setupSceneFruit--advanced {
  left: 58.2%;
  top: 1.8%;
  animation-delay: -0.2s;
}

