  border: 1px solid rgb(237 182 82 / 72%);
  border-radius: 999px;
  background: linear-gradient(180deg, rgb(94 45 13 / 92%), rgb(26 11 4 / 96%));
  box-shadow:
    0 0 18px rgb(255 137 35 / 34%),
    inset 0 0 16px rgb(255 191 68 / 18%);
}

.setupSceneStartButton .newGameMenuIcon {
  display: none;
}
.setupSceneStartButton .newGameMenuLabel {
  position: static;
  transform: none;
  font-size: 14px;
}

/* The room control stays available in the corner without covering the
   Advanced fruit. Its full manager still opens from the compact toggle. */
.setupPhase .roomPanel {
  width: min(250px, 24vw);
  flex: 0 0 min(250px, 24vw);
}

.setupPhase .roomPanel .roomToggle {
  width: 100%;
}

/* The hub popup shell sits ABOVE the docked table chat (z-index 200), which
   would otherwise cover the window's bottom-left corner. The two dialogs that
   open from INSIDE a hub window — the hero-info popup (normally 120) and the
   WOG/Anime mod windows (130) — are lifted over it for exactly that window's
   lifetime, keeping the same relative order without touching any other screen. */
.setupHubBackdrop {
  position: fixed;
  inset: 0;
  z-index: 210;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(7, 5, 3, 0.66);
  backdrop-filter: blur(2px);
}

body:has(.setupHubBackdrop) .heroInfoBackdrop {
  z-index: 220;
}

body:has(.setupHubBackdrop) .wogWindowBackdrop {
  z-index: 230;
}

.setupHubWindow {
  display: flex;
  flex-direction: column;
  width: min(760px, 96vw);
  max-height: min(86vh, 860px);
  border: 1px solid rgba(214, 178, 94, 0.66);
  border-radius: 14px;
  background:
    radial-gradient(circle at 18% 0%, rgba(140, 100, 40, 0.3), transparent 42%),
    linear-gradient(160deg, #241a0e, #120d07 70%);
  color: #e9d6ab;
  box-shadow:
    0 26px 80px rgba(0, 0, 0, 0.72),
    inset 0 0 0 1px rgba(255, 227, 172, 0.08);
  outline: none;
  animation: setupHubWindowIn 0.18s ease-out;
}

@keyframes setupHubWindowIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.setupHubWindow--mode {
  width: min(900px, 96vw);
}

.setupHubWindow--heroes,
.setupHubWindow--advanced {
  width: min(1080px, 96vw);
}

.setupHubWindow--map {
  width: min(980px, 96vw);
}

.setupHubWindowHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px 10px;
  border-bottom: 1px solid rgba(170, 130, 70, 0.35);
}

.setupHubWindowEyebrow {
  display: block;
  color: #c9a55e;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.setupHubWindowHead h3 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 20px;
  color: #ffe7a1;
}

.setupHubWindowClose {
  display: inline-grid;
  place-items: center;
  min-width: 34px;
  min-height: 30px;
  border: 1px solid rgba(214, 178, 94, 0.5);
  border-radius: 7px;
  background: rgba(52, 38, 20, 0.8);
  color: #ffe9bd;
  cursor: pointer;
}

.setupHubWindowClose:hover {
  border-color: #ffd76a;
}

.setupHubWindowBody {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 16px 16px;
  overflow-y: auto;
}

/* The picker fills the window; the live summary of choices lives on the setup
   scene now (SetupSummaryRail), not inside each window. */
.setupHubWindowContent {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1 1 auto;
}

/* --- Setup summary rail: all four boxes' live choices, pinned right of the
   scene, half-transparent, one click into any box. Item chips (below) are
   shared with nothing else now; the container styles are the rail's own. --- */
.setupSummaryRail {
  position: fixed;
  /* Above the full-screen .setupHubGrid scene layer (z 8), which otherwise
     paints over the rail and steals its clicks; still far below the hub-window
     backdrop (210) so a popup covers it. */
  z-index: 9;
  top: 50%;
  right: 12px;
  transform: translateY(-50%);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: 6px;
  width: 178px;
  max-height: calc(100vh - 168px);
  padding: 9px 9px 10px;
  border: 1px solid rgba(170, 130, 70, 0.34);
  border-radius: 11px;
  background: linear-gradient(
    180deg,
    rgba(34, 24, 12, 0.62),
    rgba(14, 10, 6, 0.44)
  );
  box-shadow:
    inset 0 1px 0 rgba(255, 232, 161, 0.1),
    0 10px 26px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(7px);
  opacity: 0.82;
  overflow-y: auto;
  transition: opacity 140ms ease;
}

.setupSummaryRail:hover,
.setupSummaryRail:focus-within {
  opacity: 1;
}

.setupSummaryRailTitle {
  padding: 0 2px 1px;
  color: #c9a55e;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}

/* Hidden where the fixed rail would collide with the phone 2×2 box grid; the
   painted boxes stay the setup surface there. */
.phoneMode .setupSummaryRail {
  display: none;
}

/* Narrow desktop windows: nothing to shrink — the rail auto-hides via the
   phone rule above and the max-height keeps it scrollable on short screens. */

.setupHubNavItem {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid rgba(150, 116, 60, 0.4);
  border-radius: 8px;
  background: rgba(44, 32, 17, 0.7);
  color: inherit;
  text-align: left;
  font: inherit;
}

button.setupHubNavItem {
  cursor: pointer;
}

button.setupHubNavItem:hover {
  border-color: #ffd76a;
  background: rgba(66, 48, 24, 0.9);
}

.setupHubNavIcon {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  border-radius: 4px;
  object-fit: cover;
}

.setupHubNavText {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.setupHubNavText small {
  color: #c9a55e;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.setupHubNavText strong,
.setupHubNavText em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.setupHubNavText strong {
  color: #ffe9bd;
  font-size: 11px;
  font-weight: 600;
}

.setupHubNavText em {
  color: #c2ae86;
  font-size: 9.5px;
  font-style: normal;
}

/* "Same choice as the <box> box" note on the Advanced window's shared rows. */
.sameChoiceNote {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.sameChoiceLink {
  padding: 2px 8px;
  border: 1px solid rgba(214, 178, 94, 0.55);
  border-radius: 999px;
  background: rgba(52, 38, 20, 0.8);
  color: #ffe9bd;
  font: inherit;
  font-size: 10px;
  cursor: pointer;
}

.sameChoiceLink:hover {
  border-color: #ffd76a;
}

/* --- Map window: filters · list · shape preview · chess difficulty bar --- */
.mapPickFilters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.mapPickFilterChips {
  display: inline-flex;
  gap: 4px;
}

.mapPickFilterChips button {
  padding: 5px 11px;
  border: 1px solid rgba(150, 116, 60, 0.45);
  border-radius: 999px;
  background: rgba(35, 26, 14, 0.55);
  color: #d8c39a;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.mapPickFilterChips button:hover {
  border-color: rgba(214, 178, 94, 0.8);
  color: #ffe9bd;
}

.mapPickFilterChips button.selected {
  border-color: #ffd76a;
  background: linear-gradient(180deg, #e8c576, #c2933f);
  color: #2a1c08;
}

.mapPickSearch {
  display: flex;
  flex: 1;
  min-width: 160px;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  border: 1px solid rgba(150, 116, 60, 0.45);
  border-radius: 999px;
  background: rgba(20, 14, 8, 0.6);
  color: #bfa87c;
}

.mapPickSearch input {
  flex: 1;
  min-width: 0;
  border: none;
  background: none;
  color: #ffe9bd;
  font-size: 13px;
  outline: none;
}

.mapPickLayout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
  gap: 14px;
  min-height: 240px;
}

.mapPickList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 46vh;
  overflow-y: auto;
  padding-right: 4px;
}

.mapPickRow {
  display: grid;
  gap: 2px;
  padding: 9px 12px;
  border: 1px solid rgba(150, 116, 60, 0.4);
  border-radius: 10px;
  background: rgba(35, 26, 14, 0.55);
  color: #e7d3a8;
  text-align: left;
  cursor: pointer;
}

.mapPickRow:hover {
  border-color: rgba(214, 178, 94, 0.8);
}

.mapPickRow.highlighted {
  border-color: #ffd76a;
  background: rgba(82, 61, 29, 0.5);
}

.mapPickRow.applied {
  box-shadow: inset 0 0 0 1px rgba(126, 217, 87, 0.35);
}

.mapPickRowName {
  font-weight: 700;
  color: #ffe9bd;
}

.mapPickRowMeta {
  font-size: 11px;
  color: #bfa87c;
}

/* The detail column: the preview + info SCROLL inside .mapPickDetailScroll,
   while .mapPickApplyBar (the "Play this map" button) stays pinned below them,
   always visible — it must never have to be hunted for under a long
   description / conditions list. */
.mapPickDetail {
  display: flex;
  flex-direction: column;
  max-height: 46vh;
  overflow: hidden;
  padding: 0;
  border: 1px solid rgba(150, 116, 60, 0.35);
  border-radius: 12px;
  background: rgba(20, 14, 8, 0.55);
}

.mapPickDetail > .optionHint {
  padding: 12px;
}

.mapPickDetailScroll {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px;
}

.mapPickApplyBar {
  flex: none;
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-top: 1px solid rgba(170, 130, 70, 0.4);
  background: linear-gradient(
    180deg,
    rgba(48, 34, 15, 0.92),
    rgba(24, 16, 8, 0.97)
  );
  box-shadow: 0 -8px 18px rgba(0, 0, 0, 0.35);
}

/* Taller than the old outline-only sketch: the preview now draws the REAL printed
   tile graphics, so it needs room for the scans to be legible. */
.mapShapePreviewSvg {
  flex: none;
  width: 100%;
  height: 230px;
  border: 1px solid rgba(150, 116, 60, 0.3);
  border-radius: 10px;
  background: radial-gradient(
    circle at 50% 40%,
    rgba(60, 45, 22, 0.5),
    rgba(12, 9, 5, 0.7)
  );
}

.mapPickInfo {
  display: grid;
  gap: 6px;
  font-size: 12px;
  color: #cdb68a;
}

.mapPickInfo strong {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  color: #ffe9bd;
}

.mapPickCredit {
  font-size: 11px;
  opacity: 0.7;
}

.mapPickProblem {
  color: #ff9a8a;
}

/* What applying this map does to the SEATS (and the picks on them). */
.mapPickSeatChange {
  padding: 5px 8px;
  border: 1px solid rgba(214, 178, 94, 0.4);
  border-radius: 7px;
  background: rgba(60, 44, 20, 0.55);
  color: #ffd9a0;
  font-size: 10.5px;
  line-height: 1.4;
}

.mapPickUseButton {
  padding: 11px 14px;
  border: 1px solid #ffd76a;
  border-radius: 10px;
  background: linear-gradient(180deg, #efcf82, #c2933f);
  color: #2a1c08;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  box-shadow:
    inset 0 1px 0 rgba(255, 246, 214, 0.7),
    0 3px 10px rgba(0, 0, 0, 0.45);
  transition:
    filter 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.mapPickUseButton:not(:disabled):hover,
.mapPickUseButton:not(:disabled):focus-visible {
  filter: brightness(1.08);
  transform: translateY(-1px);
  box-shadow:
    inset 0 1px 0 rgba(255, 246, 214, 0.8),
    0 0 16px rgba(232, 183, 92, 0.5),
    0 5px 12px rgba(0, 0, 0, 0.5);
}

.mapPickUseButton:disabled {
  opacity: 0.55;
  cursor: default;
  filter: grayscale(0.4);
}

.mapPickDifficulty {
  display: grid;
  gap: 6px;
}

.mapPickDifficultyLabel {
  font-size: 11px;
  color: #bfa87c;
}

/* Whether the SELECTED map brings a difficulty of its own — so an unchanged bar
   reads as an answer, not a dead control. */
.mapPickDifficultyNote {
  font-size: 11px;
  line-height: 1.45;
  color: #9c8a66;
}

/* Difficulty as chess pieces: Pawn = Easy · Knight = Normal · Rook = Hard ·
   King = Impossible. */
.difficultyChessBar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.difficultyChessBtn {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 10px 6px 8px;
  border: 1px solid rgba(150, 116, 60, 0.45);
  border-radius: 12px;
  background: rgba(35, 26, 14, 0.55);
  color: #d8c39a;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  /* Only `transform` transitions. The picked-difficulty signal (border, fill,
     un-greyed piece) must land the INSTANT the value changes: a transitioned
     border-color / background / filter can be left frozen on the previously
     picked button — observed on the live app, where the class had correctly moved
     to Normal while the gold ring stayed on Impossible, so the bar read as
     "still Impossible". Untransitioned properties cannot get stuck. */
  transition: transform 0.15s ease;
}

.difficultyChessBtn img {
  width: 44px;
  height: 44px;
  filter: grayscale(0.55) brightness(0.8);
}

.difficultyChessBtn:hover {
  border-color: rgba(214, 178, 94, 0.8);
  transform: translateY(-1px);
}

.difficultyChessBtn:hover img,
.difficultyChessBtn.selected img {
  filter: none;
}

.difficultyChessBtn.selected {
  border-color: #ffd76a;
  background: rgba(82, 61, 29, 0.55);
  color: #ffe9bd;
  /* A solid ring on top of the inset glow: the one unmistakable "this is the
     picked difficulty" mark, and it is not a transitioned property either. */
  outline: 2px solid #ffd76a;
  outline-offset: 1px;
  box-shadow: inset 0 0 14px rgba(214, 164, 76, 0.25);
}

/* The SELECTED map's own authored difficulty, marked while you browse the list:
   clicking through maps visibly moves this mark even before "Play this map"
   commits it (which is when the gold `.selected` ring moves). */
.difficultyChessBtn.mapSet::after {
  content: "map";
  position: absolute;
  top: 2px;
  right: 4px;
  font-size: 9px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #8fd8ff;
}

.difficultyChessBtn.mapSet {
  position: relative;
  border-color: #8fd8ff;
  box-shadow: inset 0 0 12px rgba(143, 216, 255, 0.2);
}

/* Heroes tab: detail panel above the faction grid. */
.heroesTab {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.heroDetailPlaceholder {
  margin: 0;
  padding: 14px 16px;
  border: 1px dashed rgba(170, 130, 70, 0.4);
  border-radius: 12px;
  color: #b89f78;
  background: rgba(24, 18, 10, 0.55);
}

.heroDetail {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid rgba(220, 175, 95, 0.45);
  border-radius: 12px;
  background: rgba(33, 25, 15, 0.92);
  color: #ecd9b0;
  animation: heroDetailIn 0.18s ease;
}

@keyframes heroDetailIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.heroDetailHead {
  display: flex;
  align-items: center;
  gap: 12px;
}

.heroDetailTitle {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.heroDetailTitle strong {
  font-size: 17px;
}

.heroDetailTitle small {
  color: #b89f78;
}

.heroDetailStats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.heroStat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px 4px;
  border: 1px solid rgba(170, 130, 70, 0.35);
  border-radius: 9px;
  background: rgba(24, 18, 10, 0.7);
}

.heroStatIcon {
  display: inline-grid;
  place-items: center;
}

/* The printed statistic symbol (crossed swords / shield / spell book / tomes). */
.heroStatSymbol {
  width: 30px;
  height: 30px;
  object-fit: contain;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.6));
}

.heroStatValue {
  font-size: 18px;
  font-weight: 800;
  color: #ffe9bd;
  line-height: 1;
}

.heroStatLabel {
  font-size: 11px;
  color: #b89f78;
}

.heroDetailSection {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.heroDetailSection h4 {
  margin: 0;
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #ffd76a;
}

.heroDetailEntry {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: baseline;
  column-gap: 8px;
  row-gap: 2px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(24, 18, 10, 0.6);
  border: 1px solid rgba(170, 130, 70, 0.25);
}

.heroDetailEntry strong {
  color: #ffe9bd;
}

.heroDetailEntry > span:last-child {
  grid-column: 1 / -1;
  color: #cbb88f;
  font-size: 13px;
  line-height: 1.4;
}

/* An entry led by a real ability/specialty symbol chip: chip on the left, the
   name + rules text stacked to its right. */
.heroDetailEntrySymbol {
  display: flex;
  align-items: flex-start;
  column-gap: 10px;
}

.heroDetailEntryText {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.heroDetailEntryText strong {
  color: #ffe9bd;
}

.heroDetailEntryText > span {
  color: #cbb88f;
  font-size: 13px;
  line-height: 1.4;
}

/* Shared leather chip that holds an ability emblem or a specialty symbol, so
   the transparent skill emblems and the card-recovered symbols sit on one
   surface that matches the printed cards. */
.heroAbilitySymbol,
.heroSpecArt {
  flex: 0 0 auto;
  display: block;
  width: 48px;
  height: 48px;
  border-radius: 8px;
  border: 1px solid rgba(200, 156, 88, 0.7);
  box-shadow:
    inset 0 0 0 1px rgba(0, 0, 0, 0.7),
    0 1px 3px rgba(0, 0, 0, 0.5);
  background:
    radial-gradient(
      70% 70% at 50% 40%,
      rgba(255, 226, 168, 0.12),
      transparent 72%
    ),
    url("/assets/specialty-card/leather.webp") center / cover,
    #5c4026;
  overflow: hidden;
}

.heroAbilitySymbol img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.55));
}

/* The specialty chip crops the specialty card scan to its top-centre art — the
   same window the hero board uses (see .hbArt-specialty img). */
.heroSpecArt {
  position: relative;
}

.heroSpecArt img {
  position: absolute;
  left: 0;
  top: 0;
  display: block;
  max-width: none;
  width: 262%;
  transform: translate(-31%, -9.5%);
}

/* An art-less specialty (Bulwark/Conflux/spell specialist) shows its
   transparent symbol contained in the chip instead of a cropped scan. */
.heroSpecArt .heroSpecIcon {
  position: absolute;
  inset: 8%;
  width: 84%;
  height: 84%;
  object-fit: contain;
  transform: none;
}

.heroSpecArtWrap {
  position: relative;
  flex: 0 0 auto;
  display: block;
}

.heroSpecLevel {
  position: absolute;
  right: -5px;
  bottom: -5px;
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  padding: 1px 5px;
  border-radius: 6px;
  background: linear-gradient(180deg, #e8c576, #c2933f);
  border: 1px solid rgba(0, 0, 0, 0.55);
  color: #2a1c08;
  font-weight: 800;
  font-size: 11px;
  line-height: 1.4;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
}

.heroDetailEmpty {
  color: #b89f78;
}

/* Hero row: pick button + small info button. */
.lobbyHeroRow {
  display: flex;
  gap: 4px;
  align-items: stretch;
}

.lobbyHeroRow .lobbyHero {
  flex: 1;
  min-width: 0;
}

.lobbyHeroInfo {
  flex: 0 0 auto;
  width: 30px;
  display: inline-grid;
  place-items: center;
  border-radius: 8px;
  border: 1px solid rgba(170, 130, 70, 0.3);
  background: rgba(33, 25, 15, 0.7);
  color: #d8c39a;
  cursor: pointer;
}

.lobbyHeroInfo:hover {
  border-color: rgba(214, 178, 94, 0.8);
  color: #ffe9bd;
}

.lobbyHeroInfo.active {
  border-color: #ffd76a;
  color: #ffd76a;
  background: rgba(82, 61, 29, 0.6);
}

.lobbyHero.banned {
  opacity: 0.4;
}

.lobbyHero.banned span {
  text-decoration: line-through;
}

/* Heroes & draft tab: one continuous realistic parchment sheet with restrained
   edge blood, light burn aging, and faint surface scratches (all in the art).
   Texture on ::before (slightly translucent so the dragon peeks through). */
.draftPanel {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 18px 20px;
  border: 1px solid rgb(120 90 55 / 48%);
  border-radius: 8px;
  background: transparent;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow:
    inset 0 1px 0 rgb(255 246 230 / 22%),
    inset 0 0 0 1px rgb(80 55 30 / 14%),
    0 12px 28px rgb(0 0 0 / 38%);
  color: #2a1c08;
  text-shadow: none;
}

.draftPanel::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
  /* Full sheet of parchment — no extra CSS filters that fake “ancient”. */
  background-color: #d4bc8e;
  background-image: url("/assets/ui/ornate/draft-parchment-panel.webp");
  background-position: center;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  opacity: 0.9;
  /* Soft paper depth only — keep edge aging as painted in the texture. */
  box-shadow: inset 0 0 36px rgb(70 48 24 / 12%);
}

/* Keep controls above the parchment layer. */
.draftPanel > * {
  position: relative;
  z-index: 1;
}

/* Full-screen, brief phase card: rendered in a portal so it remains visible
   above the Setup Hub window and communicates the authoritative state change. */
.draftPhaseAnnouncement {
  position: fixed;
  inset: 0;
  z-index: 1400;
  display: grid;
  place-items: center;
  padding: 20px;
  pointer-events: none;
  background: radial-gradient(circle, rgba(28, 17, 7, 0.3), rgba(4, 3, 2, 0.72));
  animation: draftPhaseBackdropIn 180ms ease-out both;
}

.draftPhaseAnnouncementCard {
  width: min(460px, calc(100vw - 32px));
  padding: 30px 28px 24px;
  border: 2px solid #d7aa4d;
  border-radius: 10px;
  color: #fff4d0;
  text-align: center;
  pointer-events: auto;
  background: linear-gradient(155deg, #35220f 0%, #160d08 62%, #090604 100%);
  box-shadow: 0 24px 70px #000c, inset 0 0 30px #e3aa3024;
  animation: draftPhaseCardIn 420ms cubic-bezier(.2, .9, .25, 1.2) both;
}

.draftPhaseAnnouncementSeal {
  width: 70px;
  height: 70px;
  margin: -4px auto 14px;
  display: grid;
  place-items: center;
  border: 2px solid currentColor;
  border-radius: 50%;
  color: #efc76d;
  box-shadow: 0 0 0 5px #d6a64a24, 0 0 28px #e8b94b55;
  animation: draftPhaseSealPulse 850ms ease-out both;
}

.draftPhaseAnnouncement--ban .draftPhaseAnnouncementSeal { color: #ff665f; }
.draftPhaseAnnouncement--pick .draftPhaseAnnouncementSeal { color: #82d9ff; }
.draftPhaseAnnouncementCard small { display: block; color: #d8b56c; letter-spacing: .14em; text-transform: uppercase; }
.draftPhaseAnnouncementCard strong { display: block; margin-top: 7px; font: 800 clamp(1.55rem, 5vw, 2.35rem)/1.05 Georgia, serif; letter-spacing: .07em; }
.draftPhaseAnnouncementCard p { margin: 12px auto 18px; max-width: 38ch; color: #e7dcc4; line-height: 1.45; }
.draftPhaseAnnouncementCard button { min-width: 120px; padding: 8px 18px; border: 1px solid #d8ae59; border-radius: 5px; color: #fff2c8; background: #6d4319; cursor: pointer; }
.draftPhaseAnnouncementCard button:hover { background: #895724; }

@keyframes draftPhaseBackdropIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes draftPhaseCardIn { from { opacity: 0; transform: translateY(24px) scale(.88); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes draftPhaseSealPulse { 0% { transform: scale(.65); filter: brightness(2); } 55% { transform: scale(1.12); } 100% { transform: scale(1); filter: brightness(1); } }

@media (prefers-reduced-motion: reduce) {
  .draftPhaseAnnouncement,
  .draftPhaseAnnouncementCard,
  .draftPhaseAnnouncementSeal { animation: none; }
}

