}
.designerObjectButton.modOverride:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.designerModPinRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  padding: 4px 0;
  border-top: 1px solid rgba(180, 120, 255, 0.15);
