}
.designerModPinRow .popoverSelect {
  max-width: 9rem;
}
/* Glowing candidate cells while an object (or tile token) is armed / dragged. */
.designerObjectSlot {
  fill: rgba(255, 233, 168, 0.28);
  stroke: #ffe9a8;
  stroke-width: 1.5px;
  cursor: pointer;
}
.designerObjectSlot:hover {
  fill: rgba(255, 233, 168, 0.5);
}
.designerObjectSlot.standalone {
  fill: rgba(120, 200, 255, 0.24);
  stroke: #8fd0ff;
  stroke-dasharray: 3 2;
}
/* The candidate under the dragged token — a brighter drop target. */
.designerObjectSlot.hover {
  fill: rgba(255, 233, 168, 0.62);
  stroke-width: 2.4px;
  filter: drop-shadow(0 0 5px rgba(255, 235, 150, 0.85));
}
.designerObjectSlot.standalone.hover {
  fill: rgba(120, 200, 255, 0.56);
}
/* A face-down tile is ONE whole-footprint drop target for a token drag (the
   discoverer picks the exact field at reveal) — a distinct dashed violet glow so
   it reads as a whole-tile target, not a single printed slot. */
.designerObjectSlot.faceDownTile {
  fill: rgba(180, 150, 255, 0.22);
  stroke: #c3a7ff;
  stroke-dasharray: 4 3;
}
.designerObjectSlot.faceDownTile.hover {
  fill: rgba(180, 150, 255, 0.5);
  stroke-width: 2.4px;
  filter: drop-shadow(0 0 5px rgba(190, 160, 255, 0.85));
}
/* Exact release target: candidates answer "where can it go?"; this reticle
   answers "which one will this release take?" and stays visible under the
   dragged token art. */
.designerTokenDropReticle polygon {
  fill: rgba(255, 224, 112, 0.18);
  stroke: #fff0a8;
  stroke-width: 2.8px;
  stroke-dasharray: 7 2;
  filter: drop-shadow(0 0 7px rgba(255, 225, 112, 0.95));
}
.designerTokenDropReticle circle {
  fill: #fff4bd;
  stroke: #5b3309;
  stroke-width: 1.4px;
}
.designerTokenDropReticle text {
  fill: #fff0a8;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.8px;
  paint-order: stroke;
  stroke: rgba(21, 10, 2, 0.95);
  stroke-width: 2.4px;
}
.designerTokenDropReticle.standalone polygon {
  fill: rgba(120, 200, 255, 0.2);
  stroke: #a8dcff;
  filter: drop-shadow(0 0 7px rgba(120, 200, 255, 0.9));
}
.designerTokenDropReticle.standalone text {
  fill: #bfe6ff;
}
/* Placed object tokens are grabbable (drag to move, click for options). */
.designerObjectToken {
  cursor: grab;
}
.designerObjectToken:hover .designerObjectRing {
  filter: brightness(1.15) drop-shadow(0 0 4px rgba(255, 235, 150, 0.7));
}
.designerObjectToken.dragging {
  cursor: grabbing;
}
.designerObjectToken.dragging .designerObjectRing {
  filter: drop-shadow(0 0 7px rgba(255, 235, 150, 0.95));
}
.designerObjectRing {
  fill: rgba(12, 8, 4, 0.5);
  stroke-width: 3px;
}
.designerObjectToken.selected .designerObjectRing {
  stroke-width: 4px;
  filter: drop-shadow(0 0 4px currentColor);
}
/* Tile-carried Monolith/Whirlpool tokens: every one drags (grab) — face-up to a
   legal slot, face-down to another compatible tile — and a plain click opens
   options. They lift on hover so they read interactive. */
.designerMapToken {
  cursor: pointer;
}
.designerMapToken.draggable {
  cursor: grab;
}
.designerMapToken:hover {
  filter: brightness(1.12) drop-shadow(0 0 4px rgba(255, 235, 150, 0.7));
}
.designerMapToken.dragging {
  cursor: grabbing;
  filter: drop-shadow(0 0 7px rgba(255, 235, 150, 0.95));
}

/* A designer-pinned token on a still-hidden in-game tile. The thin hex ring
   makes the reserved physical field readable without exposing the tile art. */
.tileBackPendingTokenSlot {
  fill: rgba(255, 228, 140, 0.12);
  stroke: rgba(255, 236, 174, 0.95);
  stroke-width: 2px;
  stroke-dasharray: 5 2;
  filter: drop-shadow(0 0 5px rgba(255, 219, 110, 0.75));
}
