}

.designerTileLabel {
  fill: #f3e7c8;
  font-size: 9px;
  letter-spacing: 0.06em;
  paint-order: stroke;
  stroke: rgba(0, 0, 0, 0.75);
  stroke-width: 2.6px;
  pointer-events: none;
