/* --- Palette: drag a tile type onto the board --------------------------- */
.designerPalette {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
  width: 100%;
}

.designerPalette .palettePrompt {
  align-self: center;
  color: var(--muted);
  letter-spacing: 0.04em;
}

.paletteTile {
  display: grid;
  grid-template-rows: auto auto;
  justify-items: center;
  gap: 4px;
  width: 84px;
  padding: 6px 6px 7px;
  border: 1px solid rgba(214, 178, 94, 0.45);
  border-radius: 10px;
  background: linear-gradient(
    180deg,
    rgba(46, 38, 22, 0.95),
    rgba(22, 17, 10, 0.95)
  );
  color: #f0dcb8;
  cursor: grab;
  touch-action: none;
  user-select: none;
  transition:
    transform 0.08s ease,
    box-shadow 0.12s ease;
}

.paletteTile:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.paletteTile:active {
  cursor: grabbing;
}

.paletteThumb {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background-size: cover;
  background-position: center;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.4);
}

.paletteThumb.large {
  width: 56px;
  height: 56px;
}

.paletteLabel {
  font-size: 10px;
  color: var(--muted);
  text-align: center;
  line-height: 1.2;
}

/* Compact band-colour key: swatch + numeral for each tile group, so the
   creature-tier meaning of every outline colour is always on screen. */
.designerBandLegend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  width: 100%;
  padding: 5px 8px;
  border: 1px solid rgba(214, 178, 94, 0.28);
  border-radius: 8px;
  background: rgba(20, 16, 10, 0.55);
}

.designerBandLegendTitle {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted);
}

.designerBandLegendItem {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #f0dcb8;
}

.designerBandLegendSwatch {
  width: 13px;
  height: 13px;
