  align-items: center;
  gap: 6px;
  padding: 5px 9px 5px 5px;
  border-radius: 9px;
  border: 1px solid var(--gold);
  background: rgba(22, 17, 10, 0.95);
  color: #f0dcb8;
  font-size: 11px;
  font-weight: 700;
  transform: translate(-50%, -50%);
  pointer-events: none;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.55);
}

.designerDragGhost .paletteThumb {
  width: 30px;
  height: 30px;
