/* ---------------------------------------------------------------------------
   WOG Commander — level-up notice: the dock tile and the card's grade-up box
   pulse gold while a grade-up pick is owed, so a commander level-up is
   impossible to miss. The dock tile additionally BLINKS hard for a few
   seconds right after the pick arrives (screen.tsx toggles the class).
   -------------------------------------------------------------------------- */
@keyframes commanderPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(244, 215, 116, 0);
    border-color: rgba(244, 215, 116, 0.55);
  }
  50% {
    box-shadow: 0 0 14px 3px rgba(244, 215, 116, 0.55);
    border-color: var(--gold, #f0c46a);
  }
}

@keyframes commanderBlink {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.7);
    box-shadow: 0 0 22px 6px rgba(244, 215, 116, 0.85);
  }
}

.commanderGradeUpPulse {
  animation: commanderPulse 1.6s ease-in-out infinite;
}

.dockTile.commanderTilePulse {
  animation: commanderPulse 1.6s ease-in-out infinite;
}

.dockTile.commanderTileBlink {
  animation: commanderBlink 0.55s ease-in-out 8;
}

/* ---------------------------------------------------------------------------
   WOG Commander — rainbow frame spark: a rotating rainbow ring, with a bright
   white "spark" that travels around the card border (the white stop in the
   conic gradient rotates with --cmdrRainbowAngle). Drawn as a gradient BORDER
   (conic fill masked to the padding ring) sitting over the frame art. Purely
   decorative; sits inside the container-query box so cqw units track the card.
   -------------------------------------------------------------------------- */
@property --cmdrRainbowAngle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes commanderRainbowSpin {
  to {
    --cmdrRainbowAngle: 360deg;
  }
}

@keyframes commanderRainbowGlow {
  0%,
  100% {
    opacity: 0.72;
    filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.35)) saturate(1.25);
  }
  50% {
    opacity: 1;
    filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.6)) saturate(1.5);
  }
}

.commanderRainbowFrame {
  position: absolute;
  inset: 0;
  border-radius: 2.5cqw;
  padding: 1.5cqw; /* ring thickness */
  pointer-events: none;
  z-index: 2;
  background: conic-gradient(
    from var(--cmdrRainbowAngle),
    #ff004c,
    #ff8a00,
    #ffe600,
    #ffffff,
    /* the travelling spark */ #33ff5a,
    #00e5ff,
    #4d6bff,
    #d400ff,
    #ff004c
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation:
    commanderRainbowSpin 4.5s linear infinite,
    commanderRainbowGlow 2.4s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .commanderRainbowFrame {
    animation: none;
  }
}

/* ---------------------------------------------------------------------------
   WOG Commander — level-up stat picker: one clearly-separated, individually
   highlighted option per stat, each with its own accent colour, a hover lift
   and a full "current → next" readout. Used in the dock card AND the level-up
   popup below.
   -------------------------------------------------------------------------- */
.commanderLevelUpPicker {
  padding: 10px;
  border: 1px dashed #b9985a;
  border-radius: 8px;
  background: #241b10;
}

.commanderLevelUpTitle {
  color: #f4d774;
  font-weight: 800;
  letter-spacing: 0.3px;
  margin-bottom: 2px;
}

.commanderLevelUpHint {
  color: #b9a988;
  font-size: 11.5px;
  margin-bottom: 8px;
}

.commanderLevelUpGrid {
  display: grid;
  gap: 8px;
}

.commanderPickStat {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  padding: 8px 10px 8px 14px;
  border-radius: 9px;
  border: 1px solid #6f5533;
  background: linear-gradient(180deg, #322614, #241b10);
  color: #fff4c8;
  cursor: pointer;
  font-weight: 600;
  transition:
    transform 0.12s ease,
    box-shadow 0.12s ease,
    border-color 0.12s ease,
    background 0.12s ease;
}

.commanderPickStat:hover:not([data-capped="true"]),
.commanderPickStat:focus-visible:not([data-capped="true"]) {
  transform: translateY(-1px);
  border-color: var(--pick-accent, #f4d774);
  box-shadow:
    0 0 0 1px var(--pick-accent, #f4d774),
    0 4px 14px rgba(0, 0, 0, 0.45);
  background: linear-gradient(180deg, #3c2d18, #281e11);
  outline: none;
}

.commanderPickStat[data-capped="true"] {
  border-color: #3f3320;
  background: #1c1710;
  color: #6d6252;
  cursor: default;
}

/* Per-stat accent bar down the left edge — each option is visually distinct. */
.commanderPickAccent {
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 4px;
  border-radius: 4px;
  background: var(--pick-accent, #f4d774);
  opacity: 0.9;
}

.commanderPickStat[data-capped="true"] .commanderPickAccent {
  opacity: 0.25;
}

.commanderPickStat[data-stat="attack"] {
  --pick-accent: #ff6b4a;
}
.commanderPickStat[data-stat="defense"] {
  --pick-accent: #6ba7ff;
}
.commanderPickStat[data-stat="health"] {
  --pick-accent: #6ee06e;
}
.commanderPickStat[data-stat="damage"] {
  --pick-accent: #ff5d7d;
}
.commanderPickStat[data-stat="magic"] {
  --pick-accent: #c48cff;
}
.commanderPickStat[data-stat="speed"] {
  --pick-accent: #5fe0d6;
}

.commanderPickBody {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.commanderPickHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.commanderPickName {
  font-weight: 800;
  color: #e6c56a;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  font-size: 12.5px;
}

.commanderPickStat[data-capped="true"] .commanderPickName {
  color: #6d6252;
}

.commanderPickGrades {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.commanderPickArrow {
  font-weight: 800;
  color: #f4d774;
  font-size: 11px;
}

.commanderPickBenefit {
  font-size: 11.5px;
  line-height: 1.25;
  color: #d8cba9;
}

.commanderPickBenefit b {
  color: #f4d774;
}

.commanderPickCapped {
  font-size: 11.5px;
  opacity: 0.75;
}

/* ---------------------------------------------------------------------------
   WOG Commander — level-up POPUP: a slam-in celebratory modal shown the moment
   a level-up awards commander stat points (mirrors the morale-card overlay).
   -------------------------------------------------------------------------- */
@keyframes commanderLevelUpSlamIn {
  0% {
    transform: scale(0.7) translateY(14px);
    opacity: 0;
  }
  60% {
    transform: scale(1.03);
    opacity: 1;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

.commanderLevelUpBackdrop {
  position: fixed;
  inset: 0;
  /* The overlay PORTALS to <body> (commander-card.tsx) because it is rendered
     from the left rail's `.leftRailDock`, a z-index: 20 stacking context that
     trapped it under the fixed hand tray. Portaled, it needs its own slot in
     the documented band: above the chat dock (200), setup-hub backdrop (210),
     hero info (220) and mod windows (230), below the commander equipment
     window (240/245), which opens on top of this one. */
  z-index: 236;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(6, 4, 2, 0.62);
  backdrop-filter: blur(2px);
  animation: moraleCueBackdropIn 0.2s ease-out;
}

.commanderLevelUpModal {
  width: min(440px, 96vw);
  /* Three pinned-scroller-pinned rows: banner · scrolling body · the
     Done/"Spend later" escape. The middle `minmax(0, 1fr)` is what lets the
     body shrink below its content so `.commanderLevelUpScroll` scrolls instead
     of the modal growing past the viewport — the six stat options plus the
     commander face easily exceed a short window, and the last option (Speed)
     was unreachable. `dvh` (with the vh fallback declared first, like
     `.searchModal` / `.phoneMode .townWindow`) because a phone's 100vh is the
     URL-bar-hidden LARGE viewport: a 92vh box centered in a shorter VISUAL
     viewport hangs off both edges with nothing to scroll. */
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  max-height: 92vh;
  max-height: 92dvh;
  overflow-y: auto;
  gap: 10px;
  padding: 14px;
  border-radius: 14px;
  border: 2px solid #d9b25a;
  background: linear-gradient(180deg, #241a10, #17110a);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.5),
    0 18px 60px rgba(0, 0, 0, 0.7),
    0 0 30px rgba(244, 215, 116, 0.35);
  animation: commanderLevelUpSlamIn 0.42s cubic-bezier(0.18, 0.9, 0.28, 1.2);
}

.commanderLevelUpBanner {
  text-align: center;
  font-weight: 900;
  letter-spacing: 0.6px;
  color: #ffe9a3;
  font-size: 16px;
  text-shadow: 0 0 10px rgba(244, 215, 116, 0.7);
}

.commanderLevelUpModalBody {
  display: grid;
  gap: 12px;
  align-content: start;
}

/* THE scroll region of the level-up popup (see .commanderLevelUpModal above).
   `min-height: 0` is the load-bearing half — without it this grid row is sized
   by its content and the box never scrolls. Keep both, and keep this class on
   the element that holds the face + the six stat options. */
.commanderLevelUpScroll {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding-right: 4px;
}

.commanderLevelUpFace {
  width: min(230px, 62%);
  margin: 0 auto;
}

/* On a short window the card face would eat the whole scroller and push all six
   options below the fold; shrink it so at least the first options are visible
   before any scrolling. */
@media (max-height: 780px) {
  .commanderLevelUpFace {
    width: min(150px, 42%);
  }
}

.commanderLevelUpDone {
  justify-self: center;
  padding: 7px 18px;
  border-radius: 8px;
  border: 1px solid #b9985a;
  background: #3a2c18;
  color: #fff4c8;
  font-weight: 700;
  cursor: pointer;
}

.commanderLevelUpDone:hover {
  background: #4a3820;
}

@media (prefers-reduced-motion: reduce) {
  .commanderLevelUpModal {
    animation: none;
  }
}

/* ==================================================================== */
/* COMPENDIUM THEME (Homm3BG layout kit)                                 */
/*                                                                       */
/* A cohesive "premium board-game" skin drawn from the Homm3BG           */
/* /assets/layout art: gold filigree frames, royal-blue leather bands,   */
/* black-marble panel interiors, a brown-leather table and the official  */
/* gold wordmark. Everything below is a VISUAL reskin only — it overrides */
/* background / border / box-shadow / colour / filter on existing        */
/* classes and never changes layout, positioning or hit-areas, so no     */
/* button, cell or drag target moves. Every decorative pseudo-element is  */
/* pointer-events:none, so gameplay clicks are completely untouched.      */
/* This block sits last so its skin wins over the base rules above.      */
/* ==================================================================== */
:root {
  /* Filigree gold (three stops for bevelled gilding). */
  --cmp-gold: #d9b25a;
  --cmp-gold-bright: #f6e2a8;
  --cmp-gold-deep: #6e4e1f;
  /* Royal-blue leather band. */
  --cmp-blue: #3f6bb5;
  --cmp-blue-deep: #21406f;
  /* Black-marble panel interior. */
  --cmp-marble-1: #262a34;
  --cmp-marble-2: #14161d;
  --cmp-marble-3: #0d0f14;
  /* Bronze rule + leather table. */
  --cmp-bronze: #b08d5a;
  --cmp-leather: url("/assets/ui/layout/leather.jpg");
  --cmp-separator: url("/assets/ui/layout/separator.png");
  --cmp-frame-banner: url("/assets/ui/layout/frame-banner.png");
  /* The gilded concentric frame: gold → blue → deep-gold banding read from
     the edge inward, an inner shadow for depth, and a soft outer rim + drop.
     Applied via box-shadow so it honours border-radius (border-image does
     not) and adds zero layout. */
  --cmp-frame:
    inset 0 0 0 2px var(--cmp-gold), inset 0 0 0 4px var(--cmp-blue-deep),
    inset 0 0 0 6px var(--cmp-gold-deep), inset 0 3px 26px rgb(0 0 0 / 55%),
    0 0 0 2px var(--cmp-gold-deep), 0 24px 56px rgb(0 0 0 / 62%);
  /* Marble fill for panel interiors. */
  --cmp-marble-fill:
    radial-gradient(
      130% 90% at 50% -6%,
      rgb(63 107 181 / 12%),
      transparent 62%
    ),
    linear-gradient(
      158deg,
      var(--cmp-marble-1) 0%,
      var(--cmp-marble-2) 56%,
      var(--cmp-marble-3) 100%
    );
}

/* ---- Reusable utilities (also used by the design preview) ----------- */

/* A gilded, marble-filled ornate frame — the workhorse panel skin. */
.ornateFrame {
  position: relative;
  border: none;
  border-radius: 12px;
  background: var(--cmp-marble-fill);
  box-shadow: var(--cmp-frame);
}

/* An engraved gold section title over a bronze rule. */
.compendiumHeading {
  margin: 0;
  text-align: center;
  font-family: var(--font-heroic);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--cmp-gold-bright);
  background: linear-gradient(
    180deg,
    #fbeec0 0%,
    var(--cmp-gold) 54%,
    #a67c33 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 2px 3px rgb(0 0 0 / 65%));
}

/* The bronze subsection separator from the layout kit. */
.compendiumRule {
  width: min(320px, 80%);
  height: 10px;
  margin: 2px auto 0;
  border: 0;
  background: var(--cmp-separator) center / 100% 100% no-repeat;
  opacity: 0.85;
  pointer-events: none;
}

/* An authentic ornate banner (gold/blue/marble) for short wide titles. */
.compendiumBanner {
  display: grid;
  place-items: center;
  padding: 22px 60px;
  border-image: var(--cmp-frame-banner) 70 110 fill / 40px 90px stretch;
  color: var(--cmp-gold-bright);
  font-family: var(--font-heroic);
}

/* ---- Pre-game chrome ------------------------------------------------ */

/* Cinematic full-bleed backdrop with a slow ken-burns drift. */
.menuShellBackdrop {
  filter: saturate(1.04) contrast(1.05) brightness(0.6);
  transform-origin: 55% 42%;
  animation: cmpKenBurns 46s ease-in-out infinite alternate;
  will-change: transform;
}

/* Deeper, warmer vignette so overlaid gold reads and the edges fall to ink. */
.menuShellVignette {
  background:
    radial-gradient(ellipse at 50% 40%, transparent 26%, rgb(6 5 3 / 72%) 100%),
    linear-gradient(
      180deg,
      rgb(6 5 3 / 62%) 0%,
      transparent 22%,
      transparent 74%,
      rgb(6 5 3 / 82%) 100%
    );
}

/* The official gold wordmark, floated above the panel. */
.menuGameLogo {
  width: min(560px, 82vw);
  height: auto;
  margin: 0 auto -2px;
  filter: drop-shadow(0 6px 16px rgb(0 0 0 / 70%))
    drop-shadow(0 0 26px rgb(217 178 90 / 22%));
  pointer-events: none;
  user-select: none;
  animation: cmpLogoIn 900ms cubic-bezier(0.2, 0.85, 0.25, 1) both;
}

/* FRAMELESS main menu — the panel box (background, gold frame, blur) is fully
   removed so the options float as ONLY their emblem + engraved words directly
   over the dragon. Opt-in via `frameless`; the lobby / hall / loading panels
   keep their framed compendium page below. */
.menuShellPanel.bare {
  background: none;
  box-shadow: none;
  border: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  padding: 0;
  gap: 4px;
  width: min(560px, 100%);
}

/* Menu options: NO BOX at all — the plaque (background/border/shadow) AND the
   dark scrim are removed. The emblem stays LARGE behind the engraved title so
   the words still cross the icon. The skill emblems are genuine transparent
   PNGs (soft glow fading to alpha 0 — github.com/Heegu-sama/Homm3BG), so they
   already blend into the dragon with NO rectangle: the old radial mask + the
   button's overflow-clip were what softened ("blurred") and cropped the
   emblem, and both are removed here so the icon shows crisp and whole. */
.menuNavButton,
.menuNavButton:hover:not(:disabled),
.menuNavButton:disabled {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  /* Let the emblem breathe past the button box instead of being hard-cropped. */
  overflow: visible;
}

.menuNavButton::after {
  content: none; /* remove the scrim — that was the last visible "box" */
}

/* The emblem is shown WHOLE and natural — no mask, no circle, no crop, no
   blur, no shadow. These are transparent PNGs, so at full opacity they read as
   the emblem itself (sword, banner, map, book…) over the dragon, with the
   engraved title laid across the middle. The only "box" ever removed is the
   button plaque + scrim above; the icon art is never reshaped. */
.menuNavIcon {
  height: 116%;
  opacity: 1;
  -webkit-mask-image: none;
  mask-image: none;
}

/* Per-emblem size tweaks so every option reads at a comparable visual weight:
   the Map-Designer parchment fills its frame, so trim it a touch; the Hall of
   Fame clover/dice sit small in theirs, so enlarge them a touch. */
.menuNavIcon[src*="pathfinding"] {
  height: 106%;
}

.menuNavIcon[src*="luck"] {
  height: 128%;
}

/* Bigger option rows on the boxless menu: taller buttons with more breathing
   room so the enlarged emblems have space, and a larger engraved title. */
.menuNav {
  gap: 24px;
}

.menuNavButton {
  min-height: 150px;
}

/* Large, hard-carved words that read clearly over the emblem + dragon with no
   box behind them — legibility comes from the carved text-shadows below, never
   a panel or halo. */
.menuNavLabel {
  font-size: 32px;
  filter: drop-shadow(0 1px 1px #000) drop-shadow(0 2px 7px #000)
    drop-shadow(0 0 4px #000);
}

/* On the boxless main menu, hide the white subtitle line — only the gold
   engraved label shows over the emblem. Scoped to `.menuNavText` (used ONLY by
   the main menu) so plain menuNavButtons on other screens are untouched. Kept
   in the DOM for screen readers; just not painted. */
.menuNavText small {
  display: none;
}

/* The menu / lobby panel becomes a gilded compendium page — kept MUCH more
   translucent so the dragon cover reads clearly through it. It is frosted
   glass, not a solid card: a heavy backdrop-blur keeps the gold title and
   list text legible over the busy art while the gold frame still reads. */
.menuShellPanel {
  border: none;
  border-radius: 14px;
  background:
    radial-gradient(
      130% 90% at 50% -6%,
      rgb(63 107 181 / 14%),
      transparent 60%
    ),
    linear-gradient(158deg, rgb(20 22 30 / 38%) 0%, rgb(11 13 18 / 48%) 100%);
  box-shadow: var(--cmp-frame);
  -webkit-backdrop-filter: blur(7px) saturate(1.06);
  backdrop-filter: blur(7px) saturate(1.06);
}

/* Engraved gold title with a bronze rule beneath it. */
.menuShellTitle,
.loadingTitle {
  color: var(--cmp-gold-bright);
  background: linear-gradient(
    180deg,
    #fbeec0 0%,
    var(--cmp-gold) 55%,
    #a67c33 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 2px 4px rgb(0 0 0 / 70%));
  font-family: var(--font-heroic);
}

.menuShellTitle::after,
.loadingTitle::after {
  content: "";
  display: block;
  width: min(280px, 72%);
  height: 10px;
  margin: 8px auto 0;
  background: var(--cmp-separator) center / 100% 100% no-repeat;
  opacity: 0.8;
  pointer-events: none;
}

/* Themed loading bar: gold fill running through a marble channel, with a
   travelling sheen so a long download still feels alive. */
.loadingBar {
  border: 1px solid var(--cmp-gold-deep);
  background: linear-gradient(180deg, #0c0e13, #191c24);
  box-shadow:
    inset 0 2px 5px rgb(0 0 0 / 60%),
    inset 0 0 0 1px rgb(217 178 90 / 22%);
}

.loadingBarFill {
  position: relative;
  overflow: hidden;
  background: linear-gradient(
    180deg,
    var(--cmp-gold-bright) 0%,
    var(--cmp-gold) 50%,
    #a67c33 100%
  );
  box-shadow: 0 0 12px rgb(217 178 90 / 55%);
}

.loadingBarFill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 30%,
    rgb(255 250 230 / 70%) 50%,
    transparent 70%
  );
  transform: translateX(-120%);
  animation: cmpSheen 1.9s ease-in-out infinite;
  pointer-events: none;
}

/* ---- In-game HUD & board (click-safe visual overrides) -------------- */

/* Brown-leather table grain beneath the existing atmosphere glows. */
body {
  background:
    radial-gradient(circle at 18% 8%, rgb(93 135 100 / 12%), transparent 26rem),
    radial-gradient(
      circle at 84% 14%,
      rgb(120 111 166 / 10%),
      transparent 24rem
    ),
    linear-gradient(
      160deg,
      rgb(23 19 16 / 90%) 0%,
      rgb(28 22 16 / 90%) 46%,
      rgb(18 20 23 / 92%) 100%
    ),
    var(--cmp-leather) center top / 480px repeat;
}

/* The player's card tray → the brown-leather table surface (the Homm3BG
   table-background), a translucent dark wash over the grain so the cards and
   text on it stay readable, finished with a gold-hairline frame.
   `isolation` gives it its own stacking context so the guardian watermark
   below can sit BEHIND the cards. */
.playerCardBar {
  position: relative;
  isolation: isolate;
  overflow: visible;
  background:
    linear-gradient(180deg, rgb(30 21 11 / 72%), rgb(20 14 8 / 78%)),
    var(--cmp-leather) center / 340px repeat;
  border: 1px solid var(--cmp-gold-deep);
  box-shadow:
    inset 0 0 0 1px rgb(217 178 90 / 30%),
    inset 0 1px 0 rgb(255 235 190 / 8%),
    0 8px 22px rgb(0 0 0 / 45%);
}

/* Faint griffin on the tray — scales with the bar. Fills the full height of
   .playerCardBar and grows/shrinks as the hand/permanent/deck boxes change
   the tray size; stays behind content (z-index:-1) and pointer-events:none. */
.playerCardBar::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  /* Full box footprint so height tracks the tray; art sized to the box. */
  width: 100%;
  height: 100%;
  background: url("/assets/ui/layout/guardian-griffin.png") right center / auto
    100% no-repeat;
  opacity: 0.14;
  filter: grayscale(1) brightness(1.3);
  pointer-events: none;
}

/* The top status ribbon → a gilded marble bar. */
.advHud {
  background: linear-gradient(180deg, rgb(32 35 44 / 95%), rgb(14 16 22 / 97%));
  border: 1px solid var(--cmp-gold-deep);
  box-shadow:
    inset 0 0 0 1px rgb(217 178 90 / 45%),
    inset 0 1px 0 rgb(246 226 168 / 22%),
    0 8px 22px rgb(0 0 0 / 45%);
}

.advHudCell {
  border-right: 1px solid rgb(217 178 90 / 26%);
}

/* Command rail dock → marble panel with a gold hairline. `isolation` lets the
   guardian watermark sit behind the buttons. */
.commandDock {
  position: relative;
  isolation: isolate;
  border: 1px solid var(--cmp-gold-deep);
  background: linear-gradient(180deg, rgb(28 31 40 / 96%), rgb(13 15 20 / 97%));
  box-shadow:
    inset 0 0 0 1px rgb(217 178 90 / 34%),
    0 6px 18px rgb(0 0 0 / 42%);
}

/* A faint pegasus perched at the FOOT of the command rail — hugs the bar,
   behind the buttons (z-index:-1), only reads through the empty marble below
   the last command. Decorative: pointer-events:none, contained. */
.commandDock::before {
  content: "";
  position: absolute;
  z-index: -1;
  right: 4px;
  bottom: 4px;
  width: 128px;
  height: 150px;
  background: url("/assets/ui/layout/guardian-pegasus.png") right bottom /
    contain no-repeat;
  opacity: 0.16;
  filter: grayscale(1) brightness(1.4);
  pointer-events: none;
}

/* Primary gilded action buttons get a bevelled gold face + hover lift.
   Scoped away from the .ghost / heal variants so their own colours stand. */
.commandButton:not(.ghost):not(.healCommandButton) {
  border: 1px solid var(--cmp-gold-deep);
  color: #2c1d08;
  background: linear-gradient(
    180deg,
    #f4d78c 0%,
    var(--cmp-gold) 48%,
    #b98f3f 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 247 218 / 78%),
    inset 0 -2px 4px rgb(110 78 31 / 45%),
    0 2px 5px rgb(0 0 0 / 40%);
  transition:
    filter 120ms ease,
    transform 120ms ease,
    box-shadow 120ms ease;
}

.commandButton:not(.ghost):not(.healCommandButton):hover {
  filter: brightness(1.07);
  transform: translateY(-1px);
  box-shadow:
    inset 0 1px 0 rgb(255 250 232 / 85%),
    inset 0 -2px 4px rgb(110 78 31 / 45%),
    0 5px 12px rgb(0 0 0 / 48%);
}

.commandButton:not(.ghost):not(.healCommandButton):active {
  transform: translateY(0);
  filter: brightness(0.98);
}

/* The .ghost secondary gets a quiet marble face (no gold bevel bleed-through). */
.commandButton.ghost {
  background: linear-gradient(180deg, rgb(38 41 50 / 96%), rgb(22 24 30 / 96%));
  border: 1px solid rgb(217 178 90 / 34%);
  box-shadow: inset 0 1px 0 rgb(246 226 168 / 12%);
}

/* Floating prompt tray → ornate gilded frame. */
.promptTray {
  border: none;
  background: var(--cmp-marble-fill);
  box-shadow: var(--cmp-frame);
}

/* Map action cards → gilded marble chips. */
.mapFloatCard {
  background: linear-gradient(180deg, rgb(30 33 42 / 97%), rgb(15 17 23 / 98%));
  border: 1px solid var(--cmp-gold);
  box-shadow:
    inset 0 0 0 1px rgb(33 64 111 / 55%),
    inset 0 1px 0 rgb(246 226 168 / 20%),
    0 6px 18px rgb(0 0 0 / 52%);
}

/* Dock tiles (hand / deck / hero) → marble with a gold hairline. */
.dockTile {
  border: 1px solid var(--cmp-gold-deep);
  box-shadow:
    inset 0 0 0 1px rgb(217 178 90 / 30%),
    0 4px 12px rgb(0 0 0 / 40%);
}

/* The battlefield gets a real gilded frame — gold, royal-blue and deep-gold
   banding around the board, the signature look of the section-heading art. */
.battlefieldFrame {
  border: 2px solid var(--cmp-gold-deep);
  box-shadow:
    inset 0 0 0 2px rgb(217 178 90 / 82%),
    inset 0 0 0 4px rgb(33 64 111 / 62%),
    inset 0 0 0 6px rgb(110 78 31 / 72%),
    inset 0 0 42px rgb(0 0 0 / 42%),
    0 24px 30px rgb(0 0 0 / 42%);
}

@keyframes cmpKenBurns {
  from {
    transform: scale(1) translate(0, 0);
  }
  to {
    transform: scale(1.07) translate(-1.4%, -1%);
  }
}

@keyframes cmpLogoIn {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes cmpSheen {
  0% {
    transform: translateX(-120%);
  }
  60%,
  100% {
    transform: translateX(240%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .menuShellBackdrop,
  .menuDragonBreath {
    animation: none;
  }
  .menuGameLogo {
    animation: none;
  }
  .loadingBarFill::after {
    animation: none;
  }
  .menuDragonBreathPlume,
  .menuDragonBreathRage,
  .menuDragonBreathShimmer,
  .menuDragonBreathImpact,
  .menuDragonBreathEmbers,
  .menuDragonGroundBurn,
  .menuDragonSpark,
  .menuDragonGroundEmber {
    animation: none !important;
    transform: none;
    filter: none;
  }
  .menuDragonBreathPlume {
    opacity: 0.6;
  }
  .menuDragonBreathRage,
  .menuDragonBreathShimmer {
    opacity: 0;
  }
  .menuDragonBreathImpact {
    opacity: 0.45;
  }
  .menuDragonGroundBurn {
    opacity: 0.5;
  }
  .menuDragonBreathEmbers {
    opacity: 0.3;
  }
  .menuDragonSpark,
  .menuDragonGroundEmber {
    opacity: 0;
  }
}

/* ==================================================================== */
/* ORNATE ART SKIN (AI-generated chrome, /assets/ui/ornate)              */
/*                                                                       */
/* Painted game chrome generated with gpt-image (Codex image_gen) and    */
/* chroma-key-cut locally: a dragon-flanked title banner, ruby corner    */
/* flourishes, a riveted dark-iron button plate, a real open grimoire    */
/* for the Spell Book, a dragon-seal medallion, and leather/parchment    */
/* material textures. Like the compendium block above, this is a VISUAL  */
/* reskin only: it overrides background / border / box-shadow / colour   */
/* on existing classes, decorative pseudo-elements are pointer-events:   */
/* none, and no layout hit-area moves. It sits LAST so it wins.          */
/* ==================================================================== */
:root {
  --orn-banner: url("/assets/ui/ornate/dragon-banner.webp");
  --orn-button: url("/assets/ui/ornate/button-plate.webp");
