  --orn-seal: url("/assets/ui/ornate/seal-emblem.webp");
  --orn-parchment: url("/assets/ui/ornate/parchment.webp");
  --orn-leather: url("/assets/ui/ornate/leather-panel.webp");
  --orn-corner-tl: url("/assets/ui/ornate/corner-tl.webp");
  --orn-corner-tr: url("/assets/ui/ornate/corner-tr.webp");
  --orn-corner-bl: url("/assets/ui/ornate/corner-bl.webp");
  --orn-corner-br: url("/assets/ui/ornate/corner-br.webp");
}

/* ---- App chrome: leather top bar & footer ---------------------------- */

.topBar {
  border-bottom: 1px solid rgb(213 168 79 / 46%);
  background:
    linear-gradient(180deg, rgb(12 9 6 / 42%) 0%, rgb(8 6 4 / 62%) 100%),
    var(--orn-leather) center / cover;
  box-shadow: 0 2px 10px rgb(0 0 0 / 55%);
}

.brand {
  font-family: var(--font-heroic);
  font-size: 17px;
  letter-spacing: 0.05em;
  background: linear-gradient(
    180deg,
    #fbeec0 0%,
    var(--cmp-gold) 55%,
    #a67c33 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 1px 2px rgb(0 0 0 / 85%));
}

.footerNotice {
  border-top: 1px solid rgb(213 168 79 / 34%);
  background:
    linear-gradient(180deg, rgb(8 6 4 / 66%) 0%, rgb(12 9 6 / 50%) 100%),
    var(--orn-leather) center / cover;
}

/* ---- Ornate panels: leather fill + ruby corner flourishes ------------ */

.menuShellPanel:not(.bare),
.lobbyCard,
.serverBadge {
  position: relative;
  border: none;
  background:
    radial-gradient(
      120% 80% at 50% -10%,
      rgb(213 168 79 / 10%),
      transparent 60%
    ),
    linear-gradient(180deg, rgb(14 10 7 / 58%) 0%, rgb(9 7 5 / 72%) 100%),
    var(--orn-leather) center / cover;
  box-shadow: var(--cmp-frame);
}

/* The four generated ruby-and-gold flourishes, hung just outside the
   panel's gold banding. One overlay pseudo-element carries all four as
   separately-positioned backgrounds; it never intercepts clicks. */
.menuShellPanel:not(.bare)::after,
.lobbyCard::after {
  content: "";
  position: absolute;
  inset: -13px;
  background:
    var(--orn-corner-tl) left 0 top 0 / 76px 76px no-repeat,
    var(--orn-corner-tr) right 0 top 0 / 76px 76px no-repeat,
    var(--orn-corner-bl) left 0 bottom 0 / 76px 76px no-repeat,
    var(--orn-corner-br) right 0 bottom 0 / 76px 76px no-repeat;
  filter: drop-shadow(0 3px 5px rgb(0 0 0 / 60%));
  pointer-events: none;
  z-index: 2;
}

/* ---- The dragon-flanked title banner --------------------------------- */

/* Login / Hall of Fame / loading titles: the engraved words sit inside the
   banner's dark central plaque, hugged by the two gold dragons. */
.menuShellTitle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: min(470px, 100%);
  aspect-ratio: 3.148;
  margin: -6px auto 0;
  padding: 10.5% 21% 8%;
  background: var(--orn-banner) center / contain no-repeat;
  filter: drop-shadow(0 10px 22px rgb(0 0 0 / 62%));
  font-size: clamp(15px, 2.6vw, 20px);
  line-height: 1.15;
  /* the compendium block paints this title as a transparent-fill gradient
     clipped to the glyphs; over the painted banner the glyphs must be solid
     gold again or they vanish */
  color: var(--cmp-gold-bright);
  -webkit-text-fill-color: var(--cmp-gold-bright);
  text-shadow: 0 2px 4px rgb(0 0 0 / 85%);
}

.menuShellTitle::after {
  content: none; /* the banner replaces the bronze rule */
}

/* Lobby heading: same banner, with the refresh control floated clear. */
.lobbyHeader {
  position: relative;
  justify-content: center;
  min-height: 0;
}

.lobbyHeader h1 {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: min(440px, 86%);
  aspect-ratio: 3.148;
  padding: 10.5% 20% 8%;
  background: var(--orn-banner) center / contain no-repeat;
  filter: drop-shadow(0 10px 22px rgb(0 0 0 / 62%));
  font-family: var(--font-heroic);
  font-size: clamp(14px, 2.2vw, 17px);
  white-space: nowrap;
  letter-spacing: 0.04em;
  line-height: 1.1;
  text-align: center;
  color: var(--cmp-gold-bright);
  background-clip: border-box;
  text-shadow: 0 2px 4px rgb(0 0 0 / 85%);
}

.lobbyHeader > .commandButton {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
}

/* ---- Riveted dark-iron button plate ----------------------------------- */

/* The hero CTA look: painted plate stretched under the label. Scoped to
   the big action buttons (never the dense in-combat micro buttons). */
.commandButton.primary:not(.ghost):not(.healCommandButton),
.lobbyIdentity .commandButton:not(.ghost),
.lobbyJoinCode .commandButton:not(.ghost),
.commanderLevelUpDone {
  min-height: 42px;
  padding: 9px 20px;
  border: none;
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgb(255 235 180 / 7%) 0%, transparent 40%),
    var(--orn-button) center / 100% 100% no-repeat;
  color: #f2dea6;
  font-family: var(--font-heroic);
  font-weight: 700;
  letter-spacing: 0.05em;
  text-align: center;
  text-shadow: 0 1px 3px rgb(0 0 0 / 92%);
  box-shadow: 0 4px 12px rgb(0 0 0 / 50%);
  transition:
    filter 120ms ease,
    transform 120ms ease,
    box-shadow 120ms ease;
}

.commandButton.primary:not(.ghost):not(.healCommandButton):hover:not(:disabled),
.lobbyIdentity .commandButton:not(.ghost):hover:not(:disabled),
.lobbyJoinCode .commandButton:not(.ghost):hover:not(:disabled),
.commanderLevelUpDone:hover {
  filter: brightness(1.18);
  transform: translateY(-1px);
  box-shadow:
    0 0 14px rgb(213 168 79 / 40%),
    0 6px 14px rgb(0 0 0 / 55%);
}

.commandButton.primary:not(.ghost):not(.healCommandButton):active:not(
    :disabled
  ),
.lobbyIdentity .commandButton:not(.ghost):active:not(:disabled),
.lobbyJoinCode .commandButton:not(.ghost):active:not(:disabled) {
  transform: translateY(1px);
  filter: brightness(0.94);
}

.commandButton.primary:not(.ghost):not(.healCommandButton):disabled,
.lobbyIdentity .commandButton:not(.ghost):disabled {
  filter: grayscale(0.55) brightness(0.7);
  cursor: not-allowed;
}

/* ---- Inputs: dark engraved wells with a gold focus glow ---------------- */

.lobbyIdentity input,
.lobbyCreate input,
.lobbyJoinCode input,
.lobbyFilter input,
.lobbyChatComposer input,
.menuShellPanel input {
  border: 1px solid rgb(213 168 79 / 32%);
  border-radius: 7px;
  background: rgb(8 6 4 / 78%);
  color: #f0e6cd;
  box-shadow: inset 0 2px 6px rgb(0 0 0 / 65%);
  transition:
    border-color 120ms ease,
    box-shadow 120ms ease;
}

.lobbyIdentity input:focus,
.lobbyCreate input:focus,
.lobbyJoinCode input:focus,
.lobbyFilter input:focus,
.lobbyChatComposer input:focus,
.menuShellPanel input:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow:
    inset 0 2px 6px rgb(0 0 0 / 65%),
    0 0 10px rgb(247 207 110 / 35%);
}

/* ---- Lobby inner trays -------------------------------------------------- */

.lobbyActions,
.lobbyChat {
  border: 1px solid rgb(213 168 79 / 26%);
  border-radius: 10px;
  background: linear-gradient(180deg, rgb(0 0 0 / 30%), rgb(0 0 0 / 18%));
  box-shadow: inset 0 1px 6px rgb(0 0 0 / 45%);
}

.lobbyModeOption {
  border-color: rgb(213 168 79 / 22%);
  background: rgb(8 6 4 / 45%);
}

.lobbyModeOption.active {
  border-color: var(--cmp-gold);
  background: rgb(213 168 79 / 14%);
  box-shadow:
    inset 0 0 0 1px rgb(246 226 168 / 30%),
    0 0 10px rgb(213 168 79 / 22%);
}

/* ---- Spell Book: the real grimoire ------------------------------------- */

.spellBookBook {
  grid-template-columns: 1fr 7.4% 1fr;
  width: min(1000px, 95vw, calc(86vh * 1.42));
  max-height: none;
  aspect-ratio: 1.42;
  padding: 4% 6.4% 5%;
  border: none;
  border-radius: 0;
  background: var(--orn-grimoire) center / 100% 100% no-repeat;
  box-shadow: none;
  filter: drop-shadow(0 34px 60px rgb(0 0 0 / 75%));
}

.spellBookPage {
  background: transparent;
  color: #3a2a10;
}

.spellBookPage.left,
.spellBookPage.right {
  border-radius: 0;
  box-shadow: none;
}

.spellBookSpine {
  background: transparent; /* the painted jeweled spine shows through */
}

/* Close: the dragon-seal medallion. */
.spellBookBookClose {
  top: -18px;
  right: -18px;
  width: 44px;
  height: 44px;
  border: none;
  background: var(--orn-seal) center / cover no-repeat;
  color: #fdf3cf;
  filter: drop-shadow(0 3px 6px rgb(0 0 0 / 70%));
  transition:
    transform 120ms ease,
    filter 120ms ease;
}

.spellBookBookClose:hover,
.spellBookBookClose:focus-visible {
  color: #fff;
  filter: drop-shadow(0 3px 6px rgb(0 0 0 / 70%)) brightness(1.25);
  transform: scale(1.1);
}

.spellBookBookClose svg {
  filter: drop-shadow(0 1px 2px rgb(0 0 0 / 95%));
}

/* Index entries read as ink on the painted parchment. */
.spellBookIndexItem {
  background: rgb(96 64 22 / 10%);
}

.spellBookIndexItem:hover {
  background: rgb(96 64 22 / 20%);
}

.spellBookIndexItem.active {
  background: rgb(150 102 36 / 26%);
  border-color: rgb(110 74 26 / 60%);
}

/* ---- Server badge ------------------------------------------------------- */

.serverBadge {
  border-radius: 12px;
}

.serverBadgeName {
  font-family: var(--font-heroic);
  letter-spacing: 0.05em;
}

/* ---- Main-menu dragon breath (opt-in via dragonBreath) ------------------- */
/*
 * The painted flame ART itself rages and pours (not a static image + soft mask):
 *   1) Base jet — always on, violent brightness/contrast flicker
 *   2) Three phase-offset copies of the same art that continuously translate +
 *      scale from the mouth down-right along the jet — texture rolls outward
 *   3) Blurred heat-shimmer ghost moving faster
 *   4) Bottom impact smolder + ground embers + jet sparks
 * Alignment: same object-fit/cover + ken-burns as .menuShellBackdrop.
 */
.menuDragonBreath {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  transform-origin: 55% 42%;
  animation: cmpKenBurns 46s ease-in-out infinite alternate;
  will-change: transform;
}

.menuDragonBreathPlume,
.menuDragonBreathRage,
.menuDragonBreathShimmer,
.menuDragonBreathImpact,
.menuDragonBreathEmbers {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  pointer-events: none;
  user-select: none;
  mix-blend-mode: screen;
  /* Mouth of the cover dragon — all pour motion grows from here. */
  transform-origin: 46% 37%;
}

/* --- 1) Base jet: the art stays on and RAGES (filters + micro-warp) --- */
.menuDragonBreathPlume {
  opacity: 0.86;
  -webkit-mask-image: linear-gradient(
    152deg,
    #000 0%,
    #000 92%,
    transparent 100%
  );
  mask-image: linear-gradient(152deg, #000 0%, #000 92%, transparent 100%);
  animation:
    menuDragonArtRage 0.55s steps(2, end) infinite,
    menuDragonArtWobble 1.1s ease-in-out infinite alternate;
  will-change: filter, transform, opacity;
}

/* Stepped filter changes = hot flicker like real fire frames. */
@keyframes menuDragonArtRage {
  0% {
    opacity: 0.78;
    filter: brightness(1.05) contrast(1.08) saturate(1.12) hue-rotate(-4deg);
  }
  25% {
    opacity: 0.95;
    filter: brightness(1.28) contrast(1.18) saturate(1.28) hue-rotate(3deg);
  }
  50% {
    opacity: 0.82;
    filter: brightness(1.12) contrast(1.1) saturate(1.15) hue-rotate(-2deg);
  }
  75% {
    opacity: 1;
    filter: brightness(1.38) contrast(1.22) saturate(1.32) hue-rotate(4deg);
  }
  100% {
    opacity: 0.8;
    filter: brightness(1.08) contrast(1.09) saturate(1.14) hue-rotate(-3deg);
  }
}

/* Micro stretch along the jet so the painted tongue "breathes". */
@keyframes menuDragonArtWobble {
  from {
    transform: scale(0.985, 0.99) rotate(-0.35deg);
  }
  to {
    transform: scale(1.025, 1.04) rotate(0.4deg);
  }
}

/*
 * --- 2) Rage pour layers: the ART moves mouth → down ---
 * Each copy of the flame image slides + expands along the jet diagonal and
 * fades as it "lands". Three copies, 1/3 cycle apart → never a still frame.
 */
.menuDragonBreathRage {
  opacity: 0;
  will-change: transform, opacity, filter;
  -webkit-mask-image: linear-gradient(
    152deg,
    #000 0%,
    #000 88%,
    transparent 100%
  );
  mask-image: linear-gradient(152deg, #000 0%, #000 88%, transparent 100%);
  animation: menuDragonArtPour 1.15s linear infinite;
}

.menuDragonBreathRage1 {
  animation-delay: 0s;
  filter: brightness(1.25) saturate(1.2) contrast(1.08);
}

.menuDragonBreathRage2 {
  animation-delay: -0.38s;
  filter: brightness(1.35) saturate(1.25) contrast(1.12);
}

.menuDragonBreathRage3 {
  animation-delay: -0.76s;
  filter: brightness(1.18) saturate(1.15) contrast(1.06);
}

/*
 * Push the painted fire along the cover jet (down-right). Origin = mouth.
 * Scale grows as it leaves the jaws so it reads as force blasting outward.
 */
@keyframes menuDragonArtPour {
  0% {
    opacity: 0.15;
    transform: translate(-0.6%, -0.9%) scale(0.94) rotate(-0.5deg);
    filter: brightness(1.15) saturate(1.15) contrast(1.05);
  }
  8% {
    opacity: 0.9;
  }
  35% {
    opacity: 1;
    transform: translate(1.1%, 1.8%) scale(1.03) rotate(0.15deg);
    filter: brightness(1.4) saturate(1.28) contrast(1.14);
  }
  65% {
    opacity: 0.85;
    transform: translate(2.4%, 3.8%) scale(1.07) rotate(0.35deg);
    filter: brightness(1.3) saturate(1.22) contrast(1.1);
  }
  88% {
    opacity: 0.35;
  }
  100% {
    opacity: 0;
    transform: translate(3.6%, 5.8%) scale(1.12) rotate(0.55deg);
    filter: brightness(1.1) saturate(1.1) contrast(1.04);
  }
}

/* --- 3) Heat shimmer: blurred art ghost, faster pour --- */
.menuDragonBreathShimmer {
  opacity: 0.4;
  filter: blur(2.4px) brightness(1.45) saturate(1.3);
  -webkit-mask-image: linear-gradient(
    152deg,
    #000 0%,
    #000 85%,
    transparent 100%
  );
  mask-image: linear-gradient(152deg, #000 0%, #000 85%, transparent 100%);
  animation: menuDragonArtShimmer 0.85s linear infinite;
  will-change: transform, opacity;
}

@keyframes menuDragonArtShimmer {
  0% {
    opacity: 0.15;
    transform: translate(-0.4%, -0.6%) scale(0.97);
  }
  20% {
    opacity: 0.55;
  }
  55% {
    opacity: 0.45;
    transform: translate(1.8%, 2.8%) scale(1.06);
  }
  100% {
    opacity: 0.1;
    transform: translate(3.2%, 5%) scale(1.12);
  }
}

/* --- 4) Bottom landing blaze — constant smolder where the stream hits --- */
.menuDragonBreathImpact {
  opacity: 0.75;
  clip-path: ellipse(50% 44% at 78% 91%);
  transform-origin: 78% 91%;
  animation:
    menuDragonImpactSmolder 1.4s ease-in-out infinite alternate,
    menuDragonImpactRage 0.45s steps(2, end) infinite;
}

@keyframes menuDragonImpactSmolder {
  from {
    opacity: 0.55;
    transform: scale(0.96);
  }
  to {
    opacity: 0.92;
    transform: scale(1.06);
  }
}

@keyframes menuDragonImpactRage {
  0% {
    filter: brightness(1.1) blur(0.5px) saturate(1.08);
  }
  50% {
    filter: brightness(1.4) blur(0.1px) saturate(1.25);
  }
  100% {
    filter: brightness(1.15) blur(0.4px) saturate(1.1);
  }
}

.menuDragonGroundBurn {
  position: absolute;
  left: 50%;
  top: 64%;
  width: 52%;
  height: 42%;
  pointer-events: none;
  mix-blend-mode: screen;
  background:
    radial-gradient(
      ellipse 58% 48% at 58% 74%,
      rgb(255 72 10 / 55%) 0%,
