/* Switching spells re-mounts the right page (keyed by turn count): the new
   plate swings in from the spine while a paper leaf — parchment-textured,
   with a sweeping edge shadow — flips away over it. */
.spellBookPage.right.turning {
  animation: spellBookPageTurn 460ms cubic-bezier(0.16, 0.7, 0.3, 1);
}

.spellBookTurnLeaf {
  position: absolute;
  inset: 0;
  z-index: 6;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transform-origin: left center;
  backface-visibility: hidden;
  background:
    linear-gradient(
      105deg,
      rgb(96 64 22 / 0%) 52%,
      rgb(96 64 22 / 20%) 86%,
      rgb(60 40 14 / 34%) 100%
    ),
    var(--orn-parchment) center / cover;
  box-shadow: inset 0 0 26px rgb(96 64 22 / 24%);
}

