  opacity: 1;
  transition-duration: 0ms;
}

/* Melee slash and impact sparks hit harder (hotter core, deeper glow). */
.fxSlashStreak {
  filter: brightness(1.22) drop-shadow(0 0 10px rgb(255 214 120 / 65%));
}

.fxImpactSpark {
  filter: brightness(1.3) drop-shadow(0 0 6px rgb(255 190 90 / 70%));
}

/* Gliding unit/card ghosts trail a soft gold wake. */
.fxMoveGhost {
  filter: drop-shadow(0 0 12px rgb(240 196 106 / 40%))
    drop-shadow(0 6px 14px rgb(0 0 0 / 45%));
}

