  50% {
    filter: drop-shadow(0 4px 14px rgb(0 0 0 / 55%))
      drop-shadow(0 0 16px rgb(240 196 106 / 42%));
  }
}

/* ==================================================================== */
/* ORNATE DRAGON — Azure claw + frost under grip.                        */
/* Glow = silhouette drop-shadow on the claw ONLY (curves with art).     */
/* NEVER linear-mask the claw (full-width fade = square light frame).    */
/* Frost rim is separate, tightly oval-masked under the talons.          */
/* ==================================================================== */
:root {
  --orn-azure-claw: url("/assets/ui/ornate/azure-claw.webp");
  --orn-azure-frost-rim: url("/assets/ui/ornate/azure-frost-rim.webp");
}

/*
 * Painted geometry (claw 820×520): bar top edge at ~67.4% of art height.
 * Displayed 225px wide → that line is 96px from the art top.
 * top: -96px lands the knuckles on the real bar rim.
 * Anchored LEFT over the deck / Spell Book cluster (ownDeckColumn sits under
 * the grip with margin-top so the talons clear the faces).
 */
.azureClawChrome {
  position: absolute;
  top: -96px;
  left: -8px;
  width: 225px;
  height: 143px;
  z-index: 0;
  pointer-events: none;
  overflow: visible;
}

/*
 * Frost under the talons / bar edge. Narrow + strong radial mask so it
 * reads as ice under the grip, never a horizontal box.
 */
.azureClawFrostRim {
  position: absolute;
  left: 20%;
  /* Slightly below the bar rim (~96px) so frost sits under the talons. */
  top: 94px;
  width: 60%;
  height: auto;
  display: block;
  object-fit: contain;
  object-position: center top;
  pointer-events: none;
  user-select: none;
  opacity: 0.5;
  filter: drop-shadow(0 0 3px rgb(160 220 255 / 25%));
  -webkit-mask-image: radial-gradient(
    ellipse 52% 78% at 50% 12%,
    #000 0%,
    #000 32%,
    rgb(0 0 0 / 45%) 55%,
    transparent 76%
  );
  mask-image: radial-gradient(
    ellipse 52% 78% at 50% 12%,
    #000 0%,
    #000 32%,
    rgb(0 0 0 / 45%) 55%,
    transparent 76%
  );
  animation: azureFrostBreathe 7.5s ease-in-out infinite;
}

@keyframes azureFrostBreathe {
  0%,
  100% {
    opacity: 0.4;
  }
  50% {
    opacity: 0.58;
  }
}

/*
 * Claw — tight cyan drop-shadows hug the painted outline.
 * Short blur only (long blur = soft rectangular cloud).
 * NO mask-image on this element.
 */
.azureClawHand {
  position: absolute;
  left: 0;
  top: 0;
  width: 225px;
  height: auto;
  display: block;
  object-fit: contain;
  object-position: center top;
  pointer-events: none;
  user-select: none;
  filter: drop-shadow(0 3px 6px rgb(0 0 0 / 50%))
    drop-shadow(0 0 2px rgb(200 240 255 / 70%))
    drop-shadow(0 0 6px rgb(160 225 255 / 48%))
    drop-shadow(0 0 11px rgb(130 210 255 / 28%));
  animation: azureClawSilhouetteGlow 7.5s ease-in-out infinite;
}

@keyframes azureClawSilhouetteGlow {
  0%,
  100% {
    filter: drop-shadow(0 3px 6px rgb(0 0 0 / 50%))
      drop-shadow(0 0 2px rgb(190 235 255 / 55%))
      drop-shadow(0 0 5px rgb(150 220 255 / 36%))
      drop-shadow(0 0 10px rgb(120 205 250 / 18%));
  }
  50% {
    filter: drop-shadow(0 3px 6px rgb(0 0 0 / 50%))
      drop-shadow(0 0 3px rgb(220 248 255 / 85%))
      drop-shadow(0 0 8px rgb(175 230 255 / 55%))
      drop-shadow(0 0 14px rgb(145 215 255 / 30%));
  }
}

/* ---- Reduced motion: everything settles, nothing is lost ----------------- */

@media (prefers-reduced-motion: reduce) {
  .menuGameLogo,
  .spellBookPage.right.turning,
  .spellBookPage.right.turning .spellBookTurnLeaf,
  .spellBookBook {
    animation: none;
  }

  .azureClawFrostRim,
  .azureClawHand {
    animation: none;
  }

  .azureClawFrostRim {
    opacity: 0.5;
  }

  .menuMote {
    display: none;
  }
}

