  color: #d4a070;
  cursor: pointer;
  font-size: 0.78rem;
}

.sandboxEmpty {
  color: #8a7654 !important;
  font-style: italic;
}

.sandboxPickGrid {
  max-height: 180px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
  border: 1px solid rgba(100, 80, 45, 0.35);
  border-radius: 8px;
  padding: 4px;
  background: rgba(0, 0, 0, 0.25);
}

.sandboxPickRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 6px;
  color: #dcc9a0;
  font-size: 0.82rem;
}

.sandboxPickRow small {
  color: #8a7654;
}

.sandboxSideButtons {
  display: inline-flex;
  gap: 4px;
  flex-shrink: 0;
}

.sandboxSideButtons button,
.sandboxCardPick {
  border-radius: 5px;
  border: 1px solid rgba(140, 110, 65, 0.45);
  background: rgba(36, 26, 14, 0.9);
  color: #f0dfb4;
  font-size: 0.75rem;
  padding: 2px 6px;
  cursor: pointer;
}

.sandboxSideButtons button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.sandboxCardPick {
  text-align: left;
  padding: 4px 8px;
}

.sandboxCardPick small {
  color: #8a7654;
  margin-right: 6px;
  text-transform: uppercase;
  font-size: 0.68rem;
}

.sandboxZoneToggle {
  display: inline-flex;
  gap: 4px;
}

.sandboxZoneToggle button {
  border-radius: 6px;
  border: 1px solid rgba(140, 110, 65, 0.45);
  background: transparent;
  color: #cbb892;
  padding: 3px 8px;
  font-size: 0.78rem;
  cursor: pointer;
}

.sandboxZoneToggle button.selected {
  background: rgba(168, 137, 79, 0.25);
  color: #f3e2b8;
  border-color: rgba(200, 160, 80, 0.6);
}

.sandboxGradeGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.sandboxGradeGrid label {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 0.72rem;
  color: #a8894f;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sandboxGradeGrid select {
  border-radius: 6px;
  border: 1px solid rgba(140, 110, 65, 0.5);
  background: rgba(10, 8, 5, 0.9);
  color: #f0dfb4;
  padding: 4px 6px;
}

.sandboxSetupFoot {
  display: flex;
  justify-content: center;
  padding: 8px 0 16px;
}

/* Single-player creation panel (/single-player) ------------------------------ */

.singlePlayerOpponents {
  display: grid;
  gap: 8px;
  margin: 14px 0;
}

.singlePlayerOpponentChoices {
  display: flex;
  gap: 8px;
}

.singlePlayerOpponentChoice {
  min-width: 52px;
  justify-content: center;
  font-size: 18px;
  font-weight: 700;
}

.singlePlayerOpponentChoice.selected {
  border-color: var(--gold, #d9b45b);
  box-shadow: 0 0 0 1px var(--gold, #d9b45b) inset;
}

/* Setup-lobby seat controller badges (single-player) ------------------------- */

.computerSeatBadge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 6px;
  border: 1px solid rgb(140 150 190 / 55%);
  border-radius: 8px;
  background: rgb(40 46 70 / 60%);
  color: #b9c4e8;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  vertical-align: middle;
}

.computerSeatBadge.you {
  border-color: rgb(217 180 91 / 60%);
  background: rgb(70 58 26 / 60%);
  color: #ecd9a4;
}

/* Single-player: the human owner's per-opponent faction/hero picker blocks. */
.computerSeatPickers {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid rgb(170 130 70 / 30%);
}

.computerSeatPicker {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid rgb(140 150 190 / 40%);
  border-radius: 10px;
  background: rgb(30 34 52 / 30%);
}

.computerSeatPickerHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.computerSeatPickerName {
  font-weight: 700;
  color: #c7d0ec;
  text-shadow: 0 1px 4px rgb(0 0 0 / 85%);
}

.computerSeatPickerPick {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.computerSeatPickerNames {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.computerSeatPickerNames strong {
  text-shadow: 0 1px 4px rgb(0 0 0 / 85%);
}

.computerSeatPickerNames small {
  color: #b89f78;
}

.computerSeatPickerAuto {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #b9c4e8;
  font-size: 12px;
  font-style: italic;
}

.computerSeatPickerButtons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.presentationSkip {
  position: fixed;
  right: 1rem;
  bottom: 1rem;
  z-index: 10020;
  box-shadow: 0 0.35rem 1.2rem rgb(0 0 0 / 55%);
}

/* =========================================================================
   Helper coach — next-step strip + lobby opt-in + "why blocked" card badges
   ========================================================================= */

.helperCoachBackdrop {
  position: fixed;
  inset: 0;
  z-index: 1250;
  display: grid;
  place-items: center;
  padding: 20px;
  background: radial-gradient(
    circle at 50% 28%,
    rgba(0, 0, 0, 0.5),
    rgba(0, 0, 0, 0.84)
  );
  animation: welcomeFade 0.2s ease;
}

.helperCoachCard {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 0;
  max-width: 560px;
  width: 100%;
  border-radius: 16px;
  overflow: hidden;
  color: #ecd9b0;
  background:
    radial-gradient(
      circle at 12% 6%,
      rgba(255, 214, 120, 0.1),
      transparent 42%
    ),
    linear-gradient(160deg, #2c2013 0%, #1c140b 60%, #120d07 100%);
  border: 1px solid rgba(220, 175, 95, 0.55);
  box-shadow:
    inset 0 0 0 1px rgba(255, 226, 160, 0.1),
    0 24px 60px rgba(0, 0, 0, 0.6);
  animation: welcomeRise 0.24s cubic-bezier(0.2, 0.9, 0.3, 1);
}

.helperCoachCardIcon {
  display: grid;
  place-items: center;
  background: linear-gradient(
    180deg,
    rgba(255, 210, 100, 0.18),
    rgba(0, 0, 0, 0.25)
  );
  border-right: 1px solid rgba(220, 175, 95, 0.28);
  color: #ffd76a;
}

.helperCoachCardBody {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 20px 22px 18px;
}

.helperCoachEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #c9a86a;
}

.helperCoachTitle {
  margin: 0;
  font-size: 1.35rem;
  font-weight: 800;
  color: #ffe9b0;
  letter-spacing: 0.01em;
}

.helperCoachLede {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.45;
  color: #e0cfad;
}

.helperCoachList {
  margin: 0;
  padding: 0 0 0 1.1rem;
  font-size: 12.5px;
  line-height: 1.5;
  color: #d4c19a;
}

.helperCoachList li {
  margin: 2px 0;
}

.helperCoachActions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}

.helperCoachPrimary,
.helperCoachSecondary {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 9px 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    filter 120ms ease,
    transform 120ms ease;
}

.helperCoachPrimary {
  border: 1px solid #b98f3f;
  color: #2c1d08;
  background: linear-gradient(180deg, #f4d78c 0%, #d4a84a 48%, #b98f3f 100%);
  box-shadow:
    inset 0 1px 0 rgb(255 247 218 / 78%),
    0 2px 6px rgb(0 0 0 / 35%);
}

.helperCoachSecondary {
  border: 1px solid rgba(220, 175, 95, 0.4);
  color: #e6d2a6;
  background: rgba(10, 7, 4, 0.45);
}

.helperCoachPrimary:hover,
.helperCoachSecondary:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

.helperCoachFoot {
  color: rgba(220, 190, 140, 0.65);
  font-size: 11px;
}

.helperCoachLobbyNote {
  margin: 8px 0 0;
  font-size: 12.5px;
  color: #c9b48a;
}

.helperCoachLobbyLink {
  appearance: none;
  border: none;
  background: none;
  padding: 0;
  color: #ffd76a;
  font: inherit;
  font-weight: 700;
  text-decoration: underline;
  cursor: pointer;
}

.helperCoachLobbyLink:hover {
  color: #ffe9b0;
}

/* Floating next-step panel: center of screen, draggable, blinks for attention. */
.helperCoachStrip {
  position: fixed;
  z-index: 900;
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(440px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  padding: 12px 14px 12px 10px;
  border-radius: 14px;
  border: 2px solid #ffd76a;
  background: linear-gradient(165deg, rgb(52 40 18 / 98%), rgb(18 14 8 / 98%));
  box-shadow:
    inset 0 0 0 1px rgba(255, 236, 180, 0.18),
    0 0 0 1px rgba(0, 0, 0, 0.5),
    0 16px 40px rgba(0, 0, 0, 0.65),
    0 0 28px rgba(255, 200, 60, 0.35);
  color: #fff4d4;
  pointer-events: auto;
  user-select: none;
  touch-action: none;
  animation: helperCoachPulse 1.35s ease-in-out infinite;
}

@keyframes helperCoachPulse {
  0%,
  100% {
    box-shadow:
      inset 0 0 0 1px rgba(255, 236, 180, 0.18),
      0 0 0 1px rgba(0, 0, 0, 0.5),
      0 16px 40px rgba(0, 0, 0, 0.65),
      0 0 18px rgba(255, 200, 60, 0.28);
    border-color: #e8c050;
    filter: brightness(1);
  }
  50% {
    box-shadow:
      inset 0 0 0 1px rgba(255, 246, 200, 0.35),
      0 0 0 2px rgba(255, 215, 100, 0.55),
      0 18px 48px rgba(0, 0, 0, 0.7),
      0 0 42px rgba(255, 210, 70, 0.65);
    border-color: #ffe28a;
    filter: brightness(1.08);
  }
}

.helperCoachStrip.dragging {
  animation: none;
  cursor: grabbing;
  filter: brightness(1.05);
  box-shadow:
    inset 0 0 0 1px rgba(255, 236, 180, 0.25),
    0 0 0 2px rgba(255, 215, 100, 0.7),
    0 22px 50px rgba(0, 0, 0, 0.75),
    0 0 36px rgba(255, 200, 60, 0.45);
}

.helperCoachDragHandle {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  flex: 0 0 auto;
  min-width: 40px;
  padding: 8px 4px;
  margin: -4px 0 -4px -2px;
  border: 1px solid rgba(255, 215, 106, 0.35);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.35);
  color: #ffd76a;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: grab;
  touch-action: none;
}

.helperCoachDragHandle:hover {
  border-color: #ffd76a;
  background: rgba(255, 210, 80, 0.12);
  color: #ffe9b0;
}

.helperCoachStrip.dragging .helperCoachDragHandle {
  cursor: grabbing;
}

.helperCoachStrip.tone-go {
  border-color: #8fd87a;
  background: linear-gradient(165deg, rgb(28 48 24 / 98%), rgb(12 20 12 / 98%));
  animation-name: helperCoachPulseGo;
}

@keyframes helperCoachPulseGo {
  0%,
  100% {
    box-shadow:
      inset 0 0 0 1px rgba(160, 230, 140, 0.15),
      0 16px 40px rgba(0, 0, 0, 0.65),
      0 0 16px rgba(100, 200, 80, 0.25);
    border-color: #6bb85a;
    filter: brightness(1);
  }
  50% {
    box-shadow:
      inset 0 0 0 1px rgba(180, 255, 160, 0.3),
      0 0 0 2px rgba(140, 230, 110, 0.5),
      0 18px 48px rgba(0, 0, 0, 0.7),
      0 0 40px rgba(120, 230, 90, 0.55);
    border-color: #b4f0a0;
    filter: brightness(1.08);
  }
}

.helperCoachStrip.tone-wait {
  border-color: #9aabcc;
  background: linear-gradient(165deg, rgb(32 38 52 / 98%), rgb(14 16 24 / 98%));
  animation-name: helperCoachPulseWait;
}

@keyframes helperCoachPulseWait {
  0%,
  100% {
    box-shadow:
      inset 0 0 0 1px rgba(160, 180, 220, 0.12),
      0 16px 40px rgba(0, 0, 0, 0.65),
      0 0 14px rgba(120, 140, 200, 0.22);
    border-color: #7a8cb0;
    filter: brightness(1);
  }
  50% {
    box-shadow:
      inset 0 0 0 1px rgba(180, 200, 240, 0.28),
      0 0 0 2px rgba(140, 160, 210, 0.45),
      0 18px 48px rgba(0, 0, 0, 0.7),
      0 0 36px rgba(130, 160, 230, 0.5);
    border-color: #c0d0f0;
    filter: brightness(1.07);
  }
}

.helperCoachStrip.tone-choice {
  border-color: #ffd76a;
}

.helperCoachStrip.tone-info {
  border-color: #c9b48a;
}

.helperCoachStripIcon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: rgba(255, 210, 100, 0.18);
  color: #ffd76a;
  animation: helperCoachIconBlink 1.35s ease-in-out infinite;
}

@keyframes helperCoachIconBlink {
  0%,
  100% {
    opacity: 0.85;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.08);
    background: rgba(255, 220, 120, 0.32);
  }
}

.helperCoachStrip.tone-go .helperCoachStripIcon {
  background: rgba(120, 200, 100, 0.2);
  color: #b8f0a0;
}

.helperCoachStrip.tone-wait .helperCoachStripIcon {
  background: rgba(140, 160, 200, 0.2);
  color: #c8d4f0;
}

.helperCoachStripText {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1 1 auto;
}

.helperCoachStripLabel {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #ffd76a;
}

.helperCoachStrip.tone-go .helperCoachStripLabel {
  color: #a8e090;
}

.helperCoachStrip.tone-wait .helperCoachStripLabel {
  color: #a8b8d8;
}

.helperCoachStripText strong {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: #fff6d8;
  line-height: 1.2;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.55);
}

.helperCoachStrip.tone-go .helperCoachStripText strong {
  color: #e8ffd8;
}

.helperCoachStripText small {
  font-size: 13px;
  line-height: 1.4;
  color: rgba(255, 240, 200, 0.92);
}

.helperCoachStripHide {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1px solid rgba(220, 175, 95, 0.45);
  background: rgba(0, 0, 0, 0.4);
  color: #e8d4a8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.helperCoachStripHide:hover {
  border-color: rgba(255, 215, 106, 0.85);
  color: #fff0c0;
  background: rgba(40, 28, 12, 0.7);
}

.helperCoachChip {
  position: fixed;
  right: 14px;
  bottom: 14px;
  z-index: 890;
  display: flex;
  justify-content: flex-end;
  pointer-events: none;
}

.helperCoachChipButton {
  pointer-events: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(220, 175, 95, 0.55);
  background: rgba(22, 16, 10, 0.92);
  color: #e0c890;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.45);
}

.helperCoachChipButton:hover {
  border-color: #ffd76a;
  color: #ffe9b0;
}

/* Greyed card + "?" badge when helper tips explain why it cannot be played. */
.fanCard.helperBlocked .fanCardImage,
.adventureHandCard.helperBlocked .handCardImage {
  filter: grayscale(0.35) brightness(0.82);
  opacity: 0.88;
}

.fanCard.helperBlockedBadge,
.helperBlockedBadge {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  border: 1px solid rgba(220, 175, 95, 0.65);
  background: rgba(20, 14, 8, 0.88);
  color: #ffd76a;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  pointer-events: none;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.45);
}

.fanCard {
  position: relative;
}

.adventureHandCard {
  position: relative;
}

.cardPopover .noTiming.helperWhy,
.handPlayMenu .helperWhy,
.rulesetNote.helperWhy {
  color: #e8c878;
  font-style: normal;
  font-weight: 600;
}

@media (max-width: 640px) {
  .helperCoachCard {
    grid-template-columns: 1fr;
  }

  .helperCoachCardIcon {
    min-height: 56px;
    border-right: none;
    border-bottom: 1px solid rgba(220, 175, 95, 0.28);
  }

  .helperCoachStrip {
    width: min(440px, calc(100vw - 16px));
    padding: 10px 10px 10px 8px;
    gap: 8px;
  }

  .helperCoachStripText strong {
    font-size: 14px;
  }

  .helperCoachStripHide span {
    display: none;
  }

  .helperCoachDragHandle span {
    display: none;
  }
}

/* --- Map preset editor (designer conditions) --------------------------- */
.mapPresetEditor {
  margin-top: 14px;
  display: grid;
  gap: 12px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid rgba(154, 208, 255, 0.28);
  background: linear-gradient(
    180deg,
    rgba(22, 30, 44, 0.95),
    rgba(14, 18, 28, 0.98)
  );
  /* Fill the (stable) column so collapsing the panel changes only its HEIGHT,
     never its width — no horizontal jump. Capped so it never sprawls too wide. */
  justify-self: stretch;
  min-width: 0;
  max-width: 860px;
  box-sizing: border-box;
}

.mapPresetHeader {
  display: grid;
  gap: 4px;
}

.mapPresetHeader strong {
  color: #e8f0ff;
  font-size: 13px;
}

.mapPresetHeader small,
.mapPresetEmpty,
.mapPresetHint {
  color: rgba(190, 210, 235, 0.75);
  font-size: 11px;
  line-height: 1.4;
}

.mapPresetSummary {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(154, 208, 255, 0.35);
  background: rgba(30, 48, 70, 0.85);
  color: #d8e8ff;
  font-size: 11px;
}

.mapPresetSummaryTitle {
  font-weight: 700;
  margin-bottom: 4px;
  color: #f0f6ff;
}

.mapPresetSummary ul,
.mapPresetList {
  margin: 0;
  padding-left: 18px;
}

.mapPresetSummary li,
.mapPresetList li {
  margin: 2px 0;
}

.mapPresetClear,
.mapPresetLinkBtn {
  margin-top: 6px;
  padding: 4px 8px;
  border-radius: 8px;
  border: 1px solid rgba(154, 208, 255, 0.35);
  background: rgba(24, 36, 52, 0.9);
  color: #c8dcff;
  font-size: 11px;
  cursor: pointer;
}

.mapPresetClear:hover,
.mapPresetLinkBtn:hover:not(:disabled) {
  border-color: #9ad0ff;
}

.mapPresetLinkBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.mapPresetSection {
  display: grid;
  gap: 6px;
  padding: 10px 0 2px;
  border-top: 1px solid rgba(154, 208, 255, 0.14);
}

/* The first section sits right under the summary — no double divider. */
.mapPresetSection:first-of-type {
  border-top: none;
  padding-top: 2px;
}

.mapPresetSectionLabel {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(190, 210, 235, 0.72);
}

.mapPresetChipRow {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

/* Objectives section: one labelled row per knob (Grail Obelisks / Utopia …). */
.mapPresetObjectiveRow {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 8px;
}
.mapPresetObjectiveLabel {
  font-size: 11px;
  color: rgba(210, 224, 240, 0.86);
}

.mapPresetChip {
  padding: 5px 9px;
  border-radius: 999px;
  border: 1px solid rgba(154, 208, 255, 0.3);
  background: rgba(28, 40, 56, 0.9);
  color: #e0ecff;
  font-size: 11px;
  cursor: pointer;
}

.mapPresetChip:hover:not(:disabled) {
  border-color: rgba(154, 208, 255, 0.7);
}

.mapPresetChip:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.mapPresetChip.active {
  border-color: #9ad0ff;
  background: rgba(40, 70, 100, 0.95);
