/* ---- SP2. A filigree rail above the actions --------------------------- */
/* Hung in the panel's existing 14px grid gap above the action nav (absolute, */
/* so it consumes no layout and moves no button), it rules the "choose your    */
/* opponents" block off from the deliberate Create/Back actions — the same     */
/* rail-divider that rules the Deploy title and the designer header.           */
.menuNav[aria-label="Single player"] {
  position: relative;
}

.menuNav[aria-label="Single player"]::before {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: -13px;
  height: 12px;
  background: var(--orn-rail) center / 100% 12px no-repeat;
  opacity: 0.78;
  filter: drop-shadow(0 1px 2px rgb(0 0 0 / 55%));
  pointer-events: none;
}

/* ---- SP3. Create game → raised gilded plate; Back → quiet leather ------ */
/* The boxless main-menu skin renders both as bare engraved-gold labels. Here */
/* the primary CTA gets its OWN surface back — a warm gilded leather plate     */
/* with a strong gold hairline and a float shadow — so it reads as THE action, */
/* while "Back" (the <a>) takes the room panel's quiet leather-plate.          */
.menuNav[aria-label="Single player"] > .menuNavButton {
  border-radius: 12px;
  border: 1px solid var(--cmp-gold-deep);
  background:
    linear-gradient(180deg, rgb(34 25 14 / 90%), rgb(20 14 8 / 93%)),
    var(--cmp-leather) center / 240px repeat;
  box-shadow:
    inset 0 1px 0 rgb(246 226 168 / 12%),
    0 6px 16px rgb(0 0 0 / 40%);
}

.menuNav[aria-label="Single player"] > .menuNavButton:hover:not(:disabled) {
  border-color: var(--cmp-gold);
}

/* The CTA (the <button>) is warmer + gilded so it out-reads the quiet Back. */
.menuNav[aria-label="Single player"] > button.menuNavButton {
  background:
    radial-gradient(
      120% 135% at 50% -22%,
      rgb(244 215 140 / 20%),
      transparent 58%
    ),
    linear-gradient(180deg, rgb(50 37 19 / 94%), rgb(28 19 10 / 96%)),
    var(--cmp-leather) center / 240px repeat;
  box-shadow:
    inset 0 0 0 1px rgb(217 178 90 / 40%),
    inset 0 1px 0 rgb(255 240 200 / 22%),
    inset 0 -14px 26px rgb(0 0 0 / 32%),
    0 8px 20px rgb(0 0 0 / 46%);
}

.menuNav[aria-label="Single player"]
  > button.menuNavButton:hover:not(:disabled) {
  border-color: var(--cmp-gold);
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.menuNav[aria-label="Single player"] > button.menuNavButton:disabled {
  filter: grayscale(0.5) brightness(0.72);
  opacity: 0.72;
}

/* ======================================================================== */
/* DESKTOP COMMAND HUD                                                      */
/*                                                                          */
/* The map is the work surface; the things a player repeatedly reads or     */
/* touches stay docked around it: status/resources at the top, town/hero/    */
/* army on the left, shared libraries on the right, and the hand at the      */
/* bottom. This is deliberately desktop-only: phone mode keeps its tabbed    */
/* full-screen panels below.                                                 */
/* ======================================================================== */

/* Below the command-HUD breakpoint nothing collapses the table controls, so
   the "Table" trigger would be a dead button beside a menu that is already
   fully expanded. (Phone mode hides it in its own block too.) */
@media (max-width: 1100px) {
  .tableControlsToggle {
    display: none;
  }
}

/* Once a live desktop table owns the viewport, its sticky HUD replaces the
   generic site masthead. Keep setup/menu pages branded, but do not spend a
   second header and footer row inside the game. (Lives HERE, not in the PHONE
   UI MODE block: it is a desktop rule and every selector in that block must be
   `.phoneMode`-prefixed.) */
@media (min-width: 1101px) {
  .appShell:has(.tableMenuInline) .topBar,
  .appShell:has(.tableMenuInline) .footerNotice {
    display: none;
  }
}

@media (min-width: 1101px) {
  .adventureRoot:not(.phoneMode) {
    --desktop-hud-height: 62px;
    --desktop-hand-height: 198px;
    --desktop-library-width: clamp(104px, 6.2vw, 116px);
    --desktop-edge: max(14px, calc((100vw - 1680px) / 2 + 14px));
    padding-bottom: calc(var(--desktop-hand-height) + 18px);
  }

  /* Status and resources remain readable while the map scrolls. The old
     wrapped ribbon could become two or three rows tall; one compact strip
     keeps the map directly under it and permits a small horizontal scroll at
     unusually dense rulesets. */
  .adventureRoot:not(.phoneMode) > .tableTopRow {
    position: sticky;
    top: 6px;
    z-index: 55;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px;
    align-items: start;
  }

  /* History lives in the top command band as one compact scroll button.
     Opening it produces a floating chronicle below that button instead of
     inserting the full event feed into the map layout. */
  .adventureRoot:not(.phoneMode) .advHudButtons {
    position: relative;
  }

  /* 110px: the narrowest that fits the whole "EVENT LOG" tag beside its icon
     (measured — 96px ellipsized it to "EVENT L…"). */
  .adventureRoot:not(.phoneMode) .advHudButtons > .logDrawer {
    position: relative;
    flex: 0 0 110px;
    width: 110px;
    min-width: 110px;
    margin: 0;
    overflow: visible;
    border: 1px solid var(--cmp-gold-deep);
    border-radius: 9px;
    background:
      linear-gradient(180deg, rgb(34 25 14 / 96%), rgb(18 13 8 / 98%)),
      var(--cmp-leather) center / 180px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 28%),
      inset 0 1px 0 rgb(246 226 168 / 12%),
      0 6px 18px rgb(0 0 0 / 46%);
  }

  .adventureRoot:not(.phoneMode) .advHudButtons > .logDrawer .logToggle {
    justify-content: center;
    gap: 5px;
    width: 108px;
    min-height: 36px;
    padding: 0 6px;
    color: var(--cmp-gold-bright);
  }

  /* The pill is only 110px: no room for the chevron or the live ticker line. */
  .adventureRoot:not(.phoneMode)
    .advHudButtons
    > .logDrawer
    .logToggle
    svg:last-child,
  .adventureRoot:not(.phoneMode)
    .advHudButtons
    > .logDrawer
    .logToggle
    .logToggleLatest {
    display: none;
  }

  .adventureRoot:not(.phoneMode) .advHudButtons > .logDrawer .logToggle span {
    flex: 0 1 auto;
    color: #f0dcb8;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.02em;
  }

  /* FIXED, not absolute: the command band scrolls horizontally
     (`overflow-x: auto`), which clips both axes — an absolute popover would be
     cut off exactly like the left-rail fly-outs were. Capped so the chronicle
     can never run under the fixed hand tray. */
  .adventureRoot:not(.phoneMode) .advHudButtons > .logDrawer .logPopover {
    position: fixed;
    top: calc(6px + var(--desktop-hud-height) + 6px);
    /* Right edge lands just LEFT of the fixed shared-deck rail, so the open
       chronicle never paints over the library's deck labels. */
    right: calc(var(--desktop-edge) + var(--desktop-library-width) + 14px);
    z-index: 92;
    width: min(560px, calc(100vw - var(--desktop-library-width) - 260px));
    max-height: calc(
      100vh - var(--desktop-hud-height) - var(--desktop-hand-height) - 40px
    );
    overflow: hidden;
    border: 1px solid var(--cmp-gold-deep);
    border-radius: 9px;
    background:
      linear-gradient(180deg, rgb(26 19 11 / 99%), rgb(13 10 7 / 99%)),
      var(--cmp-leather) center / 280px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 25%),
      0 18px 48px rgb(0 0 0 / 72%);
  }

  .adventureRoot:not(.phoneMode) .advHudButtons > .logDrawer .logPopover ol {
    max-height: calc(
      100vh - var(--desktop-hud-height) - var(--desktop-hand-height) - 96px
    );
  }

  .adventureRoot:not(.phoneMode) > .tableTopRow > .advHud {
    min-height: var(--desktop-hud-height);
    max-height: var(--desktop-hud-height);
    flex-wrap: nowrap;
    gap: 6px;
    padding: 5px 8px;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: thin;
    overscroll-behavior-x: contain;
  }

  .adventureRoot:not(.phoneMode) .advHudCell {
    flex: 0 0 auto;
    gap: 0;
    padding-right: 8px;
    white-space: nowrap;
  }

  .adventureRoot:not(.phoneMode) .advHudCell strong {
    font-size: 12px;
  }

  .adventureRoot:not(.phoneMode) .advHudCell small {
    font-size: 9.5px;
  }

  .adventureRoot:not(.phoneMode) .advHudCell.resources {
    gap: 6px;
    padding: 2px 8px 2px 0;
  }

  .adventureRoot:not(.phoneMode) .resourceChip {
    gap: 3px;
  }

  .adventureRoot:not(.phoneMode) .resourceIcon {
    width: 22px;
    height: 22px;
  }

  .adventureRoot:not(.phoneMode) .incomeNote {
    max-width: 54px;
    font-size: 8px;
    line-height: 1.05;
    white-space: normal;
  }

  .adventureRoot:not(.phoneMode) .moveMoraleCell {
    gap: 5px;
  }

  .adventureRoot:not(.phoneMode) .advHudButtons {
    flex: 0 0 auto;
    gap: 4px;
  }

  .adventureRoot:not(.phoneMode) .advHudButtons .commandButton {
    min-height: 30px;
    padding: 4px 9px;
    font-size: 11px;
    white-space: nowrap;
  }

  /* In-game room controls are utility controls, not page content. Remove the
     join/ID row in JSX, and compress the remaining controls into a narrow
     cluster. Opening Room produces a floating manager instead of stretching
     the sticky header and pushing the map away. */
  .tableRoot:not(.phoneMode) > .tableTopRow > .tableMenu.tableMenuInline {
    position: relative;
    display: block;
    min-height: 0;
  }

  /* Collapsed: only the toggle shows — EXCEPT the room-password gate. A viewer
     who follows a direct link into a locked, already-running table has exactly
     one thing to do (type the password); hiding it behind a button labelled
     "Table" reads as "this room is broken". `.roomPasswordRow` is stamped on
     that row in page.tsx, and pinned by page-phone-mode.test.tsx so this
     exclusion always has a target. */
  .tableRoot:not(.phoneMode)
    > .tableTopRow
    > .tableMenu.tableMenuInline:not(.controlsOpen)
    > :not(.tableControlsToggle):not(.roomPasswordRow) {
    display: none;
  }

  /* The open panel is absolutely positioned against the top row. The ADVENTURE
     top row is `position: sticky` (below), which anchors it; the COMBAT top row
     is a plain static grid, so without this the panel's containing block became
     the initial containing block and `top: calc(100% + 6px)` dropped it a full
     viewport down — the button and every table control jumped off-screen the
     moment a player opened them mid-battle. Relative on a static grid item is
     visually a no-op; :not(.adventureRoot) keeps the map screen's sticky HUD. */
  .tableRoot:not(.adventureRoot):not(.phoneMode) > .tableTopRow {
    position: relative;
  }

  .tableRoot:not(.phoneMode) .tableControlsToggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    min-width: 76px;
    min-height: var(--desktop-hud-height, 62px);
    padding: 5px 10px;
    border: 1px solid var(--cmp-gold-deep);
    border-radius: 9px;
    color: var(--cmp-gold-bright);
    background:
      linear-gradient(180deg, rgb(34 25 14 / 96%), rgb(18 13 8 / 98%)),
      var(--cmp-leather) center / 180px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 30%),
      inset 0 1px 0 rgb(246 226 168 / 12%),
      0 6px 18px rgb(0 0 0 / 46%);
    cursor: pointer;
    font-size: 11px;
    font-weight: 800;
  }

  .tableRoot:not(.phoneMode)
    > .tableTopRow
    > .tableMenu.tableMenuInline.controlsOpen {
    position: absolute;
    top: calc(100% + 6px);
    right: 0;
    z-index: 88;
    display: grid;
    width: min(390px, calc(100vw - 28px));
    max-height: calc(100vh - var(--desktop-hud-height) - 28px);
    gap: 6px;
    padding: 8px;
    overflow-y: auto;
    border: 1px solid var(--cmp-gold-deep);
    border-radius: 10px;
    background:
      linear-gradient(180deg, rgb(26 19 11 / 98%), rgb(13 10 7 / 99%)),
      var(--cmp-leather) center / 280px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 24%),
      0 18px 48px rgb(0 0 0 / 72%);
  }

  .tableRoot:not(.phoneMode)
    .tableMenuInline.controlsOpen
    > .tableControlsToggle {
    min-height: 30px;
    justify-self: end;
    width: auto;
  }

  .tableRoot:not(.phoneMode) > .tableTopRow:has(> .tableMenuInline) {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline.controlsOpen .roomBody {
    position: static;
    width: 100%;
    max-width: none;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline > .seatSwitch,
  .tableRoot:not(.phoneMode) .tableMenuInline > .seatLocked {
    flex: 1 1 100%;
    min-height: 27px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .seatSwitch button {
    min-height: 27px;
    padding: 2px 5px;
    font-size: 10px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline > .roomPanel {
    flex: 0 0 auto;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .roomToggle {
    min-height: 28px;
    padding: 3px 7px;
    font-size: 10.5px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .roomToggleMeta {
    font-size: 9.5px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .roomBody {
    position: absolute;
    top: calc(100% + 6px);
    right: 0;
    z-index: 90;
    width: min(560px, calc(100vw - 28px));
    max-height: calc(100vh - 92px);
    overflow-y: auto;
    border-color: var(--cmp-gold-deep);
    background:
      linear-gradient(180deg, rgb(26 19 11 / 98%), rgb(13 10 7 / 99%)),
      var(--cmp-leather) center / 280px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 24%),
      0 18px 48px rgb(0 0 0 / 72%);
  }

  .tableRoot:not(.phoneMode) .tableMenuInline > .statusRow {
    flex: 1 1 auto;
    justify-content: flex-end;
    gap: 4px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline > .statusRow > small {
    white-space: nowrap;
    font-size: 8.5px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .connectionQualityChip {
    padding: 1px 5px;
    font-size: 8px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .musicToggle,
  .tableRoot:not(.phoneMode) .tableMenuInline .uiModeToggle {
    min-height: 26px;
    padding: 2px 6px;
    font-size: 8.5px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .musicToggle svg,
  .tableRoot:not(.phoneMode) .tableMenuInline .uiModeToggle svg {
    width: 14px;
    height: 14px;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline > .gameControlsRow {
    flex: 0 0 auto;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
  }

  .tableRoot:not(.phoneMode)
    .tableMenuInline.controlsOpen
    .gameControlsRow
    > .singlePlayerSavePanel.compact.open {
    flex: 1 0 100%;
  }

  .tableRoot:not(.phoneMode) .tableMenuInline .menuGroupLabel {
    display: none;
  }

  .tableRoot:not(.phoneMode)
    .tableMenuInline
    .gameControlsRow
    > .commandButton {
    min-height: 27px;
    padding: 3px 7px;
    font-size: 10px;
    white-space: nowrap;
  }

  /* The map begins immediately below the top HUD. The right margin is the
     always-visible shared-library rail; no transparent panel covers map
     controls or fields. */
  .adventureRoot:not(.phoneMode) > .adventureMidRow {
    order: 3;
    margin-right: calc(var(--desktop-library-width) + 8px);
    grid-template-columns: 218px minmax(0, 1fr);
    gap: 8px;
  }

  .adventureRoot:not(.phoneMode) > .adventureMidRow > .mapColumn {
    grid-column: 2;
  }

  /* The left rail and the shared library are FIXED, so they float over the
     whole viewport band — not just over the mid row. Every full-width row that
     stays in the flow (today only the rules-error banner — the event log rides
     the command band as a popover and the PvP notice is fixed, both below) has
     to keep out of those two columns, or its first 218px and last 218px sit
     UNDER a rail. Inset it to exactly the map column's gutters so the whole
     page reads as one column of content. A NEW full-width child of
     `.adventureRoot` needs the same inset. */
  .adventureRoot:not(.phoneMode) > .errorBanner {
    margin-right: calc(var(--desktop-library-width) + 8px);
    margin-left: 226px;
  }

  /* PvP preparation notice: lifted out of the flow so readying up never shoves
     the map and the hand down a row. Anchored clear of the sticky command band
     (its height here is the fixed `--desktop-hud-height`) and capped so it never
     runs under the fixed hand tray. z 94 sits above the collapsed controls panel
     (88) and the room manager (90) on purpose — the notice must be answered
     before the fight can start — and stays under the chat dock (200). */
  .adventureRoot:not(.phoneMode) > .preBattlePanel {
    position: fixed;
    top: calc(6px + var(--desktop-hud-height) + 14px);
    left: 50%;
    z-index: 94;
    box-sizing: border-box;
    width: min(560px, calc(100vw - 32px));
    max-height: calc(
      100vh - var(--desktop-hud-height) - var(--desktop-hand-height) - 60px
    );
    overflow: auto;
    transform: translateX(-50%);
    animation: preBattleNoticePop 240ms cubic-bezier(0.2, 0.9, 0.3, 1.2);
  }

  /* Minimized: tuck the title bar into the top-right so the centered board,
     the left town rail and the bottom hand tray are all reachable for
     buying/equipping before the fight. */
  .adventureRoot:not(.phoneMode) > .preBattlePanel.minimized {
    width: max-content;
    max-width: min(420px, calc(100vw - 32px));
    left: auto;
    right: var(--desktop-edge);
    transform: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .adventureRoot:not(.phoneMode) > .preBattlePanel {
      animation: none;
    }
  }

  /* Town / Hero / Army stay in view. Less-used morale/VP panels remain in the
     same scrollable rail rather than lengthening the entire page. */
  .adventureRoot:not(.phoneMode) .leftRail {
    position: fixed;
    top: calc(var(--desktop-hud-height) + 14px);
    bottom: calc(var(--desktop-hand-height) + 14px);
    left: var(--desktop-edge);
    z-index: 36;
    width: 218px;
    max-height: none;
    /* FIT: the rail is a grid whose lone auto track used to be sized by the
       tiles' min-content (portrait + label ≈ 228px) — the track grew PAST the
       218px rail and every tile's right edge was clipped by the scroll box.
       Pin the track to the rail's own width and let tile text shrink. */
    grid-template-columns: minmax(0, 1fr);
    overflow-y: auto;
    padding-right: 4px;
    scrollbar-width: thin;
    overscroll-behavior: contain;
  }

  .adventureRoot:not(.phoneMode) .leftRail > * {
    min-width: 0;
  }

  /* Docked chat sits in the map's true bottom-left corner (the MMO chat spot):
     anchored to the rail's left edge (≈ screen edge) and dropped to the corner
     itself. The collapsed chat button (its default state) sits in the corner;
     an OPEN panel overlaps the hand tray's left deck box (chat is z 200, over
     the tray's 48) — accepted, consistent with the chat-open-takes-priority
     band rule below. Combat screens (no rail) keep the base corner. */
  .adventureRoot:not(.phoneMode) .chatDock {
    left: var(--desktop-edge);
    bottom: 16px;
  }

  /* While a fly-out board (hero / unit deck / commander) is open, lift the
     rail above the other fixed chrome (hand tray 48, library 42, top row 55,
     room manager 90) AND the docked chat (200): an open board is a modal
     interaction with a dimming backdrop, like the opponent dossier (205).
     The rail's resting 36 stays under everything as documented. */
  .adventureRoot:not(.phoneMode) .leftRail:has(.heroDropBackdrop) {
    z-index: 205;
  }

  .adventureRoot:not(.phoneMode) .leftRailDock .townHeroDock {
    gap: 8px;
  }

  .adventureRoot:not(.phoneMode) .leftRailDock .dockTile {
    min-height: 64px;
    gap: 10px;
    padding: 8px 9px;
  }

  .adventureRoot:not(.phoneMode) .leftRailDock .dockTileText strong {
    font-size: 13px;
  }

  .adventureRoot:not(.phoneMode) .leftRailDock .dockTileText small {
    font-size: 9.5px;
  }

  /* THE "shows nothing" FIX: the fly-out board opens OUTSIDE the rail box
     (left: 100% + 12px), and a scroll container clips BOTH axes — rendered
     position:absolute inside the fixed scrolling rail, the whole board sat
     invisible in clipped overflow. position:fixed escapes an ancestor's
     overflow clip (no transformed/filtered ancestor exists on this chain),
     re-anchored to the same spot beside the rail. */
  .adventureRoot:not(.phoneMode) .leftRailDock .heroDrop {
    position: fixed;
    left: calc(var(--desktop-edge) + 218px + 14px);
    top: calc(var(--desktop-hud-height) + 18px);
    max-height: calc(
      100vh - var(--desktop-hud-height) - var(--desktop-hand-height) - 36px
    );
  }

  /* Shared Spells / Abilities / Artifacts / Events / Neutral units are a
     fixed library on the right. Every station is visible or reachable within
     this rail without scrolling away from the current map position. */
  .adventureRoot:not(.phoneMode) > .advDecksBottom {
    position: fixed;
    top: calc(var(--desktop-hud-height) + 22px);
    right: var(--desktop-edge);
    bottom: calc(var(--desktop-hand-height) + 14px);
    z-index: 42;
    width: var(--desktop-library-width);
    margin: 0;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDecks {
    height: 100%;
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: stretch;
    justify-content: flex-start;
    gap: 4px;
    padding: 24px 5px 7px;
    overflow-y: auto;
    scrollbar-width: thin;
    overscroll-behavior: contain;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 22%),
      inset 0 1px 0 rgb(255 235 190 / 7%),
      -8px 8px 24px rgb(0 0 0 / 50%);
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDecks::before {
    content: "Shared library";
    top: 7px;
    left: 10px;
    color: var(--cmp-gold-bright);
    font-size: 9px;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDeckRow {
    flex: 0 0 auto;
    min-height: 52px;
    justify-content: center;
    gap: 4px;
    padding: 3px 2px;
    border: 0;
    border-bottom: 1px solid rgb(217 178 90 / 14%);
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDeckRow:last-child {
    border-bottom: 0;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .cardBack.small,
  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDiscard {
    width: 34px;
    height: 47px;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDeck small,
  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDiscard small {
    max-width: 56px;
    white-space: normal;
    line-height: 1.05;
    text-align: center;
    font-size: 7px;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .advDeckRow.neutral {
    grid-template-columns: repeat(2, 32px);
    justify-content: center;
    width: 100%;
    min-height: 68px;
    gap: 2px;
    padding: 2px 0;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .neutralDeckCell {
    min-width: 0;
    width: 100%;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .neutralDeck {
    width: 32px;
    height: 32px;
    min-width: 0;
    min-height: 0;
    aspect-ratio: 1;
    justify-content: center;
    margin-inline: auto;
    padding: 1px;
    background-size: cover;
    font-size: 10px;
  }

  .adventureRoot:not(.phoneMode) > .advDecksBottom .neutralDeck small {
    font-size: 6.5px;
  }

  /* The player's hand is the bottom command surface, not a large row between
     status and map. It is fixed and one-card tall. Deck/book and any ongoing
     effects sit beside the cards so the tray never grows vertically. */
  .adventureRoot:not(.phoneMode) > .playerCardBar {
    position: fixed;
    left: var(--desktop-edge);
    right: var(--desktop-edge);
    bottom: 6px;
    z-index: 48;
    order: 5;
    height: var(--desktop-hand-height);
    max-height: calc(100vh - 92px);
    gap: 8px;
    padding: 7px 9px;
    border-radius: 12px;
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 30%),
      inset 0 1px 0 rgb(255 235 190 / 8%),
      0 -10px 30px rgb(0 0 0 / 62%);
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckToolsRow {
    gap: 6px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckColumn .ownDeckPile {
    gap: 6px;
    padding: 5px 7px 7px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckColumn .ownDeckBack,
  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckColumn .ownDiscardSpot {
    width: 48px;
    height: 67px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckColumn .ownDeckCount {
    font-size: 15px;
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .ownDeckColumn
    .spellBookToggle {
    padding: 6px 7px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .ownDeckColumn .spellBookIcon {
    width: 48px;
    height: 38px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .handMain {
    display: grid;
    grid-template-columns: minmax(180px, 230px) minmax(0, 1fr);
    gap: 7px;
    margin-left: 0;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .permanentEffectsPanel,
  .adventureRoot:not(.phoneMode) .playerCardBar .handArea {
    min-height: 0;
    height: 100%;
    padding: 5px 7px 7px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .permanentEffectsPanel {
    overflow-y: auto;
    scrollbar-width: thin;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .trayBoxHeader,
  .adventureRoot:not(.phoneMode) .playerCardBar .handTopBar {
    min-height: 25px;
    padding-bottom: 6px;
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .permanentEffectsPanel
    .trayBoxHeader
    strong,
  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handArea
    .handTopBar
    > small:first-child {
    padding: 3px 18px 4px;
    font-size: 9px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .adventureHandCards {
    flex-wrap: nowrap;
    align-items: flex-start;
    justify-content: center;
    gap: 6px;
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .adventureHandCard
    .handCardImage {
    width: clamp(78px, 6.2vw, 94px);
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .permanentEffectsPanel
    .permanentCardImage {
    width: 42px;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .trayFootFrost {
    display: none;
  }

  /* Choice and reaction windows sit above the fixed hand rather than covering
     the cards the player may need to inspect while deciding. */
  .adventureRoot:not(.phoneMode) .promptTray,
  .adventureRoot:not(.phoneMode) .reactionTray {
    bottom: calc(var(--desktop-hand-height) + 20px);
  }

  /* ---- Hand-step banner (mandatory draw / discard / Mulligan) ----------- */
  /* Re-anchored as a fixed HoMM3 scroll banner centered ABOVE the hand tray:
     in the fixed one-card-tall tray the in-flow directives were compressed
     and the hand cards painted OVER the mandatory "Draw new" button (it was
     unclickable — elementFromPoint hit a card image). Out-of-flow, nothing
     can cover it and the tray keeps its single-row height. */
  .adventureRoot:not(.phoneMode) .playerCardBar .handDirectives {
    position: fixed;
    left: 234px;
    top: calc(var(--desktop-hud-height) + 122px);
    bottom: auto;
    transform: none;
    z-index: 60; /* prompt-tray band: above rails/hand, under chat 200+ */
    min-width: 300px;
    max-width: min(390px, calc(100vw - 360px));
    gap: 7px;
    padding: 18px 52px 20px;
    border: none;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  /* The banner plate itself is generated art (banner-command.webp); the
     leather gradient beneath keeps the dialog readable if the art fails. */
  .adventureRoot:not(.phoneMode) .playerCardBar .handDirectives::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: 12px;
    background:
      url("/assets/ui/ornate/banner-command.webp") center / 100% 100% no-repeat,
      linear-gradient(180deg, rgb(44 32 18 / 97%), rgb(24 17 9 / 98%));
    filter: drop-shadow(0 10px 26px rgb(0 0 0 / 60%));
    pointer-events: none;
  }

  /* A mandatory step breathes a soft gold glow so the eye finds it without
     a modal interruption. */
  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handDirectives.mandatory::before {
    animation: handDirectivesGlow 2.8s ease-in-out infinite;
  }

  /* An OPEN chat dock parks in the same bottom-left band (z 200, above the
     banner's 60): slide the banner toward the map's right half so neither
     covers the other. Graceful no-op on browsers without :has (the chat then
     overlaps the banner's left edge exactly as it already overlaps prompt
     trays). */
  .adventureRoot:not(.phoneMode):has(.chatDock.open)
    .playerCardBar
    .handDirectives,
  .adventureRoot:not(.phoneMode):has(.chatDock.open)
    .playerCardBar
    .handArea
    > .handButtons.costPicker,
  .adventureRoot:not(.phoneMode):has(.chatDock.open)
    .playerCardBar
    .handArea
    > .handButtons.playConfirm {
    left: auto;
    right: calc(var(--desktop-library-width) + 40px);
    transform: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .adventureRoot:not(.phoneMode)
      .playerCardBar
      .handDirectives.mandatory::before {
      animation: none;
    }
  }

  /* Optional plays only (morale spends): a quiet slim leather chip strip,
     not the full banner. */
  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handDirectives:not(.mandatory) {
    min-width: 0;
    padding: 9px 20px 11px;
  }

  /* Morale overflow and Ability-token pickers use the same left map-action
     lane as Cover of Darkness and the other hand directives: immediately
     below the floating II–III tile supply. The clear backdrop keeps the map
     readable; engine legal-action gating still makes mandatory choices safe. */
  .adventureRoot:not(.phoneMode) .moraleOverflowBackdrop {
    inset: auto;
    top: calc(var(--desktop-hud-height) + 122px);
    left: 234px;
    width: min(320px, calc(100vw - 360px));
    background: transparent;
    display: block;
    pointer-events: none;
  }

  .adventureRoot:not(.phoneMode) .moraleOverflowPopup {
    box-sizing: border-box;
    width: 100%;
    padding: 14px;
    text-align: left;
    pointer-events: auto;
  }

  .adventureRoot:not(.phoneMode) .moraleOverflowPopup .handButtons {
    justify-content: flex-start;
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handDirectives:not(.mandatory)::before {
    background: linear-gradient(
      180deg,
      rgb(38 28 16 / 96%),
      rgb(22 16 9 / 97%)
    );
    box-shadow: inset 0 0 0 1px rgb(217 178 90 / 40%);
    filter: drop-shadow(0 6px 16px rgb(0 0 0 / 50%));
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handDirectives
    .handDirectivesTitle {
    position: relative;
    padding: 0 26px 10px;
    font-size: 14px;
  }

  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handDirectives
    .handDirectivesTitle::after {
    content: "";
    position: absolute;
    left: -14px;
    right: -14px;
    bottom: 0;
    height: 10px;
    background: var(--orn-rail) center bottom / 100% 10px no-repeat;
    opacity: 0.85;
    filter: drop-shadow(0 1px 2px rgb(0 0 0 / 55%));
    pointer-events: none;
  }

  .adventureRoot:not(.phoneMode) .playerCardBar .handDirectives .handWarning,
  .adventureRoot:not(.phoneMode) .playerCardBar .handDirectives .handHint {
    font-size: 12.5px;
    line-height: 1.45;
  }

  /* The cost-picker ("pick cards to discard") and play-confirm rows are the
     same class of victim: in-flow rows in the fixed-height tray push the
     cards out of the box. Float them in the same banner spot — the hand
     cards below stay visible and clickable for the pick. */
  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handArea
    > .handButtons.costPicker,
  .adventureRoot:not(.phoneMode)
    .playerCardBar
    .handArea
    > .handButtons.playConfirm {
    position: fixed;
    left: 50%;
    bottom: calc(var(--desktop-hand-height) + 16px);
    transform: translateX(-50%);
    z-index: 60;
    justify-content: center;
    max-width: min(780px, calc(100vw - 480px));
    padding: 12px 26px;
    border-radius: 10px;
    background: linear-gradient(
      180deg,
      rgb(38 28 16 / 96%),
      rgb(22 16 9 / 97%)
    );
    box-shadow:
      inset 0 0 0 1px rgb(217 178 90 / 40%),
      0 8px 20px rgb(0 0 0 / 55%);
  }

  /* The chat dock is intentionally NOT in this group: it owns its own corner
     anchor (bottom-left, just above the hand tray) in the .chatDock rule above.
     These three affordances stay lifted a little higher, above the hand tray. */
  .adventureRoot:not(.phoneMode) .helperCoachChip,
  .adventureRoot:not(.phoneMode) .tableReactionBar,
  .adventureRoot:not(.phoneMode) .reactionStrip {
    bottom: calc(var(--desktop-hand-height) + 16px);
  }
}

/* ======================================================================== */
/* PHONE UI MODE                                                            */
/*                                                                          */
/* Everything below only applies inside `main.phoneMode` (plus the mode     */
/* prompt / toggle / tab-bar components themselves, which only exist        */
/* because of this feature). The class is added exclusively when the        */
/* per-browser "binh-ui-mode" preference is "phone" (see                    */
/* src/lib/ui-mode-preference.ts) — in Computer mode not one rule in this   */
/* section can match, which is the "never affect the desktop layout"       */
/* guarantee. The phone layout shows ONE full-screen panel at a time,       */
/* picked by `data-phone-tab` on the same DOM the desktop lays out side by  */
/* side; fixed overlays (prompts, dice, chat, feed) stay visible on every   */
/* tab.                                                                     */
/* ======================================================================== */

/* ---------- the pre-game mode prompt (renders in BOTH modes) ---------- */

.uiModeBackdrop {
  position: fixed;
  inset: 0;
  /* Above the helper-coach prompt (1250) — the mode question comes first. */
  z-index: 1300;
  display: grid;
  place-items: center;
  padding: 16px;
  background: radial-gradient(
    circle at 50% 28%,
    rgba(0, 0, 0, 0.5),
    rgba(0, 0, 0, 0.84)
  );
  animation: welcomeFade 0.2s ease;
}

.uiModeCard {
  display: grid;
  gap: 10px;
  width: 100%;
  max-width: 560px;
  max-height: 92dvh;
  overflow-y: auto;
  padding: 18px 20px 14px;
  border-radius: 16px;
  color: #ecd9b0;
  background:
    radial-gradient(
      circle at 12% 6%,
      rgba(255, 214, 120, 0.1),
      transparent 42%
    ),
    linear-gradient(160deg, #2c2013 0%, #1c140b 60%, #120d07 100%);
  border: 1px solid rgba(220, 175, 95, 0.55);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.6);
}

.uiModeEyebrow {
  color: #c9a35c;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.uiModeTitle {
  margin: 0;
  color: #ffe9bd;
  font-size: 20px;
}

.uiModeLede {
  margin: 0;
  color: #d8c49a;
  font-size: 13px;
  line-height: 1.5;
}

.uiModeOptions {
  display: grid;
  gap: 8px;
}

.uiModeOption {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 12px 12px 14px;
  border: 1px solid rgba(220, 175, 95, 0.4);
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.28);
  color: #ecd9b0;
  cursor: pointer;
  text-align: left;
  touch-action: manipulation;
}

.uiModeOption:hover,
.uiModeOption:focus-visible {
  border-color: rgba(255, 215, 118, 0.85);
  background: rgba(213, 168, 79, 0.12);
}

.uiModeOption.recommended {
  border-color: rgba(255, 215, 118, 0.9);
  box-shadow:
    0 0 0 1px rgba(255, 215, 118, 0.35),
    0 0 18px rgba(213, 168, 79, 0.25);
}

.uiModeOptionIcon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  border-radius: 10px;
  border: 1px solid rgba(220, 175, 95, 0.45);
  background: rgba(213, 168, 79, 0.12);
  color: #ffd76a;
}

.uiModeOptionText {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.uiModeOptionText strong {
  color: #ffe9bd;
  font-size: 14px;
}

.uiModeOptionText small {
  color: #c7b088;
  font-size: 11.5px;
  line-height: 1.4;
}

.uiModeRecommended {
  position: absolute;
  top: -9px;
  right: 10px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid rgba(255, 215, 118, 0.8);
  background: #2c2013;
  color: #ffd76a;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.uiModeFoot {
  color: #a68d63;
  font-size: 11px;
}

/* The table-menu 📱/💻 switch — matches the MusicToggle button family. */
.uiModeToggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--muted);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
  touch-action: manipulation;
}

.uiModeToggle.phone {
  border-color: var(--gold);
  color: var(--gold);
}

/* ---------- bottom tab bar ---------- */

.phoneTabBar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 90;
  display: flex;
  align-items: stretch;
  gap: 2px;
  padding: 4px max(6px, env(safe-area-inset-right, 0px))
    calc(4px + env(safe-area-inset-bottom, 0px))
    max(6px, env(safe-area-inset-left, 0px));
  border-top: 1px solid rgba(213, 168, 79, 0.4);
  background: rgba(16, 13, 9, 0.97);
  backdrop-filter: blur(8px);
}

.phoneTab {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 52px;
  min-width: 0;
  padding: 6px 2px 4px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #b89f78;
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  touch-action: manipulation;
}

.phoneTab.active {
  background: rgba(213, 168, 79, 0.16);
  color: #ffd76a;
}

.phoneTab.action {
  flex: 1.25;
  border: 1px solid rgba(255, 215, 106, 0.78);
  background: linear-gradient(
    180deg,
    rgba(139, 91, 17, 0.96),
    rgba(88, 48, 10, 0.98)
  );
  color: #fff0b8;
  box-shadow:
    inset 0 1px 0 rgba(255, 244, 196, 0.28),
    0 0 12px rgba(255, 190, 65, 0.2);
}

.phoneTab.action:active {
  transform: translateY(1px);
  filter: brightness(1.12);
}

.phoneTabIcon {
  display: inline-flex;
}

.phoneTabLabel {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.phoneTabBadge {
  position: absolute;
  top: 2px;
  left: calc(50% + 6px);
  min-width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--gold);
  color: var(--ink);
  font-size: 10px;
  font-weight: 800;
}

.phoneTabAttention {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  padding: 1px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255, 130, 110, 0.8);
  background: #8c1f1f;
  color: #ffe4dc;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.phoneTab.attention .phoneTabIcon {
  color: #ffd76a;
  animation: phoneTabPulse 1.1s ease-in-out infinite;
}

@keyframes phoneTabPulse {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-3px) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  .phoneTab.attention .phoneTabIcon {
    animation: none;
  }
}

/* ---------- global chrome: reclaim vertical space ---------- */

/* Collapse the site header/footer while a phone-mode table is on screen.
   `:has` is supported by every current mobile browser; without it the header
   simply stays — nothing breaks. */
.appShell:has(main.phoneMode) .topBar,
.appShell:has(main.phoneMode) .footerNotice {
  display: none;
}

/* (The desktop twin of the rule above — hiding the masthead for a live
   `.tableMenuInline` table at ≥1101px — lives in the DESKTOP COMMAND HUD
   section, so every selector in THIS block stays `.phoneMode`-prefixed.) */

/* ---------- shared phone shell (all table branches) ---------- */

.phoneMode {
  padding: 6px 6px calc(74px + env(safe-area-inset-bottom, 0px));
  gap: 6px;
}

/* Faster taps: game buttons never need double-tap-to-zoom. */
.phoneMode button {
  touch-action: manipulation;
}

/* One column up top — the table menu leaves the top row (it becomes the
   "Menu" tab's panel below). */
.phoneMode .tableTopRow {
  grid-template-columns: minmax(0, 1fr);
}

/* Region visibility: hidden by default in a tabbed surface, re-shown by the
   active tab below. Mains WITHOUT data-phone-tab (setup lobby / Battle-Test
   setup) keep everything visible — they are single scrolling columns. */
.phoneMode[data-phone-tab] .tableMenu,
.phoneMode[data-phone-tab] .playerCardBar,
.phoneMode[data-phone-tab] .advDecksBottom,
.phoneMode[data-phone-tab] .leftRail,
.phoneMode[data-phone-tab] .combatCardStrip {
  display: none;
}

.phoneMode[data-phone-tab="menu"] .tableMenu {
  display: grid;
}

.phoneMode .tableControlsToggle {
  display: none;
}

/* ---------- adventure surface ---------- */

/* Flex column so the map tab can hand ALL leftover height to the map. The
   `order` rules written for the desktop grid apply identically to flex. */
.phoneMode.adventureRoot {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
}

/* The HUD ribbon stays pinned while panels scroll under it… */
.phoneMode.adventureRoot > .tableTopRow {
  position: sticky;
  top: 0;
  z-index: 45;
  background: rgba(13, 15, 16, 0.96);
  border-radius: 0 0 10px 10px;
}

/* …except on the Menu tab, whose (tall) panel lives inside the same row and
   must be free to scroll with the page. */
.phoneMode.adventureRoot[data-phone-tab="menu"] > .tableTopRow {
  position: static;
  background: transparent;
}

/* Compact one-line HUD: swipe sideways instead of wrapping into a tall block. */
.phoneMode .advHud {
  flex-wrap: nowrap;
  overflow-x: auto;
  min-height: 46px;
  gap: 10px;
  padding: 6px 10px;
  scrollbar-width: thin;
}

.phoneMode .advHud .advHudCell {
  flex: 0 0 auto;
  white-space: nowrap;
}

.phoneMode .advHudButtons {
  flex: 0 0 auto;
}

.phoneMode.adventureRoot > .adventureMidRow {
  grid-template-columns: minmax(0, 1fr);
  flex: 1 1 auto;
  min-height: 0;
}

/* Map tab: the hex map takes every leftover pixel between HUD and tab bar. */
.phoneMode .mapColumn {
  min-height: 0;
}

.phoneMode .hexMapWrap {
  min-height: min(52vh, 520px);
}

.phoneMode.adventureRoot[data-phone-tab="map"] .hexMapWrap {
  min-height: calc(100vh - 210px);
  min-height: calc(100dvh - 210px);
}

/* Army tab shows the command rail full-width in place of the map. */
.phoneMode.adventureRoot[data-phone-tab="hand"] .adventureMidRow,
.phoneMode.adventureRoot[data-phone-tab="decks"] .adventureMidRow,
.phoneMode.adventureRoot[data-phone-tab="menu"] .adventureMidRow {
  display: none;
}

.phoneMode.adventureRoot[data-phone-tab="army"] .leftRail {
  display: grid;
}

.phoneMode.adventureRoot[data-phone-tab="army"] .mapColumn {
  display: none;
}

/* The rail's fly-out boards (hero, army, town) open to the RIGHT on desktop —
   off-screen on a full-width phone panel. Re-anchor them as a fixed sheet. */
.phoneMode .leftRailDock .heroDrop {
  position: fixed;
  left: 8px;
  right: 8px;
  top: 64px;
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  width: auto;
  max-height: none;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
  /* Keep the sheet above its z-index:79 dismiss backdrop. */
  z-index: 80;
}

/* The unit roster is longer than the hero/town sheets. Keep one scrolling
   owner (the fixed sheet) and enough tail padding that the last card clears the
   phone tab bar and safe area instead of becoming an unreachable rubber-band. */
.phoneMode .leftRailDock .heroDrop.unitDrop {
  box-sizing: border-box;
  padding-bottom: 24px;
}

.phoneMode .leftRailDock .heroDrop.unitDrop .armyPanel,
.phoneMode .leftRailDock .heroDrop.unitDrop .armyPanel ul {
  min-height: min-content;
  overflow: visible;
}

.phoneMode .objectiveBackdrop {
  align-items: flex-end;
  padding: 8px 8px calc(72px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .objectiveModal {
  width: 100%;
  max-height: calc(100dvh - 92px - env(safe-area-inset-bottom, 0px));
  padding: 14px;
  border-radius: 14px 14px 8px 8px;
}

.phoneMode.adventureRoot[data-phone-tab="hand"] .playerCardBar {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
}

.phoneMode .playerCardBar .ownDeckColumn {
  align-self: center;
}

.phoneMode .adventureHandCards {
  justify-content: center;
}

.phoneMode.adventureRoot[data-phone-tab="decks"] .advDecksBottom {
  display: block;
}

/* Keep the collapsed game-log bar at the bottom, under the shown panel (it
   defaults to order 0, which would put it ABOVE the sticky HUD in a column). */
.phoneMode.adventureRoot > .logDrawer {
  order: 6;
}

/* ---------- combat surface ---------- */

.phoneMode[data-phone-tab="hand"] .combatCardStrip {
  display: grid;
}

.phoneMode[data-phone-tab="hand"] .tableMidRow,
.phoneMode[data-phone-tab="menu"] .tableMidRow {
  display: none;
}

/* Board tab: one column — initiative rail, board, then commands / effects /
   inspector / placement stacked beneath (scroll for the tail). */
.phoneMode .tableMidRow,
.phoneMode .tableMidRow.withPlacement {
  grid-template-columns: minmax(0, 1fr);
}

/* Fit the 5:4 battlefield to BOTH axes: full width portrait, height-capped in
   landscape so the board never pushes the commands off screen. */
.phoneMode .battlefieldFrame {
  max-width: min(100%, calc((100vh - 168px) * 1.25));
  max-width: min(100%, calc((100dvh - 168px) * 1.25));
  margin: 0 auto;
  width: 100%;
}

.phoneMode .initiativeRail {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}

.phoneMode .initiativeRail .initChip {
  flex: 0 0 auto;
}

/* The right rail stacks under the board; commands first — they are the
   actions of the current activation. */
.phoneMode .rightRail > .commandDock {
  order: -1;
}

/* Hand tab: the seat row stacks instead of docking side by side, and the card
   fan becomes a wrapping grid (no negative-margin overlap — every card must
   be individually tappable). */
.phoneMode .tableSeatRow {
  grid-template-columns: minmax(0, 1fr);
  min-height: 0;
  align-items: start;
}

.phoneMode .handFan {
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  min-height: 0;
  padding: 10px 6px;
}

.phoneMode .fanCard {
  margin-right: 0;
}

.phoneMode .fanCard:hover,
.phoneMode .fanCard:focus-visible,
.phoneMode .fanSlot.open .fanCard {
  transform: translateY(-10px) scale(1.18);
}

/* ---------- fixed overlays: clear the tab bar, fit the width ---------- */

.phoneMode .promptTray {
  left: 8px;
  right: 8px;
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  transform: none;
  min-width: 0;
  max-width: none;
  max-height: 58vh;
  max-height: 58dvh;
  overflow-y: auto;
}

/* Phone: stronger tile-rotation halo so the active tile is obvious under the
   smaller map, and a dashed ring that blinks a little harder. */
.phoneMode .rotatingHalo {
  stroke: rgba(255, 215, 106, 0.72);
  stroke-width: 3.2;
  animation: rotatingPulsePhone 1.1s ease-in-out infinite;
}

.phoneMode .hexCell.rotating {
  animation: rotatingPulsePhone 1.1s ease-in-out infinite;
}

@keyframes rotatingPulsePhone {
  0%,
  100% {
    filter: brightness(1);
    stroke-opacity: 0.55;
  }
  50% {
    filter: brightness(1.55);
    stroke-opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .phoneMode .rotatingHalo,
  .phoneMode .hexCell.rotating {
    animation: none;
    filter: brightness(1.25);
  }
}

/* Tile-rotate float sits on the map anchor; on a phone that often covers the
   very tile you are lining up. Nudge it further away from the tile center
   (above → higher; below → lower) so the flower stays readable, and give the
   control a slightly larger touch target. */
.phoneMode .mapFloatOuter:has(.rotateFloat).above {
  transform: translateY(-52px);
}

.phoneMode .mapFloatOuter:has(.rotateFloat).below {
  transform: translateY(48px);
}

.phoneMode .mapFloatOuter:has(.rotateFloat) {
  width: min(300px, calc(100vw - 16px)) !important;
}

.phoneMode .mapFloatCard.rotateFloat {
  padding: 10px 12px;
  font-size: 13px;
  animation: rotateFloatPulsePhone 1.2s ease-in-out infinite;
}

@keyframes rotateFloatPulsePhone {
  0%,
  100% {
    box-shadow:
      0 6px 18px rgba(0, 0, 0, 0.55),
      0 0 0 0 rgba(255, 215, 106, 0.2);
    border-color: rgba(255, 215, 106, 0.75);
  }
  50% {
    box-shadow:
      0 6px 18px rgba(0, 0, 0, 0.55),
      0 0 22px 3px rgba(255, 215, 106, 0.55);
    border-color: rgba(255, 230, 140, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .phoneMode .mapFloatCard.rotateFloat {
    animation: none;
  }
}

.phoneMode .reactionTray {
  left: 8px;
  right: 8px;
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  transform: translate(var(--reaction-tray-x, 0px), var(--reaction-tray-y, 0px));
  min-width: 0;
  max-width: none;
  width: auto;
  max-height: 58vh;
  max-height: 58dvh;
  overflow-y: auto;
}

.phoneMode .chatDock {
  left: 8px;
  bottom: calc(76px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .adventureFeed {
  top: 58px;
  right: 8px;
  max-width: min(300px, 62vw);
}

.phoneMode .afkVotePanel {
  left: 8px;
  right: 8px;
  width: auto;
}

/* Deep windows (town, morale panels, market…) already use viewport-relative
   maxima; give the big town window the full phone width. */
.phoneMode .townWindow {
  width: min(1180px, 98vw);
  max-height: 92vh;
  max-height: 92dvh;
}

/* The Search / Reroll / Learning card sits in the centered `.modalBackdrop`,
   whose bottom is painted over by the fixed tab bar (z-index 90, rendered after
   the modal). A plain 92dvh card would center with only ~4dvh of clearance, so
   its last row (a Search(4)/(5) wraps several) hid behind the bar. Anchor the
   card just above the bar instead — the same `72px + safe-area` every other
   bottom floater clears it by — and cap its height so the top stays on-screen;
   its body then scrolls (overflow-y from `.searchModal`) so every option is
   reachable clear of the bar. `:has(> .searchModal)` scopes this to exactly the
   three search-family cards and no other `.modalBackdrop` (town, hero, VP…). */
.phoneMode .modalBackdrop:has(> .searchModal) {
  align-items: end;
  padding-bottom: calc(72px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .searchModal {
  max-height: calc(100dvh - 88px - env(safe-area-inset-bottom, 0px));
}

/* Commander level-up popup on phone. It PORTALS to <body> (outside <main>), so
   it takes the body:has(main.phoneMode) form — same :has() dependency as the
   Setup-Hub windows below (graceful no-op on old browsers). It paints ABOVE the
   tab bar (z 236 vs 90), so it does not need the search modal's bar clearance;
   what it does need is the phone's real visual viewport (dvh) plus the bottom
   safe-area inset, or the "Spend later" button and the last stat option sit off
   the bottom edge with nothing to scroll. */
body:has(main.phoneMode) .commanderLevelUpBackdrop {
  padding: 10px max(10px, env(safe-area-inset-right, 0px))
    calc(10px + env(safe-area-inset-bottom, 0px))
    max(10px, env(safe-area-inset-left, 0px));
}

body:has(main.phoneMode) .commanderLevelUpModal {
  width: min(440px, 100%);
  max-height: calc(100vh - 20px);
  max-height: calc(100dvh - 20px - env(safe-area-inset-bottom, 0px));
}

body:has(main.phoneMode) .commanderLevelUpFace {
  width: min(150px, 42%);
}

/* The setup lobby mounts its own helper-coach prompt INSIDE .setupLobby, whose
   `z-index: 1` stacking context traps the prompt's fullscreen backdrop below
   the chat dock (z-index 200) — on a phone the dock then swallows the
   dialog's taps. While that prompt is open in phone mode, lift the lobby
   above the dock; the fullscreen backdrop covers everything anyway. */
.phoneMode .setupLobby:has(.helperCoachBackdrop) {
  z-index: 210;
}

/* The floating "Skip animation" control docks bottom-right on desktop — on a
   phone that is exactly where the tab bar lives (z 10020 swallows tab taps).
   Ride it just above the bar instead. */
.phoneMode .presentationSkip {
  right: 8px;
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
}

/* Every other bottom-anchored floater must clear the fixed tab bar too —
   anything left at bottom:~16px sits exactly on the tabs and swallows their
   taps (the coach chip and emote bar did). One consolidated lift. */
.phoneMode .helperCoachChip,
.phoneMode .tableReactionBar,
.phoneMode .reactionStrip {
  bottom: calc(72px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .tableReactionOverlay {
  bottom: calc(130px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .marketPanel {
  bottom: calc(128px + env(safe-area-inset-bottom, 0px));
}

.phoneMode .marketChip,
.phoneMode .marketTab {
  bottom: calc(144px + env(safe-area-inset-bottom, 0px));
}

/* ---------- less scrolling + scroll containment (performance) ---------- */

/* Rubber-banding a scrollable phone panel must NOT drag the whole page (and its
   fixed tab bar) with it: `overscroll-behavior: contain` keeps the scroll chain
   inside each panel, which also lets the browser skip the costly root-scroll
   bounce. Applied to every phone scroll surface (the sideways HUD/initiative
   ribbons, the fixed prompt/reaction trays, the big town window, and the
   Decks/Army panels capped below). */
.phoneMode .advHud,
.phoneMode .initiativeRail,
.phoneMode .promptTray,
.phoneMode .reactionTray,
.phoneMode .searchModal,
.phoneMode .townWindow,
.phoneMode .marketPanel,
.phoneMode.adventureRoot[data-phone-tab="decks"] .advDecksBottom,
.phoneMode.adventureRoot[data-phone-tab="army"] .leftRail,
.phoneMode .rightRail > .commandDock {
  overscroll-behavior: contain;
}

/* Decks tab: the shared-deck shelf is a tall block that used to grow the page
   past the tab bar (long slide to reach the bottom decks). Cap it to the panel
   height and scroll WITHIN itself instead. */
.phoneMode.adventureRoot[data-phone-tab="decks"] .advDecksBottom {
  max-height: calc(100dvh - 150px);
  overflow-y: auto;
}

/* Army tab: the left command rail (town/hero/unit deck + opponent info +
   morale) scrolls inside the panel, keeping its primary buttons above the fold
   rather than pushing the page taller than the screen. */
.phoneMode.adventureRoot[data-phone-tab="army"] .leftRail {
  max-height: calc(100dvh - 120px);
  overflow-y: auto;
}

/* Combat Board tab: the battlefield is height-capped (below), so the command
   dock — the CURRENT activation's actions — must be reachable right under it.
   Cap the dock and let ITS list scroll, so the first (most-used) actions always
   sit on-screen without a long page slide past the board. */
.phoneMode .rightRail > .commandDock {
  max-height: 42dvh;
  overflow-y: auto;
}

/* Tighter hand grids: the generous 10px gaps meant fewer cards per screen and
   more vertical hunting. 6px keeps every card individually tappable while
   fitting more into view. */
.phoneMode .handFan {
  gap: 6px;
  padding: 8px 4px;
}

.phoneMode .adventureHandCards {
  gap: 6px;
}

/* The permanents/ongoing tray above the hand rarely has content on a phone;
   drop its min-height so it does not reserve a dead band above the cards. */
.phoneMode .playerCardBar .permanentEffectsPanel {
  min-height: 0;
}

/* Landscape phones have ~220px of height for the whole battlefield frame —
   the decorative scenery band alone eats ~100px of it. Drop the band and cap
   the frame so the full 5×4 grid fits between the HUD and the tab bar without
   scrolling; portrait keeps the full art. */
@media (orientation: landscape) {
  .phoneMode .battlefieldScenery {
    display: none;
  }

  .phoneMode .battlefieldFrame {
    max-width: min(100%, calc((100dvh - 190px) * 1.25));
  }
}

/* Ornate skin III (kit v2): the 19px frame-ornate layout border would eat a
   narrow phone room panel's width, so fall back to a plain gold hairline in
   phone mode. Scoped to `.tableRoot` so the same fall-back covers the battle
   screen's room panel too (its frame now comes from §3). The tray columns are
   already display:none below 1100px, and the section rails / title plaque are
   small enough to keep. */
.phoneMode.tableRoot > .tableTopRow > .tableMenu {
  border: 1px solid var(--cmp-gold-deep);
  border-image: none;
  border-radius: 9px;
  padding: 8px;
}

/* Battle-screen skin III fall-backs: the 18px / 13px gem frames would eat a
   narrow phone battlefield / deploy sidebar, so drop them to a plain gold
   hairline. The ORDER plaque and opponent-leather touches are small enough to
   keep (they add no width). Mirrors the map step's .tableMenu hairline above. */
.phoneMode .battlefieldFrame {
  border: 2px solid var(--cmp-gold-deep);
  border-image: none;
  border-radius: 8px;
}

.phoneMode .battlefieldFrame::after {
  display: none;
}

.phoneMode .placementPanel {
  border: 1px solid var(--cmp-gold-deep);
  border-image: none;
  border-radius: 10px;
  padding: 12px;
}

/* Town-window skin III fall-back: the 26px gem frame would eat the narrow
   phone window's width, so drop it to a plain gold hairline — exactly like
   the .tableMenu / .battlefieldFrame fall-backs above. The header banding,
   gold tabs and Buildings-tab leather add no width and are kept. */
.phoneMode .townWindow {
  border: 1px solid var(--cmp-gold-deep);
  border-image: none;
  border-radius: 12px;
}

/* Setup Hub on phone: the 2×2 boxes shrink to fit, and the hub popup windows
   become full-screen sheets. The windows PORTAL to <body> (outside <main>),
   so they take the body:has(main.phoneMode) form — same :has() dependency as
   the header/footer collapse (graceful no-op on old browsers). */
.phoneMode .setupHubGrid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.phoneMode .setupHubBoxPlate {
  gap: 2px;
  padding: 6px 8px 8px;
}

.phoneMode .setupHubBoxTitle {
  font-size: 14px;
}

.phoneMode .setupHubBoxSummary {
  font-size: 11px;
}

.phoneMode .setupHubBoxDim {
  font-size: 10px;
}

/* The collapsed chat pill floats over the bottom-left corner; leave room so the
   last row of boxes and the Start button can always scroll clear of it. */
.phoneMode .setupLobby {
  padding-bottom: calc(76px + env(safe-area-inset-bottom));
}

/* Phone: show the STATIC painted still, not the looping video — lighter, and
   free of the object-fit: fill squash the desktop plate uses. */
.phoneMode .setupSceneVideo {
  display: none;
}

/* Phone: scale that still to its own aspect ratio (letterboxed on the dark
   ground) instead of covering/stretching the whole screen — it need not fill.
   Higher specificity + !important so it beats the narrow-width `cover` and the
   desktop `100% 100%` rules, which are themselves !important. Only size and
   position change; the image and #050403 fill come from those base rules. */
.phoneMode.setupPhase .setupSceneIllustration {
  background-size: contain !important;
  background-position: center !important;
}

body:has(main.phoneMode) .setupHubBackdrop {
  padding: 0;
}

body:has(main.phoneMode) .setupHubWindow {
  width: 100vw;
  height: 100dvh;
  max-height: none;
  border-radius: 0;
  border-left: none;
  border-right: none;
}

body:has(main.phoneMode) .setupHubWindowBody {
  padding-bottom: calc(16px + env(safe-area-inset-bottom));
}

body:has(main.phoneMode) .setupHubWindowContent {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* On a full-screen sheet the close button leads the header (the mobile-sheet
   idiom), which also keeps it clear of anything pinned to the top-right corner
   — in dev, the Next dev-tools badge sits exactly there. */
body:has(main.phoneMode) .setupHubWindowHead {
  justify-content: flex-start;
  gap: 10px;
}

body:has(main.phoneMode) .setupHubWindowClose {
  order: -1;
}

/* One column: the shape preview + info stack UNDER the map list. The list keeps
   its own scroll (a big library would otherwise make the sheet miles long, and
   a `min-height: 0` here would let the flex column shrink the grid while the
   list spilled over the difficulty bar). */
body:has(main.phoneMode) .mapPickLayout {
  grid-template-columns: 1fr;
  /* Never shrink: the sheet body scrolls instead, so the stacked preview + info
     can't be squeezed into (and painted over) the difficulty bar below. */
  flex: none;
}

/* A min-height as well as a max: the list is a scroll container, so without one
   the flex column above would squeeze it to a couple of rows and scroll the
   whole sheet instead. */
body:has(main.phoneMode) .mapPickList {
  min-height: 30vh;
  max-height: 38vh;
}

body:has(main.phoneMode) .mapPickDetail {
  max-height: none;
  overflow: visible;
}

/* On the phone sheet the whole body scrolls (the detail column doesn't), so
   pin the apply bar to the scrollport bottom while the detail is in view —
   "Play this map" stays reachable without hunting below the conditions list. */
body:has(main.phoneMode) .mapPickDetailScroll {
  overflow-y: visible;
  flex: none;
}

body:has(main.phoneMode) .mapPickApplyBar {
  position: sticky;
  bottom: 0;
  z-index: 2;
  border: 1px solid rgba(170, 130, 70, 0.4);
  border-radius: 10px;
}

body:has(main.phoneMode) .difficultyChessBtn {
  padding: 12px 6px 10px;
}

/* Unit-deck / recruit card faces are big on desktop (legible stat + resource
   icons); on the narrow phone Army tab and town window that pair would overflow,
   so scale them down while KEEPING the true 743:1040 aspect (no squash). The
   cost/label typography rides the desktop sizes — still readable at this scale. */
.phoneMode .unitSideCard {
  min-width: 78px;
}
.phoneMode .unitSideCard .recruitThumbImg {
  width: 78px;
  height: 109px;
}

/* Anime/Wuxia boards use seven real slices from ONE fully-built panorama. The
   slice lives on the whole bar; transparent per-building hit regions preserve
   the two-building shared-slot rules without breaking the continuous artwork. */
.tbBarTileArt {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.tbDesignedTile.barArt {
  z-index: 1;
  background: transparent;
}

.tbDesignedTile.barArt.compact {
  background: rgb(0 0 0 / 4%);
}

/* Compatibility action mirror for older integrations/tests; the visible and
   discoverable grade UI is the full hero-system tree window above. */
.hbGradePickerLegacy {
  display: none;
}

/* ========================================================================== */
/* Mod system windows: classic leather, anime astral glass, wuxia jade paper. */
/* ========================================================================== */

.theme-classic {
  --mod-accent: #e4bd68;
  --mod-accent-2: #a5612d;
  --mod-accent-soft: rgb(228 189 104 / 20%);
  --mod-panel: #24180d;
  --mod-panel-2: #100c08;
  --mod-line: rgb(228 189 104 / 38%);
  --mod-art: url("/assets/ui/mod-system-classic.webp");
  --mod-heading: Georgia, "Times New Roman", serif;
  --mod-corner: 3px;
}

.theme-anime {
  --mod-accent: #75d8ff;
  --mod-accent-2: #f16fa1;
  --mod-accent-soft: rgb(95 195 255 / 18%);
  --mod-panel: #121b38;
  --mod-panel-2: #090c20;
  --mod-line: rgb(103 205 255 / 42%);
  --mod-art: url("/assets/anime/ui/mod-system-anime.webp");
  --mod-heading: "Trebuchet MS", system-ui, sans-serif;
  --mod-corner: 15px;
}

.theme-wuxia {
  --mod-accent: #86dfc0;
  --mod-accent-2: #e3c679;
  --mod-accent-soft: rgb(103 198 164 / 18%);
  --mod-panel: #102d2d;
  --mod-panel-2: #081817;
  --mod-line: rgb(123 216 184 / 38%);
  --mod-art: url("/assets/anime/ui/mod-system-wuxia.webp");
  --mod-heading: Georgia, "Noto Serif", serif;
  --mod-corner: 24px;
}

.theme-anime .hb {
  background:
    radial-gradient(circle at 85% 4%, rgb(241 87 145 / 20%), transparent 30%),
    linear-gradient(145deg, #111b42, #100d26 60%, #251127);
}

.theme-wuxia .hb {
  background:
    radial-gradient(circle at 12% 0%, rgb(140 224 192 / 15%), transparent 36%),
    linear-gradient(145deg, #102c2c, #0c1b1a 63%, #173323);
}

.theme-anime .dockTile {
  background: linear-gradient(135deg, rgb(20 32 73 / 97%), rgb(28 15 46 / 98%));
  border-color: rgb(108 192 255 / 35%);
}

.theme-wuxia .dockTile {
  background: linear-gradient(135deg, rgb(18 53 48 / 97%), rgb(10 27 25 / 98%));
  border-color: rgb(124 215 181 / 35%);
}

.heroSystemButtons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2cqw;
  margin: 0.4cqw 0.8cqw 0;
}

.hb button.heroSystemButton {
  display: flex;
  align-items: center;
  gap: 1.2cqw;
  min-height: 7.5cqw;
  padding: 1.2cqw 1.6cqw;
  border: 0.22cqw solid var(--mod-line);
  border-radius: 1.1cqw;
  background: linear-gradient(145deg, var(--mod-accent-soft), rgb(0 0 0 / 28%));
  box-shadow:
    inset 0 0.2cqw 0 rgb(255 255 255 / 10%),
    0 0.6cqw 1.2cqw rgb(0 0 0 / 28%);
  cursor: pointer;
  color: var(--mod-accent);
}

.heroSystemButton > svg {
  flex: none;
  filter: drop-shadow(0 0 0.8cqw var(--mod-accent-soft));
}

.heroSystemButton > span {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.heroSystemButton strong {
  color: #fff1cf;
  font-family: Georgia, serif;
  font-size: 2.8cqw;
  line-height: 1.15;
}

.heroSystemButton small {
  color: #bea984;
  font-size: 2.05cqw;
}

.heroSystemButton:hover,
.heroSystemButton:focus-visible {
  border-color: var(--mod-accent);
  transform: translateY(-1px);
  outline: none;
}

.heroSystemButton.attention {
  animation: modSystemPulse 1.8s ease-in-out infinite;
}

/* Focused discard/payment window. Combat costs used to expand into a long row
   of text buttons above the battlefield; card faces now carry the decision. */
.costPlayBackdrop {
  position: fixed;
  inset: 0;
  z-index: 238;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgb(2 5 11 / 78%);
  backdrop-filter: blur(7px);
}

.costPlayWindow {
  width: min(820px, 96vw);
  max-height: min(760px, 92dvh);
  overflow: auto;
  border: 1px solid rgb(207 170 91 / 64%);
  border-radius: 18px;
  color: #eee4cf;
  background:
    radial-gradient(circle at 18% 0%, rgb(74 112 150 / 22%), transparent 38%),
    linear-gradient(155deg, #18202b, #090c12 72%);
  box-shadow:
    0 30px 90px rgb(0 0 0 / 78%),
    inset 0 0 0 1px rgb(255 255 255 / 5%);
}

.costPlayHeader {
  display: grid;
  grid-template-columns: 48px 1fr 38px;
  gap: 13px;
  align-items: center;
  padding: 18px 20px;
  border-bottom: 1px solid rgb(207 170 91 / 25%);
}
.costPlayGlyph {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgb(207 170 91 / 55%);
  border-radius: 13px;
  color: #f1cc75;
  background: rgb(128 88 30 / 18%);
}
.costPlayHeader small {
  color: #c7a966;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}
.costPlayHeader h2 {
  margin: 2px 0 0;
  color: #fff1cf;
  font:
    700 24px/1.1 Georgia,
    serif;
}
.costPlayClose {
  width: 36px;
  height: 36px;
  border: 1px solid rgb(255 255 255 / 16%);
  border-radius: 50%;
  color: #ddd3c1;
  background: rgb(0 0 0 / 28%);
  font-size: 22px;
  cursor: pointer;
}
.costPlayInstruction {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 3px 16px;
  padding: 14px 20px 10px;
}
.costPlayInstruction > strong {
  color: #f5e5c2;
}
.costPlayInstruction > span {
  grid-column: 1;
  color: #aeb8c5;
  font-size: 12px;
}
.costPlayInstruction > b {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
  color: #f1cc75;
  font-size: 20px;
}
.costPlayCards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
  gap: 12px;
  padding: 12px 20px 20px;
}
.costPlayCard {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 5px;
  padding: 7px;
  border: 1px solid rgb(255 255 255 / 13%);
  border-radius: 12px;
  color: #e9dfcb;
  background: rgb(0 0 0 / 28%);
  cursor: pointer;
  transition:
    transform 130ms ease,
    border-color 130ms ease,
    box-shadow 130ms ease;
}
.costPlayCard:hover:not(:disabled) {
  transform: translateY(-3px);
  border-color: #d4ad59;
}
.costPlayCard.selected {
  border-color: #f0cb70;
  box-shadow: 0 0 22px rgb(226 179 71 / 35%);
  background: rgb(83 59 18 / 45%);
}
.costPlayCard:disabled {
  opacity: 0.32;
  cursor: not-allowed;
  filter: grayscale(0.75);
}
.costPlayCard > img {
  width: 100%;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border-radius: 8px;
}
.costPlayCard > strong {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.costPlayCard > small {
  color: #efc969;
}
.costPlayCard > i {
  position: absolute;
  top: 11px;
  right: 11px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  color: #151007;
  background: #f0cb70;
  font-style: normal;
  font-weight: 900;
}
.costPlayCardFallback {
  display: grid;
  place-items: center;
  width: 100%;
  aspect-ratio: 3 / 4;
  padding: 8px;
  border-radius: 8px;
  background: #202734;
  text-align: center;
}
.costPlayModes {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  padding: 0 20px 12px;
}
.costPlayModes > button {
  padding: 7px 10px;
  border: 1px solid #665533;
  border-radius: 8px;
  color: #e7d9bc;
  background: #221c13;
}
.costPlayModes > button.selected {
  border-color: #e1b958;
  background: #5b4216;
}
.costPlayFooter {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 14px 20px 18px;
  border-top: 1px solid rgb(207 170 91 / 20%);
}

@media (max-width: 560px) {
  .costPlayBackdrop {
    padding: 7px;
    align-items: end;
  }
  .costPlayWindow {
    max-height: 94dvh;
    border-radius: 17px 17px 0 0;
  }
  .costPlayCards {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 7px;
    padding-inline: 12px;
  }
  .costPlayHeader,
  .costPlayInstruction,
  .costPlayFooter {
    padding-inline: 14px;
  }
}

.heroGradeEmblem {
  display: inline-block;
  flex: none;
  width: 72px;
  height: 72px;
  background-image: var(--grade-emblem-image);
  background-position: var(--grade-emblem-x) var(--grade-emblem-y);
  background-repeat: no-repeat;
  background-size: var(--grade-emblem-size, 200% 200%);
  filter: drop-shadow(0 7px 9px rgb(0 0 0 / 65%));
}

.heroGradeEmblem.compact {
  width: 42px;
  height: 42px;
  margin: -5px 0;
}

@keyframes modSystemPulse {
  50% {
    box-shadow:
      0 0 2.2cqw var(--mod-accent-soft),
      inset 0 0 1.2cqw var(--mod-accent-soft);
  }
}

.heroSystemBackdrop,
.commanderEquipmentBackdrop {
  position: fixed;
  inset: 0;
  z-index: 240;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgb(2 4 10 / 82%);
  backdrop-filter: blur(7px);
  animation: systemBackdropIn 160ms ease-out;
}

.commanderEquipmentBackdrop {
  z-index: 245;
}

@keyframes systemBackdropIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.heroSystemModal,
.commanderEquipmentWindow {
  position: relative;
  width: min(1080px, 96vw);
  max-height: min(900px, 92vh);
  overflow: auto;
  color: #e8dfca;
  border: 1px solid var(--mod-line);
  border-radius: var(--mod-corner);
  background:
    linear-gradient(155deg, rgb(2 5 12 / 78%), rgb(2 4 9 / 92%) 72%),
    var(--mod-art) center / cover no-repeat,
    linear-gradient(155deg, var(--mod-panel), var(--mod-panel-2) 72%);
  box-shadow:
    0 28px 90px rgb(0 0 0 / 75%),
    inset 0 0 0 1px rgb(255 255 255 / 5%);
  animation: systemWindowIn 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes systemWindowIn {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.heroSystemModal::before,
.commanderEquipmentWindow::before {
  content: "";
  position: absolute;
  inset: 8px;
  z-index: 0;
  border: 1px solid var(--mod-line);
  border-radius: 14px;
  pointer-events: none;
  opacity: 0.5;
}

.theme-anime .heroSystemModal::after,
.theme-anime .commanderEquipmentWindow::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    118deg,
    transparent 0 65px,
    rgb(112 191 255 / 3%) 66px 67px
  );
}

.theme-wuxia .heroSystemModal::after,
.theme-wuxia .commanderEquipmentWindow::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse at center,
    transparent 45%,
    rgb(117 214 179 / 6%)
  );
}

.heroSystemModal > *,
.commanderEquipmentWindow > * {
  position: relative;
  z-index: 1;
}

.heroSystemModal > header,
.commanderEquipmentWindow > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 28px 18px;
  border-bottom: 1px solid var(--mod-line);
}

.heroSystemModal h2,
.commanderEquipmentWindow h2 {
  margin: 2px 0 0;
  color: #fff2ce;
  font: 700 clamp(24px, 3vw, 36px)/1.05 var(--mod-heading);
  letter-spacing: 0.025em;
}

.heroSystemModal header small,
.commanderEquipmentWindow header small {
  color: var(--mod-accent);
  text-transform: uppercase;
  letter-spacing: 0.13em;
}

.heroSystemClose,
.commanderEquipmentWindow header button:not(.gradeHelpButton) {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--mod-line);
  border-radius: 50%;
  background: rgb(0 0 0 / 30%);
  color: #eadfca;
  cursor: pointer;
}

.heroSystemHeaderActions {
  display: flex;
  align-items: center;
  gap: 9px;
}

.gradeHelpButton {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--mod-line);
  border-radius: 50%;
  background: linear-gradient(145deg, var(--mod-accent-soft), rgb(0 0 0 / 44%));
  color: var(--mod-accent);
  cursor: pointer;
  transition:
    transform 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease;
}

.gradeHelpButton:hover,
.gradeHelpButton:focus-visible,
.gradeHelpButton.active {
  border-color: var(--mod-accent);
  box-shadow:
    0 0 18px var(--mod-accent-soft),
    inset 0 0 10px var(--mod-accent-soft);
  outline: none;
  transform: translateY(-1px);
}

.gradeWindowSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 20px 28px 8px;
}

.gradeWindowSummary > span {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 12px 16px;
  border: 1px solid var(--mod-line);
  border-radius: 12px;
  background: rgb(0 0 0 / 22%);
}

.gradeWindowSummary > .gradeWindowCurrent {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  padding-block: 5px;
  background: radial-gradient(
    circle at 20% 50%,
    var(--mod-accent-soft),
    rgb(0 0 0 / 24%) 70%
  );
}

.gradeWindowCurrent > span:last-child {
  display: flex;
  flex-direction: column;
}

.gradeWindowSummary b {
  color: #fff0c5;
  font-size: 20px;
}
.gradeWindowSummary small {
  color: #ab9f88;
}
.gradeWindowSummary .ready {
  box-shadow: inset 0 0 20px var(--mod-accent-soft);
}
.gradeWindowSummary .ready b {
  color: var(--mod-accent);
}

.gradeHelpPanel {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 10px 28px 0;
  padding: 14px;
  border: 1px solid var(--mod-line);
  border-radius: 14px;
  background:
    linear-gradient(145deg, rgb(255 255 255 / 5%), rgb(0 0 0 / 35%)),
    radial-gradient(circle at 50% 0%, var(--mod-accent-soft), transparent 62%);
  box-shadow: inset 0 0 30px rgb(0 0 0 / 35%);
  animation: systemWindowIn 160ms ease-out;
}

.gradeHelpPanel > div {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 9px;
  align-items: start;
}

.gradeHelpPanel > div > b {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1px solid var(--mod-accent);
  border-radius: 50%;
  color: #fff1ca;
  background: var(--mod-accent-soft);
  box-shadow: 0 0 12px var(--mod-accent-soft);
}

.gradeHelpPanel > div > span {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.gradeHelpPanel strong {
  color: #f4e9d2;
  font: 700 13px var(--mod-heading, Georgia, serif);
}

.gradeHelpPanel small {
  color: #aaa08d;
  font-size: 11px;
  line-height: 1.42;
}

.gradeHelpPanel > p {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 2px 0 0;
  padding-top: 9px;
  border-top: 1px solid rgb(255 255 255 / 8%);
  color: #c9bda7;
  font-size: 11px;
}

.heroGradeTree {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 28px;
  padding: 24px 28px 30px;
}

.heroGradeTier {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.heroGradeTier:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 50%;
  right: -22px;
  width: 16px;
  height: 2px;
  background: linear-gradient(90deg, var(--mod-accent), transparent);
  box-shadow: 0 0 8px var(--mod-accent);
}

.heroGradeTier h3 {
  margin: 0;
  color: var(--mod-accent);
  font:
    700 15px Georgia,
    serif;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.heroGradeTier h3 span,
.heroGradeTier h3 small {
  display: block;
}

.heroGradeTier h3 small {
  margin-top: 3px;
  color: #8f8677;
  font: 600 9px/1 sans-serif;
  letter-spacing: 0.18em;
}

.heroGradeNode {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 7px 11px;
  min-height: 138px;
  padding: 15px 15px 14px 18px;
  border: 0;
  border-radius: 16px;
  background-image:
    linear-gradient(90deg, rgb(2 5 10 / 6%) 26%, rgb(2 5 10 / 40%)),
    url("/assets/anime/hero-grades/tier-button-frames-atlas.webp");
  background-position:
    center,
    center top;
  background-repeat: no-repeat;
  background-size:
    100% 100%,
    100% 300%;
  box-shadow: 0 10px 18px rgb(0 0 0 / 28%);
  color: #dcd4c4;
  text-align: left;
  overflow: hidden;
  /* Pack the icon + title + description at the top instead of letting the
     grid stretch them apart across the reserved min-height. */
  align-content: start;
  transition:
    transform 150ms ease,
    filter 150ms ease,
    box-shadow 150ms ease;
}

.heroGradeNode.tier-2 {
  background-position:
    center,
    center center;
}

.heroGradeNode.tier-3 {
  background-position:
    center,
    center bottom;
}

.heroGradeNodeIcon {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  align-self: start;
  /* Span both content rows so the title/description stack tightly beside it. */
  grid-row: 1 / 3;
  filter: drop-shadow(0 5px 7px rgb(0 0 0 / 60%));
}

.heroGradeAbilityEmblem {
  display: block;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background-image: var(--grade-ability-image);
  background-position: var(--grade-ability-x) var(--grade-ability-y);
  background-repeat: no-repeat;
  background-size: 400% 400%;
}

.heroGradeNodeStatus {
  position: absolute;
  right: -2px;
  bottom: -2px;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  border-radius: 50%;
  background: #080c13;
  box-shadow: 0 2px 6px rgb(0 0 0 / 70%);
}

.heroGradeNode > span:nth-child(2) {
  display: flex;
  flex-direction: column;
}
.heroGradeNode strong {
  color: #f6ecd6;
  font:
    700 15px Georgia,
    serif;
  text-shadow: 0 1px 2px rgb(0 0 0 / 82%);
}
.heroGradeNode small {
  color: #b3a891;
  font-size: 10px;
  text-shadow: 0 1px 2px rgb(0 0 0 / 78%);
}
.heroGradeNode p {
  grid-column: 2;
  margin: 6px 0 0;
  color: #ded5c4;
  font-size: 12px;
  line-height: 1.5;
  text-shadow: 0 1px 2px rgb(0 0 0 / 80%);
}
.heroGradeNode.locked {
  opacity: 0.58;
  filter: saturate(0.38) brightness(0.72);
}
.heroGradeNode.available {
  cursor: pointer;
  filter: saturate(1.08) brightness(1.06);
  box-shadow:
    0 0 22px var(--mod-accent-soft),
    0 12px 22px rgb(0 0 0 / 42%);
}
.heroGradeNode.available:hover,
.heroGradeNode.available:focus-visible {
  transform: translateY(-3px) scale(1.012);
  filter: saturate(1.2) brightness(1.15);
  box-shadow:
    0 0 30px var(--mod-accent-soft),
    0 16px 26px rgb(0 0 0 / 50%);
  outline: none;
}
.heroGradeNode.owned {
  filter: saturate(1.05);
  box-shadow:
    0 0 18px var(--mod-accent-soft),
    inset 0 0 22px var(--mod-accent-soft);
}
.heroGradeNode.owned .heroGradeNodeIcon {
  color: var(--mod-accent);
}

@media (max-width: 840px) {
  .heroGradeTree {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .heroGradeTier:not(:last-child)::after {
    display: none;
  }

  .gradeHelpPanel {
    grid-template-columns: 1fr;
  }

  .gradeWindowSummary {
    grid-template-columns: 1fr;
  }
}

.equipmentWindowBody {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(280px, 0.75fr);
  height: 610px;
  min-height: 610px;
}

.equipmentPaperdoll {
  position: relative;
  min-height: 610px;
  border-right: 1px solid var(--mod-line);
  background: radial-gradient(
    circle at 50% 46%,
    var(--mod-accent-soft),
    transparent 44%
  );
}

.equipmentSilhouette {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150px;
  height: 420px;
  transform: translate(-50%, -48%);
  filter: drop-shadow(0 0 25px var(--mod-accent-soft));
}

.equipmentSilhouette span {
  position: absolute;
  display: block;
  background: linear-gradient(
    90deg,
    rgb(0 0 0 / 50%),
    var(--mod-accent-soft),
    rgb(0 0 0 / 50%)
  );
  border: 1px solid var(--mod-line);
}
.equipmentSilhouette .head {
  top: 0;
  left: 48px;
  width: 55px;
  height: 65px;
  border-radius: 50% 50% 44% 44%;
}
.equipmentSilhouette .body {
  top: 67px;
  left: 30px;
  width: 90px;
  height: 190px;
  clip-path: polygon(18% 0, 82% 0, 100% 100%, 0 100%);
}
.equipmentSilhouette .arms {
  top: 76px;
  left: 0;
  width: 150px;
  height: 180px;
  clip-path: polygon(
    20% 0,
    30% 3%,
    17% 100%,
    6% 98%,
    13% 12%,
    87% 12%,
    94% 98%,
    83% 100%,
    70% 3%,
    80% 0
  );
}
.equipmentSilhouette .legs {
  top: 250px;
  left: 29px;
  width: 92px;
  height: 170px;
  clip-path: polygon(
    0 0,
    45% 0,
    50% 100%,
    37% 100%,
    28% 24%,
    20% 100%,
    7% 100%,
    12% 0,
    88% 0,
    93% 100%,
    80% 100%,
    72% 24%,
    63% 100%,
    50% 100%,
    55% 0
  );
}

