  top: 16%;
}
.equipmentSlot.slot-armor {
  right: 5%;
  top: 16%;
}
.equipmentSlot.slot-accessory {
  left: 5%;
  bottom: 12%;
}
.equipmentSlot.slot-mount {
  right: 5%;
  bottom: 12%;
}

.equipmentCatalog {
