  color: #f6e9ce;
  font:
    700 18px Georgia,
    serif;
}
.equipmentCatalog > p {
  margin: 0 0 16px;
  color: #9e9584;
  font-size: 11px;
  line-height: 1.45;
}
.equipmentCatalogItem {
