  align-items: center;
  gap: 10px;
  padding: 9px;
  border-top: 1px solid rgb(255 255 255 / 7%);
}
.equipmentCatalogItem img,
.equipmentCatalogItem > span:first-child {
  width: 38px;
  height: 38px;
  object-fit: contain;
