  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 4%),
    0 8px 20px rgb(0 0 0 / 28%);
}

.commanderEquipButtonIcon {
  display: grid !important;
  flex: 0 0 62px !important;
  place-items: center;
  width: 62px;
  height: 62px;
  overflow: hidden;
  border: 1px solid var(--mod-line, rgb(228 189 104 / 45%));
