}
.commanderEquipButtonIcon img {
  width: 54px;
  height: 54px;
  object-fit: contain;
  filter: drop-shadow(0 3px 7px rgb(0 0 0 / 75%));
}

.commanderEquipButton > span {
  display: flex;
  flex: 1;
  flex-direction: column;
  text-align: left;
}
.commanderEquipButton strong {
  color: #f5e5c3;
  font:
    700 17px Georgia,
    serif;
}
.commanderEquipButton small {
  color: #aa9878;
  font-size: 11px;
}
.commanderEquipButton .commanderEquipEyebrow {
  color: var(--mod-accent, #e4bd68);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.commanderEquipArrow {
