}
.commanderEquipButton.attention {
  box-shadow: 0 0 16px var(--mod-accent-soft, rgb(228 189 104 / 20%));
}
.commanderEquipButton:hover {
  border-color: var(--mod-accent, #e4bd68);
}

.commanderEquipmentWindow {
  width: min(1100px, 96vw);
}
.commanderEquipmentBody {
  display: grid;
  grid-template-columns: minmax(460px, 1.2fr) minmax(340px, 0.85fr);
  height: 620px;
  min-height: 620px;
}
.commanderPaperdoll {
  position: relative;
  min-height: 620px;
  border-right: 1px solid var(--mod-line);
  overflow: hidden;
  background:
    radial-gradient(
      ellipse at 50% 42%,
      var(--mod-accent-soft),
      transparent 52%
    ),
    radial-gradient(circle at 50% 100%, rgb(0 0 0 / 55%), transparent 48%),
    linear-gradient(180deg, #12151b 0%, #07090d 100%);
}
/* Diablo-style empty paperdoll body (Codex art). Classic keeps the card bust
   overlay; anime/wuxia use themed body art only (no full card on the body). */
.commanderPaperdollBody {
  position: absolute;
  left: 50%;
  top: 52%;
  width: min(320px, 62%);
  height: 88%;
  transform: translate(-50%, -50%);
  object-fit: contain;
  opacity: 0.92;
  filter: drop-shadow(0 0 28px var(--mod-accent-soft))
    drop-shadow(0 18px 30px rgb(0 0 0 / 70%));
  pointer-events: none;
  user-select: none;
}
.theme-anime .commanderPaperdollBody,
.theme-wuxia .commanderPaperdollBody {
  width: min(380px, 72%);
  opacity: 0.98;
  filter: drop-shadow(0 0 34px var(--mod-accent-soft))
    drop-shadow(0 18px 34px rgb(0 0 0 / 72%)) saturate(1.08);
}
.commanderPaperdollBust {
  position: absolute;
  left: 50%;
  top: 12%;
  width: 132px;
  height: 148px;
  transform: translateX(-50%);
  border-radius: 50% 50% 42% 42%;
  overflow: hidden;
  border: 2px solid rgb(228 189 104 / 45%);
  box-shadow:
    0 0 22px var(--mod-accent-soft),
    inset 0 0 18px rgb(0 0 0 / 55%);
  pointer-events: none;
  z-index: 2;
}
/* Anime/wuxia: hide the card-face bust — the themed body art is the figure. */
.theme-anime .commanderPaperdollBust,
.theme-wuxia .commanderPaperdollBust {
  display: none;
}
.commanderPaperdollPortrait {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 18%;
  filter: saturate(1.05);
}
.commanderArtifactSlot {
  position: absolute;
  z-index: 3;
  display: grid;
  grid-template-columns: 68px 1fr;
  gap: 8px 12px;
  align-items: center;
  width: min(240px, 42%);
  min-height: 92px;
  padding: 10px 12px;
  border: 1px solid rgb(228 189 104 / 28%);
  border-radius: 14px;
  background: linear-gradient(145deg, rgb(18 14 8 / 88%), rgb(4 6 10 / 90%));
  box-shadow:
    0 10px 24px rgb(0 0 0 / 45%),
    inset 0 0 0 1px rgb(255 255 255 / 4%);
  transition:
    border-color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms ease;
}
.commanderArtifactSlotWell {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 2px solid rgb(228 189 104 / 42%);
  background: radial-gradient(
    circle at 40% 30%,
    rgb(80 62 30 / 35%),
    rgb(8 8 10 / 90%) 70%
  );
  box-shadow:
    inset 0 0 14px rgb(0 0 0 / 70%),
    0 0 10px rgb(0 0 0 / 40%);
}
.commanderArtifactSlotWell img,
.commanderArtifactSlotWell svg {
  width: 48px;
  height: 48px;
  object-fit: contain;
  color: var(--mod-accent, #e4bd68);
}
.theme-anime .commanderArtifactSlotWell,
.theme-wuxia .commanderArtifactSlotWell {
  width: 72px;
  height: 72px;
}
.theme-anime .commanderArtifactSlotWell img,
.theme-anime .commanderArtifactSlotWell svg,
.theme-wuxia .commanderArtifactSlotWell img,
.theme-wuxia .commanderArtifactSlotWell svg {
  width: 52px;
  height: 52px;
}
.commanderArtifactSlotMeta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.commanderArtifactSlot small {
  color: var(--mod-accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 9px;
}
.commanderArtifactSlot strong {
  color: #f2e5ca;
  font:
    700 13px Georgia,
    serif;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.commanderArtifactSlot span {
  color: #9c927f;
  font-size: 10px;
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.commanderArtifactSlot.empty {
  opacity: 0.78;
  border-style: dashed;
}
.commanderArtifactSlot.filled {
  border-color: var(--mod-accent, #e4bd68);
  box-shadow:
    0 0 20px var(--mod-accent-soft),
    0 10px 24px rgb(0 0 0 / 45%);
}
.commanderArtifactSlot.dropReady {
  border-color: #f0c46a;
  border-style: solid;
  transform: translateY(-2px);
  box-shadow:
    0 0 28px rgb(240 196 106 / 45%),
    0 12px 28px rgb(0 0 0 / 50%);
}
.commanderArtifactSlot.dropReady .commanderArtifactSlotWell {
  border-color: #f0c46a;
  box-shadow:
    0 0 18px rgb(240 196 106 / 40%),
    inset 0 0 14px rgb(0 0 0 / 70%);
}
/* Diablo-ish slot anchors around the body silhouette. */
.commanderArtifactSlot.slot-weapon {
  left: 4%;
  top: 18%;
}
.commanderArtifactSlot.slot-armor {
  right: 4%;
  top: 34%;
}
.commanderArtifactSlot.slot-trinket {
  left: 4%;
  bottom: 10%;
}
.commanderArtifactInventory {
  min-height: 0;
  padding: 22px;
  overflow: auto;
  background: rgb(0 0 0 / 18%);
}
.commanderInventoryHead h3 {
  margin: 0 0 3px;
  color: #f1e4ca;
  font:
    700 18px Georgia,
    serif;
}
.commanderInventoryHead small {
  color: #8f887a;
}
.commanderInventoryEmpty {
  margin: 30px 0;
  padding: 20px;
  border: 1px dashed var(--mod-line);
  border-radius: 12px;
