}
.commanderArtifactMeta {
  color: var(--mod-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.13em;
}
.commanderInventoryCard strong {
  margin-top: 2px;
  color: #efe2c8;
  font:
    700 14px Georgia,
    serif;
}
.commanderInventoryCard p {
  margin: 5px 0;
  color: #aaa08f;
  font-size: 10px;
