}

.commanderInventoryCard.equipped {
  border-color: rgb(216 181 93 / 70%);
}

.commanderForgePanel {
  display: grid;
  grid-template-columns: 78px minmax(0, 1fr);
  gap: 12px;
  margin: 10px 0 14px;
  padding: 12px;
  border: 1px solid rgba(220, 174, 73, 0.62);
