  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.armyXpHead img {
  width: 15px;
  height: 15px;
  object-fit: contain;
}
.armyXpHead strong {
  color: var(--mod-accent, #e4bd68);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.armyXpHead b {
  color: #eee1c6;
}
.armyXpTrack {
  position: relative;
  height: 7px;
  margin: 8px 5px 18px 0;
  border-radius: 999px;
  background: rgb(255 255 255 / 9%);
  box-shadow: inset 0 1px 3px rgb(0 0 0 / 65%);
}
.armyXpFill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    var(--mod-accent, #c9963a),
    var(--mod-accent-2, #f0cf76)
  );
  box-shadow: 0 0 9px var(--mod-accent-soft, rgb(228 189 104 / 30%));
  transition: width 220ms ease;
}
.armyXpMilestone {
  position: absolute;
  top: 50%;
  width: 1px;
  height: 14px;
  transform: translate(-50%, -50%);
  background: #6e6657;
}
.armyXpMilestone i {
  position: absolute;
  top: -4px;
  left: 50%;
  display: grid;
  place-items: center;
  width: 12px;
  height: 12px;
  transform: translateX(-50%);
  border: 1px solid #766b58;
  border-radius: 50%;
  background: #262119;
  color: #948873;
  font: normal 700 7px sans-serif;
}
.armyXpMilestone small {
  position: absolute;
  top: 13px;
  left: 50%;
  transform: translateX(-50%);
  color: #766e61;
  font-size: 7px;
}
.armyXpMilestone.reached i {
  border-color: var(--mod-accent, #e4bd68);
  color: var(--mod-accent, #e4bd68);
  box-shadow: 0 0 6px var(--mod-accent-soft, rgb(228 189 104 / 25%));
}
.armyXpDetails {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 8px;
  color: #988d7b;
  font-size: 8px;
}
.armyXpDetails .eliteAbility {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.armyXpDetails .eliteAbility.active {
  color: var(--mod-accent, #e4bd68);
}
.armyXpDetails .eliteAbility.locked {
  color: #746d61;
}
.armyUnitActions {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0 5px 4px 36px;
}
.armyUnitActions button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border: 1px solid var(--mod-line, rgb(228 189 104 / 34%));
  border-radius: 6px;
  background: linear-gradient(
    180deg,
    var(--mod-accent-soft, rgb(228 189 104 / 14%)),
    rgb(0 0 0 / 16%)
  );
  color: #d9c9aa;
  font-size: 8px;
  cursor: pointer;
}
.armyUnitActions button:hover {
  border-color: var(--mod-accent, #e4bd68);
  color: #fff0ce;
}
.commanderIntroFace img {
  display: block;
  width: 100%;
  max-height: 240px;
  object-fit: contain;
  filter: drop-shadow(0 8px 16px rgb(0 0 0 / 55%));
}
.armyUnitActions button.drillUnitButton {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(84px, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-width: 176px;
  padding: 7px 9px 7px 7px;
  overflow: visible;
  border: 1px solid #ffd65a;
  background:
    radial-gradient(
      circle at 16px 50%,
      rgb(255 226 113 / 28%),
      transparent 31px
    ),
    linear-gradient(180deg, rgb(151 93 12 / 96%), rgb(66 32 3 / 98%));
  color: #fff7d6;
  box-shadow:
    0 0 15px rgb(255 194 55 / 35%),
    inset 0 0 0 1px rgb(255 241 185 / 17%);
  text-align: left;
}
.armyUnitActions button.drillUnitButton:hover,
.armyUnitActions button.drillUnitButton:focus-visible {
  border-color: #fff0a6;
  background:
    radial-gradient(
      circle at 16px 50%,
      rgb(255 239 161 / 36%),
      transparent 32px
    ),
    linear-gradient(180deg, rgb(199 132 20 / 98%), rgb(92 47 5 / 100%));
  box-shadow:
    0 0 23px rgb(255 202 69 / 58%),
    inset 0 0 0 1px rgb(255 248 213 / 24%);
  transform: translateY(-1px);
}
.drillUnitButtonIcon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 1px solid rgb(255 233 147 / 74%);
  border-radius: 50%;
  background: rgb(40 19 2 / 58%);
  color: #ffe680;
}
.drillUnitButtonText {
  display: grid;
  gap: 1px;
  line-height: 1.1;
}
.drillUnitButtonText strong {
  font-size: 11px;
  letter-spacing: 0.035em;
}
.drillUnitButtonText small {
  color: #f5dca0;
  font-size: 8px;
}
.drillUnitButtonCost {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 6px;
  border: 1px solid rgb(255 224 112 / 55%);
  border-radius: 999px;
  background: rgb(27 14 2 / 66%);
  color: #ffe06c;
}
.drillUnitButtonCost b {
  font-size: 12px;
}
.drillUnitButtonCost small {
  color: #f7d98d;
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}
.drillUnitButton::after {
  position: absolute;
  z-index: 120;
  left: 0;
  bottom: calc(100% + 8px);
  width: min(300px, 76vw);
  padding: 8px 10px;
  border: 1px solid rgb(255 218 103 / 65%);
  border-radius: 7px;
  background: rgb(20 13 5 / 97%);
  box-shadow: 0 8px 24px rgb(0 0 0 / 60%);
  color: #f9e8bd;
  content: attr(data-tip);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.35;
  opacity: 0;
  pointer-events: none;
  transform: translateY(3px);
  transition:
    opacity 120ms ease,
    transform 120ms ease;
}
.drillUnitButton:hover::after,
.drillUnitButton:focus-visible::after {
  opacity: 1;
  transform: translateY(0);
}
.armyPanel.theme-classic,
.armyPanel.theme-anime,
.armyPanel.theme-wuxia {
  border: 1px solid var(--mod-line);
  background:
    linear-gradient(160deg, rgb(3 7 13 / 80%), rgb(2 5 9 / 94%)),
    var(--mod-art) center / cover no-repeat,
    var(--mod-panel-2);
  box-shadow:
    inset 0 0 34px rgb(0 0 0 / 52%),
    0 12px 30px rgb(0 0 0 / 35%);
}

/* Three genuinely separate visual registers, shared by every mod-system part. */
.theme-classic .heroSystemModal,
.theme-classic .commanderEquipmentWindow,
.armyPanel.theme-classic {
  border-width: 4px;
  border-style: ridge;
  font-family: Georgia, "Times New Roman", serif;
}

.theme-anime .heroSystemModal,
.theme-anime .commanderEquipmentWindow,
.armyPanel.theme-anime {
  border-width: 2px;
  border-color: #75d8ff;
  box-shadow:
    0 28px 90px rgb(0 0 0 / 75%),
    0 0 35px rgb(72 181 255 / 22%),
    inset 0 0 0 2px rgb(240 92 162 / 20%);
  font-family: "Trebuchet MS", system-ui, sans-serif;
}

.theme-wuxia .heroSystemModal,
.theme-wuxia .commanderEquipmentWindow,
.armyPanel.theme-wuxia {
  border-width: 3px;
  border-style: double;
  box-shadow:
    0 28px 90px rgb(0 0 0 / 70%),
    inset 0 0 48px rgb(70 174 135 / 12%);
  font-family: Georgia, "Noto Serif", serif;
}

.theme-anime .heroGradeNode,
.theme-anime .equipmentSlot,
.theme-anime .commanderArtifactSlot,
.theme-anime .unitXpEntry,
.theme-anime .unitXpRank {
  border-radius: 4px 15px 4px 15px;
}

.theme-wuxia .heroGradeNode,
.theme-wuxia .equipmentSlot,
.theme-wuxia .commanderArtifactSlot,
.theme-wuxia .unitXpEntry,
.theme-wuxia .unitXpRank {
  border-radius: 22px 6px 22px 6px;
}

.townWindow.theme-classic,
.townWindow.theme-anime,
.townWindow.theme-wuxia {
  border-color: var(--mod-line);
  background:
    linear-gradient(160deg, rgb(4 7 12 / 82%), rgb(3 5 9 / 94%)),
    var(--mod-art) center / cover no-repeat,
    var(--mod-panel-2);
}

.townWindow.theme-classic {
  border-width: 5px;
  border-style: ridge;
  border-radius: 3px;
}
.townWindow.theme-anime {
  border-width: 2px;
  border-color: #75d8ff;
  border-radius: 5px 19px 5px 19px;
}
.townWindow.theme-wuxia {
  border-width: 4px;
  border-style: double;
  border-radius: 28px 7px 28px 7px;
}
.townWindow.theme-anime .townWindowHeader {
  background: linear-gradient(90deg, rgb(12 21 51 / 95%), rgb(47 17 50 / 88%));
}
.townWindow.theme-wuxia .townWindowHeader {
  background: linear-gradient(90deg, rgb(11 42 36 / 95%), rgb(17 48 38 / 88%));
}
.tbRoot.theme-classic .tbPanel,
.tbRoot.theme-anime .tbPanel,
.tbRoot.theme-wuxia .tbPanel {
  border-color: var(--mod-line);
  background:
    linear-gradient(155deg, rgb(2 5 10 / 84%), rgb(2 4 8 / 94%)),
    var(--mod-art) center / cover no-repeat,
    var(--mod-panel-2);
}
.tbRoot.theme-anime .tbPanel {
  border-radius: 5px 17px 5px 17px;
}
.tbRoot.theme-wuxia .tbPanel {
  border-radius: 22px 6px 22px 6px;
}

.equipmentSilhouette {
  width: 250px;
  height: 500px;
}

.equipmentSilhouette > img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  opacity: 0.78;
  mask-image: linear-gradient(to bottom, #000 72%, transparent 100%);
  filter: saturate(0.9) contrast(1.08);
}

.equipmentSlot.dropReady,
.commanderArtifactSlot.dropReady {
  opacity: 1;
  border-color: var(--mod-accent);
  background: linear-gradient(145deg, var(--mod-accent-soft), rgb(0 0 0 / 56%));
  box-shadow:
    0 0 28px var(--mod-accent-soft),
    inset 0 0 18px var(--mod-accent-soft);
  transform: scale(1.025);
}

.equipmentUnequipButton {
  grid-column: 2;
  justify-self: start;
  padding: 4px 8px;
  border: 1px solid var(--mod-line);
  border-radius: 6px;
  background: rgb(0 0 0 / 32%);
  color: var(--mod-accent);
  font-size: 9px;
  cursor: pointer;
}

.equipmentCatalogItem {
  position: relative;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  gap: 2px 10px;
  border: 1px solid transparent;
  border-radius: 9px;
}

.equipmentCatalogItem.owned {
  border-color: var(--mod-line);
  background: rgb(255 255 255 / 4%);
  cursor: grab;
}

.equipmentCatalogItem.owned:active {
  cursor: grabbing;
}
.equipmentCatalogItem.unowned {
  opacity: 0.5;
  filter: saturate(0.45);
}
.equipmentCatalogItem > span:nth-child(2) {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.equipmentCatalogItem > span:nth-child(2) strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.equipmentCatalogItem .equipmentOwnership {
  grid-column: 2;
  color: var(--mod-accent);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.equipmentCatalogItem > button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  grid-column: 3;
  grid-row: 1 / 3;
  align-self: center;
  padding: 5px 9px;
  border: 1px solid var(--mod-line);
  border-radius: 6px;
  background: var(--mod-accent-soft);
  color: #f6ecd6;
  cursor: pointer;
}

.commanderInventoryCard[draggable="true"] {
  cursor: grab;
}
.commanderInventoryCard[draggable="true"]:active {
  cursor: grabbing;
}

/* The roster's Unit-Experience entry point: a button opening the pop-up board
   (like the Hero Grade / Hero Equipment windows). */
button.armyExperienceBoard {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  width: calc(100% - 14px);
  margin: 8px 7px 11px;
  padding: 10px;
  border: 1px solid var(--mod-line, rgb(228 189 104 / 34%));
  border-radius: var(--mod-corner, 8px);
  background: linear-gradient(
    145deg,
    var(--mod-accent-soft, rgb(228 189 104 / 14%)),
    rgb(0 0 0 / 45%)
  );
  box-shadow: inset 0 0 22px rgb(0 0 0 / 38%);
  color: #d9c9aa;
  text-align: left;
  cursor: pointer;
}

button.armyExperienceBoard:hover,
button.armyExperienceBoard:focus-visible {
  border-color: var(--mod-accent, #e4bd68);
  outline: none;
}

.armyXpBoardTitle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--mod-accent, #e4bd68);
}
.armyXpBoardTitle strong {
  color: #f4e8cf;
  font: 700 13px var(--mod-heading, Georgia, serif);
}
button.armyExperienceBoard > small {
  color: #9b917d;
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.11em;
}

/* Unit Experience Board window: pick a unit card, then open a large detail panel.
   Shares the heroSystemModal themed shell. */
.heroSystemModal.unitXpWindow {
  width: min(1180px, 96vw);
}
.heroSystemModal.unitXpWindow.unitXpDetailOpen {
  width: min(1280px, 98vw);
  max-height: min(920px, 96vh);
}
.unitXpSources {
  margin: 14px 28px 0;
  color: #a99e8a;
  font-size: 12px;
  line-height: 1.55;
}
.unitXpHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.unitXpBack {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid var(--mod-line);
  background: rgb(0 0 0 / 35%);
  color: #f0e6d0;
  font: 700 12px var(--mod-heading, Georgia, serif);
  cursor: pointer;
}
.unitXpBack:hover {
  border-color: var(--mod-accent);
  color: var(--mod-accent);
}
.unitXpPicker {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 8px;
  padding: 10px 18px 16px;
  max-height: min(70vh, 720px);
  overflow: auto;
}
.unitXpPickerCard {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  padding: 7px;
  border: 1px solid var(--mod-line);
  border-radius: 12px;
  background: linear-gradient(165deg, rgb(30 24 16 / 88%), rgb(8 10 14 / 92%));
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 140ms ease,
    transform 140ms ease,
    box-shadow 140ms ease;
}
.unitXpPickerCard:hover,
.unitXpPickerCard:focus-visible {
  border-color: var(--mod-accent);
  transform: translateY(-2px);
  box-shadow:
    0 0 22px var(--mod-accent-soft),
    0 12px 24px rgb(0 0 0 / 45%);
  outline: none;
}
.unitXpPickerArt {
  width: 72px;
  height: 96px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid rgb(255 255 255 / 10%);
  background: rgb(0 0 0 / 35%);
}
.unitXpPickerArt.fallback {
  display: block;
  min-height: 96px;
}
.unitXpPickerMeta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.unitXpPickerMeta strong {
  flex: 1 1 100%;
  color: #f1e7d2;
  font: 700 14px var(--mod-heading, Georgia, serif);
}
.unitXpPickerMeta em {
  color: var(--mod-accent);
  font-style: normal;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.unitXpPickerMeta > b {
  margin-left: auto;
  color: #eee1c6;
  font-size: 12px;
}
.unitXpEmpty {
  margin: 10px 0 30px;
  padding: 18px;
  border: 1px dashed var(--mod-line);
  border-radius: 12px;
  color: #aaa08e;
  text-align: center;
  grid-column: 1 / -1;
}

.unitXpDetail {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 10px 16px 14px;
  min-height: 0;
  overflow: auto;
}
.unitXpDetailHero {
  display: grid;
  grid-template-columns: 152px minmax(0, 1fr);
  gap: 10px 14px;
  align-items: start;
}
.unitXpDetailArt {
  width: 100%;
  max-width: 152px;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border-radius: 11px;
  border: 1px solid var(--mod-line);
  box-shadow: 0 16px 36px rgb(0 0 0 / 45%);
  background: rgb(0 0 0 / 35%);
}
.unitXpDetailArt.fallback {
  display: block;
  min-height: 203px;
}
.unitXpDetailSummary {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.unitXpHeadRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.unitXpHeadRow strong {
  color: #f1e7d2;
  font: 700 18px var(--mod-heading, Georgia, serif);
}
.unitXpHeadRow em {
  color: var(--mod-accent);
  font-style: normal;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
}
.unitXpHeadRow > b {
  margin-left: auto;
  color: #eee1c6;
  font-size: 14px;
}

.unitXpStats {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 14px;
  color: #b3a88f;
  font-size: 12px;
}
.unitXpStats.large {
  gap: 8px 18px;
  font-size: 15px;
}
.unitXpStats .boosted {
  color: var(--mod-accent);
  font-weight: 700;
}

.armyXpTrack.large {
  height: 18px;
  margin-top: 4px;
}
.armyXpTrack.large .armyXpMilestone i {
  font-size: 11px;
}

.unitXpRanks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.unitXpRanks.large {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
@media (min-width: 900px) {
  .unitXpRanks {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .unitXpRanks.large {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (min-width: 980px) {
  .unitXpRanks.large {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 720px) {
  .unitXpDetailHero {
    grid-template-columns: 86px minmax(0, 1fr);
    gap: 8px 10px;
  }
  .unitXpDetailArt {
    max-width: 86px;
    margin: 0;
  }
}

.unitXpRank {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: 2px 7px;
  padding: 8px;
  border: 1px solid rgb(255 255 255 / 9%);
  border-radius: 10px;
  background: rgb(0 0 0 / 24%);
}

.unitXpRank .unitXpRankIcon {
  grid-row: 1 / 3;
  display: grid;
  place-items: center;
  align-self: start;
  margin-top: 0;
  color: var(--mod-accent);
}
.unitXpRank .unitXpRankIcon .unitRankBadgeArt {
  width: 56px;
  height: 56px;
  filter: drop-shadow(0 3px 5px rgb(0 0 0 / 62%));
}
.unitXpRank b {
  color: #e8dcc4;
  font-size: 13px;
}
.unitXpRank small {
  grid-column: 2;
  color: #9d927e;
  font-size: 11px;
  line-height: 1.35;
}
.unitXpRank .unitXpRankGains {
  grid-column: 1 / -1;
  margin-top: 4px;
  color: #cabfa4;
  font-size: 12px;
}
.unitXpRank.reached {
  border-color: var(--mod-accent);
  box-shadow: inset 0 0 16px var(--mod-accent-soft);
}
.unitXpRank.reached .unitXpRankGains {
  color: var(--mod-accent);
}
.unitXpRank.next {
  border-color: rgb(255 255 255 / 22%);
}
.unitXpRank.locked {
  opacity: 0.62;
  filter: saturate(0.4);
}

/* Ability row: icon + name + status, then full rules text. */
.unitXpElite {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr) auto;
  gap: 3px 8px;
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px dashed rgb(255 255 255 / 14%);
  font-size: 12px;
  align-items: start;
}
.unitXpElite > img.unitXpAbilityIcon {
  grid-row: 1 / 2;
  width: 56px;
  height: 56px;
  object-fit: contain;
  border-radius: 6px;
  box-shadow: 0 0 0 1px rgb(0 0 0 / 50%);
}
.unitXpElite > svg {
  grid-row: 1 / 3;
  align-self: start;
  margin-top: 1px;
}
.unitXpElite > b {
  color: inherit;
}
.unitXpElite > small {
  grid-column: 2 / -1;
  line-height: 1.4;
  opacity: 0.9;
}
.unitXpElite.active {
  color: var(--mod-accent);
}
.unitXpElite.locked {
  color: #746d61;
}
.unitXpElite.signature {
  border-top-color: rgb(231 183 60 / 55%);
  background: linear-gradient(180deg, rgb(80 55 12 / 35%), transparent);
  padding: 5px 4px 2px;
  border-radius: 0 0 6px 6px;
}

/* Stat rewards now use the same full-art treatment as ability rewards. */
.unitXpStatUpgrade {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr) auto;
  gap: 3px 8px;
  align-items: center;
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px dashed rgb(255 255 255 / 14%);
  color: #746d61;
  font-size: 12px;
}
.unitXpStatUpgrade.active {
  color: var(--mod-accent);
}
.unitXpStatUpgrade > b {
  color: inherit;
}
.unitXpStatUpgrade > em {
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.unitXpStatUpgrade > small {
  grid-column: 2 / -1;
  color: inherit;
  line-height: 1.4;
