/* Desktop command-rail overflow escape hatch. The compact rail remains the
   default; "View all" promotes that same live content into a roomy modal. */
@media (min-width: 1101px) {
  .adventureRoot:not(.phoneMode) .leftRail.leftRailExpanded {
    top: max(24px, env(safe-area-inset-top, 0px));
    right: auto;
    bottom: max(24px, env(safe-area-inset-bottom, 0px));
    left: max(24px, calc((100vw - 1080px) / 2));
    z-index: 215;
    display: block;
    box-sizing: border-box;
    width: min(1080px, calc(100vw - 48px));
    padding: 16px;
    overflow: auto;
    border: 2px solid rgb(203 158 78 / 76%);
    border-radius: 16px;
    background:
      linear-gradient(180deg, rgb(48 34 19 / 98%), rgb(18 12 8 / 99%) 94px),
      var(--cmp-leather) center / 320px repeat;
    box-shadow:
      inset 0 0 0 1px rgb(255 230 165 / 12%),
      inset 0 0 44px rgb(0 0 0 / 48%),
      0 28px 80px rgb(0 0 0 / 76%);
    scrollbar-width: thin;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailToolbar {
    position: sticky;
    top: -16px;
    left: auto;
    justify-content: space-between;
    margin: -16px -16px 14px;
    padding: 12px 14px;
    border-bottom: 1px solid rgb(203 158 78 / 42%);
    background: linear-gradient(
      180deg,
      rgb(55 39 21 / 99%),
      rgb(30 20 12 / 99%)
    );
    box-shadow: 0 8px 18px rgb(0 0 0 / 28%);
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailToolbar > strong {
    display: block;
    color: #f2d79c;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 18px;
    letter-spacing: 0.045em;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailExpandButton {
    width: auto;
    min-height: 27px;
    padding: 4px 8px;
    font-size: 10px;
    opacity: 1;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailExpandButton span {
    display: inline;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailDock {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 14px;
    align-items: start;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailDock::before {
    grid-column: 1 / -1;
    margin-bottom: -2px;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailDock .townHeroDock {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 12px;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailDock .dockTile {
    min-height: 82px;
  }

  .adventureRoot:not(.phoneMode) .leftRailExpanded .leftRailDock .heroDrop {
    left: max(24px, calc((100vw - min(1080px, calc(100vw - 48px))) / 2 + 24px));
    top: 74px;
    width: min(900px, calc(100vw - 96px));
    max-height: calc(100dvh - 122px);
  }
}

.phoneMode .leftRailToolbar {
  display: none;
}

/* Detail windows launched from the expanded command panel must paint above the
   panel itself. Their normal map z-index is intentionally lower than the full
   command window, which otherwise makes Town/Opponent/VP dialogs look as if
   their buttons did nothing. Commander and mod-system windows are included so
   every conditional rail tool follows the same rule.
   The commander LEVEL-UP backdrop is deliberately NOT in this list: it now
   portals to <body> at a flat z-index 236, and re-stating 230 here would only
   LOWER it while the rail is expanded. */
body:has(.leftRailExpanded) .townWindowBackdrop,
body:has(.leftRailExpanded) .opponentInfoBackdrop,
body:has(.leftRailExpanded) .vpStandingsBackdrop,
body:has(.leftRailExpanded) .heroSystemBackdrop,
body:has(.leftRailExpanded) .commanderEquipmentBackdrop {
  z-index: 230;
}

body:has(.leftRailExpanded) .commanderEquipmentBackdrop {
  z-index: 235;
}

