/* -------------------------------------------------------------------------
   Setup scene final composition

   The painted plate is the menu. These rules remove the old in-flow lobby
   furniture from the composition and leave only the real button hit areas,
   compact status controls, the event-log pill, and the ready action.
--------------------------------------------------------------------------- */

.setupPhase > .tableTopRow {
  position: fixed;
  z-index: 12;
  inset: 8px 10px auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
}

.setupPhase > .tableTopRow > .advHud,
.setupPhase > .tableTopRow > .tableMenu {
  pointer-events: auto;
}

.setupPhase > .tableTopRow > .advHud {
  flex: 0 0 auto;
  min-height: 0;
  width: auto;
  padding: 5px 9px;
  border-radius: 7px;
  background: rgb(20 14 8 / 78%);
  box-shadow: 0 5px 16px rgb(0 0 0 / 38%);
}

.setupPhase > .tableTopRow > .advHud .advHudCell {
  padding: 0;
  border: 0;
}

.setupPhase > .tableTopRow > .advHud .advHudCell strong {
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.setupPhase > .tableTopRow > .advHud .advHudCell small {
  display: none;
}

.setupPhase > .tableTopRow > .tableMenu {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 4px;
  width: auto;
  min-width: 0;
  max-width: min(360px, calc(100vw - 20px));
  padding: 3px;
  border-radius: 7px;
  background: rgb(18 13 8 / 82%);
  box-shadow: 0 5px 16px rgb(0 0 0 / 40%);
  backdrop-filter: blur(4px);
}

.setupPhase > .tableTopRow > .tableMenu > .statusRow,
.setupPhase > .tableTopRow > .tableMenu > .gameControlsRow {
  display: none;
}

/* Ranked/closed setup must expose seating directly. Hiding `.seatLocked` here
   left every non-creator as an observer with no way to enter map preparation,
   which in turn meant they never received the ready-check Confirm button. */
.setupPhase > .tableTopRow > .tableMenu > .seatLocked {
  display: flex;
  min-height: 24px;
  max-width: min(520px, calc(100vw - 118px));
  padding: 3px 5px;
  gap: 4px;
  border-color: rgb(203 158 78 / 48%);
  border-radius: 5px;
  background: linear-gradient(180deg, rgb(35 20 7 / 88%), rgb(18 9 3 / 92%));
  box-shadow: 0 2px 8px rgb(0 0 0 / 34%);
  color: #ead9b5;
  font-size: 9px;
  line-height: 1;
}

.setupPhase > .tableTopRow > .tableMenu > .seatLocked .seatClaimButton {
  min-height: 20px;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 9px;
  line-height: 1;
}

.setupPhase > .tableTopRow > .tableMenu > .seatLocked .seatClaimHint {
  line-height: 1.25;
}

.setupPhase > .tableTopRow > .tableMenu > .roomPanel {
  position: relative;
  display: block;
  width: auto;
  min-width: 0;
  flex: 0 0 auto;
}

.setupPhase > .tableTopRow > .tableMenu .roomToggle {
  min-height: 25px;
  padding: 3px 7px;
  border-radius: 5px;
  background: rgb(31 22 12 / 82%);
  font-size: 10px;
}

.setupPhase > .tableTopRow > .tableMenu .roomToggleMeta {
  font-size: 9px;
}

.setupPhase > .tableTopRow > .tableMenu .roomBody {
  position: absolute;
  top: calc(100% + 5px);
  right: 0;
  z-index: 20;
  width: min(300px, calc(100vw - 20px));
  max-height: min(48vh, 360px);
  overflow: auto;
  padding: 6px;
  gap: 6px;
  border-radius: 7px;
  background: rgb(18 13 8 / 96%);
}

.setupPhase > .setupLobby {
  position: fixed;
  z-index: 1;
  inset: 46px 0 0;
  display: block;
  width: auto;
  max-width: none;
  margin: 0;
  padding: 0;
  overflow: hidden;
  pointer-events: none;
}

.setupPhase > .setupLobby > :not(.setupSceneArt) {
  pointer-events: auto;
}

.setupPhase > .setupLobby > header,
.setupPhase > .setupLobby > .lobbySeats,
.setupPhase > .setupLobby > .observerNote {
  display: none;
}

.setupPhase > .logDrawer {
  position: fixed;
  z-index: 12;
  left: 10px;
  right: auto;
  bottom: 8px;
  width: min(220px, calc(100vw - 20px));
  border-radius: 6px;
  background: rgb(18 13 8 / 82%);
  box-shadow: 0 5px 16px rgb(0 0 0 / 40%);
  pointer-events: auto;
}

.setupPhase > .logDrawer .logToggle {
  min-height: 26px;
  padding: 4px 7px;
  gap: 5px;
  font-size: 10px;
}

.setupPhase > .logDrawer .logToggleLatest {
  display: none;
}

.setupPhase > .logDrawer .logPopover {
  position: absolute;
  right: auto;
  bottom: calc(100% + 5px);
  left: 0;
  top: auto;
  width: min(360px, calc(100vw - 20px));
  max-height: min(46vh, 330px);
  overflow: auto;
}

.setupSceneStartButton {
  left: 44.5%;
  bottom: max(8px, env(safe-area-inset-bottom, 8px));
  width: min(190px, 22vw) !important;
  min-height: 31px;
  padding: 5px 12px;
  font-size: 12px;
}

.combatContextBanner.compact {
  justify-self: start;
  gap: 5px;
  min-height: 25px;
  padding: 3px 5px 3px 7px;
  border-radius: 7px;
  font-size: 10px;
  line-height: 1;
}

.combatContextBanner.compact > span {
  font-weight: 700;
  white-space: nowrap;
}

.combatContextBanner.compact .commandButton {
  min-height: 19px;
  padding: 2px 6px;
  gap: 3px;
  font-size: 9px;
}

.setupLobby--ready .setupSceneStartButton {
  border-color: rgb(255 225 119 / 96%);
  animation: setupStartReadyPulse 1.15s ease-in-out infinite;
}

/* The ready check is a table-wide setup decision, not an in-flow note. Keep it
   above the painted scene and centered for every seated ranked-room client. */
.setupPhase .startReadyCheck {
  position: fixed;
  z-index: 45;
  top: 88px;
  left: 50%;
  width: min(620px, calc(100vw - 24px));
  margin: 0;
  transform: translateX(-50%);
}

.setupPhase .startReadyCheckBody {
  justify-content: center;
  border-color: rgb(255 225 119 / 82%);
  background: rgb(24 14 5 / 97%);
  box-shadow:
    0 10px 30px rgb(0 0 0 / 68%),
    0 0 18px rgb(255 174 46 / 28%);
}

@keyframes setupStartReadyPulse {
  0%,
  100% {
    box-shadow:
      0 0 14px rgb(255 139 35 / 44%),
      0 0 0 1px rgb(255 219 94 / 20%),
      inset 0 0 14px rgb(255 191 68 / 18%);
  }
  50% {
    box-shadow:
      0 0 26px 7px rgb(255 174 46 / 68%),
      0 0 0 2px rgb(255 235 141 / 42%),
      inset 0 0 20px rgb(255 222 116 / 30%);
  }
}

/* Keep the open chat usable without letting it cover the painted heroes.
   NON-PHONE only: the final low-left placement below overrides this for the
   desktop scene, so its ONLY live effect used to be on PHONE MODE — where it
   dragged the collapsed chat fab down onto the fixed Start button (the fab
   intercepted every tap; the phone block's own `bottom: 76px + safe-area`
   placement is the one that keeps the bottom band clear). */
.setupPhase.adventureRoot:not(.phoneMode) .chatDock {
  left: auto;
  right: 10px;
  bottom: 8px;
}

.setupPhase.adventureRoot:not(.phoneMode) .chatPanel {
  width: min(270px, calc(100vw - 20px));
  max-height: min(35vh, 270px);
  border-radius: 9px;
}

.setupPhase .chatMessages {
